import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState } from 'react';
import { ChevronRight, ChevronDown, Folder, FileText, Plus, Edit2, Trash2, MoreVertical } from 'lucide-react';
import { BookNode, NodeType } from '../types';

interface TreeItemProps {
  node: BookNode;
  allNodes: BookNode[];
  selectedId: string | null;
  onSelect: (id: string) => void;
  onAdd: (parentId: string, type: NodeType) => void;
  onEdit: (node: BookNode) => void;
  onDelete: (id: string) => void;
  level: number;
}

const TreeItem: React.FC<TreeItemProps> = ({ 
  node, 
  allNodes, 
  selectedId, 
  onSelect, 
  onAdd, 
  onEdit, 
  onDelete,
  level 
}) => {
  const [isOpen, setIsOpen] = useState(true);
  const [showMenu, setShowMenu] = useState(false);

  const children = allNodes.filter(n => n.parentId === node.id);
  const isSelected = selectedId === node.id;

  return (
    <div className="select-none">
      <div 
        className={`group flex items-center py-2 px-2 rounded-md cursor-pointer transition-colors ${
          isSelected ? 'bg-indigo-100 text-indigo-700' : 'hover:bg-gray-100 text-gray-700'
        }`}
        style={{ paddingLeft: `${level * 1.25}rem` }}
        onClick={() => onSelect(node.id)}
      >
        <div className="flex items-center flex-1 min-w-0">
          {node.type === 'folder' ? (
            <button 
              onClick={(e) => { e.stopPropagation(); setIsOpen(!isOpen); }}
              className="p-1 hover:bg-gray-200 rounded"
            >
              {isOpen ? <ChevronDown size={16} /> : <ChevronRight size={16} />}
            </button>
          ) : (
            <div className="w-6" />
          )}

          {node.type === 'folder' ? (
            <Folder size={18} className={`mr-2 shrink-0 ${isSelected ? 'text-indigo-600' : 'text-amber-500'}`} />
          ) : (
            <FileText size={18} className={`mr-2 shrink-0 ${isSelected ? 'text-indigo-600' : 'text-blue-500'}`} />
          )}

          <span className="truncate text-sm font-medium">{node.title}</span>
        </div>

        <div className="hidden group-hover:flex items-center space-x-1 pr-1">
          {node.type === 'folder' && (
            <button 
              onClick={(e) => { e.stopPropagation(); onAdd(node.id, 'lesson'); }}
              className="p-1 hover:bg-gray-200 rounded text-gray-500"
              title="Thêm bài học"
            >
              <Plus size={14} />
            </button>
          )}
          <button 
            onClick={(e) => { e.stopPropagation(); onEdit(node); }}
            className="p-1 hover:bg-gray-200 rounded text-gray-500"
            title="Sửa"
          >
            <Edit2 size={14} />
          </button>
          <button 
            onClick={(e) => { e.stopPropagation(); onDelete(node.id); }}
            className="p-1 hover:bg-red-100 rounded text-red-500"
            title="Xóa"
          >
            <Trash2 size={14} />
          </button>
        </div>
      </div>

      {node.type === 'folder' && isOpen && children.length > 0 && (
        <div className="mt-1">
          {children.map(child => (
            <TreeItem 
              key={child.id}
              node={child}
              allNodes={allNodes}
              selectedId={selectedId}
              onSelect={onSelect}
              onAdd={onAdd}
              onEdit={onEdit}
              onDelete={onDelete}
              level={level + 1}
            />
          ))}
        </div>
      )}
    </div>
  );
};

export default TreeItem;

import React, { useState, useEffect } from 'react';
import { PlusCircle, Save, Book, ExternalLink, Link as LinkIcon, Trash2, X } from 'lucide-react';
import { BookNode, NodeType, ResourceLink, AppData } from './types';
import { INITIAL_DATA } from './constants';
import TreeItem from './components/TreeItem';

const App: React.FC = () => {
  const [data, setData] = useState<AppData>(() => {
    const saved = localStorage.getItem('teacher_app_data');
    return saved ? JSON.parse(saved) : INITIAL_DATA;
  });

  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [isEditing, setIsEditing] = useState(false);

  // Local state for the current editing node
  const [editTitle, setEditTitle] = useState('');
  const [editContent, setEditContent] = useState('');

  // Persist to "database"
  useEffect(() => {
    localStorage.setItem('teacher_app_data', JSON.stringify(data));
  }, [data]);

  const selectedNode = data.nodes.find(n => n.id === selectedId);

  const handleAddRoot = () => {
    const newNode: BookNode = {
      id: `node-${Date.now()}`,
      title: 'Chương mới',
      type: 'folder',
      content: '',
      parentId: null,
      lessonResources: []
    };
    setData(prev => ({ ...prev, nodes: [...prev.nodes, newNode] }));
    setSelectedId(newNode.id);
  };

  const handleAddChild = (parentId: string, type: NodeType) => {
    const newNode: BookNode = {
      id: `node-${Date.now()}`,
      title: type === 'folder' ? 'Chương mới' : 'Bài học mới',
      type,
      content: '',
      parentId,
      lessonResources: []
    };
    setData(prev => ({ ...prev, nodes: [...prev.nodes, newNode] }));
    setSelectedId(newNode.id);
  };

  const handleEditNode = (node: BookNode) => {
    setSelectedId(node.id);
    setEditTitle(node.title);
    setEditContent(node.content);
    setIsEditing(true);
  };

  const handleSaveNode = () => {
    if (!selectedId) return;
    setData(prev => ({
      ...prev,
      nodes: prev.nodes.map(n => 
        n.id === selectedId ? { ...n, title: editTitle, content: editContent } : n
      )
    }));
    setIsEditing(false);
  };

  const handleDeleteNode = (id: string) => {
    if (confirm('Bạn có chắc chắn muốn xóa mục này và tất cả các mục con bên trong?')) {
      const idsToDelete = new Set<string>();
      const collectIds = (targetId: string) => {
        idsToDelete.add(targetId);
        data.nodes.filter(n => n.parentId === targetId).forEach(child => collectIds(child.id));
      };
      collectIds(id);
      setData(prev => ({ ...prev, nodes: prev.nodes.filter(n => !idsToDelete.has(n.id)) }));
      if (selectedId && idsToDelete.has(selectedId)) setSelectedId(null);
    }
  };

  const handleAddLessonResource = () => {
    if (!selectedId) return;
    const title = prompt('Nhập tên tài liệu:');
    const url = prompt('Nhập link tài liệu:');
    if (title && url) {
      setData(prev => ({
        ...prev,
        nodes: prev.nodes.map(n => 
          n.id === selectedId 
            ? { ...n, lessonResources: [...n.lessonResources, { id: `res-${Date.now()}`, title, url }] }
            : n
        )
      }));
    }
  };

  const handleDeleteLessonResource = (resId: string) => {
    setData(prev => ({
      ...prev,
      nodes: prev.nodes.map(n => 
        n.id === selectedId 
          ? { ...n, lessonResources: n.lessonResources.filter(r => r.id !== resId) }
          : n
      )
    }));
  };

  const handleAddGlobalResource = () => {
    const title = prompt('Nhập tên tài liệu chung:');
    const url = prompt('Nhập link tài liệu chung:');
    if (title && url) {
      setData(prev => ({
        ...prev,
        globalResources: [...prev.globalResources, { id: `res-${Date.now()}`, title, url }]
      }));
    }
  };

  const handleDeleteGlobalResource = (resId: string) => {
    setData(prev => ({
      ...prev,
      globalResources: prev.globalResources.filter(r => r.id !== resId)
    }));
  };

  return (
    <div className="flex h-screen bg-gray-50 overflow-hidden font-sans">

      {/* PANEL 1: SIDEBAR NAVIGATION */}
      <aside className="w-80 border-r bg-white flex flex-col shadow-sm">
        <div className="p-4 border-b bg-indigo-600 flex justify-between items-center text-white">
          <div className="flex items-center space-x-2">
            <Book size={20} />
            <h2 className="font-bold text-lg">Giáo trình</h2>
          </div>
          <button 
            onClick={handleAddRoot}
            className="p-1.5 hover:bg-indigo-500 rounded-full transition-colors"
            title="Thêm chương mới"
          >
            <PlusCircle size={20} />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-4">
          {data.nodes.filter(n => n.parentId === null).map(rootNode => (
            <TreeItem 
              key={rootNode.id}
              node={rootNode}
              allNodes={data.nodes}
              selectedId={selectedId}
              onSelect={(id) => {
                setSelectedId(id);
                const n = data.nodes.find(item => item.id === id);
                if (n) {
                  setEditTitle(n.title);
                  setEditContent(n.content);
                  setIsEditing(false);
                }
              }}
              onAdd={handleAddChild}
              onEdit={handleEditNode}
              onDelete={handleDeleteNode}
              level={0}
            />
          ))}
          {data.nodes.length === 0 && (
            <p className="text-gray-400 text-center text-sm mt-10 italic">Cây thư mục chưa có nội dung</p>
          )}
        </div>
      </aside>

      {/* PANEL 2: MAIN CONTENT AREA */}
      <main className="flex-1 flex flex-col min-w-0 bg-white shadow-inner">
        {selectedNode ? (
          <>
            <header className="px-8 py-4 border-b bg-gray-50 flex justify-between items-center">
              {isEditing ? (
                <input 
                  type="text"
                  value={editTitle}
                  onChange={(e) => setEditTitle(e.target.value)}
                  className="text-2xl font-bold bg-white border border-indigo-300 rounded px-2 py-1 w-full max-w-xl focus:outline-none focus:ring-2 focus:ring-indigo-500"
                />
              ) : (
                <h1 className="text-2xl font-bold text-gray-800 truncate">{selectedNode.title}</h1>
              )}

              <div className="flex space-x-2">
                {isEditing ? (
                  <button 
                    onClick={handleSaveNode}
                    className="flex items-center space-x-2 bg-indigo-600 text-white px-4 py-2 rounded-lg hover:bg-indigo-700 transition-colors shadow-md"
                  >
                    <Save size={18} />
                    <span>Lưu bài học</span>
                  </button>
                ) : (
                  <button 
                    onClick={() => setIsEditing(true)}
                    className="flex items-center space-x-2 bg-white border border-indigo-200 text-indigo-600 px-4 py-2 rounded-lg hover:bg-indigo-50 transition-colors"
                  >
                    <Edit2 size={18} />
                    <span>Sửa bài học</span>
                  </button>
                )}
              </div>
            </header>

            <div className="flex-1 overflow-y-auto p-8 prose prose-indigo max-w-none">
              {isEditing ? (
                <textarea 
                  value={editContent}
                  onChange={(e) => setEditContent(e.target.value)}
                  placeholder="Nhập nội dung bài học ở đây (hỗ trợ Markdown)..."
                  className="w-full h-full p-4 border rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 font-mono text-sm leading-relaxed"
                />
              ) : (
                <div className="whitespace-pre-wrap leading-relaxed text-gray-700">
                  {selectedNode.content || (
                    <div className="text-gray-400 italic text-center py-20">
                      Không có nội dung cho mục này. Nhấn "Sửa bài học" để thêm nội dung.
                    </div>
                  )}
                </div>
              )}
            </div>
          </>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-gray-400 p-10">
            <Book size={64} className="mb-4 opacity-20" />
            <h2 className="text-xl font-medium">Chọn một mục từ cây thư mục để xem nội dung</h2>
          </div>
        )}
      </main>

      {/* PANEL 3: RESOURCE PANEL */}
      <aside className="w-80 border-l bg-gray-50 flex flex-col overflow-hidden">
        {/* Top Section: Lesson Specific Resources */}
        <div className="h-1/2 flex flex-col border-b">
          <div className="p-4 border-b bg-white flex justify-between items-center sticky top-0 z-10 shadow-sm">
            <h3 className="font-bold text-gray-700 flex items-center">
              <LinkIcon size={16} className="mr-2 text-indigo-500" />
              Tài liệu bài học
            </h3>
            {selectedNode && (
              <button 
                onClick={handleAddLessonResource}
                className="p-1 text-indigo-600 hover:bg-indigo-50 rounded"
              >
                <Plus size={18} />
              </button>
            )}
          </div>
          <div className="flex-1 overflow-y-auto p-4 space-y-2">
            {!selectedNode ? (
              <p className="text-xs text-gray-400 text-center py-4 italic">Hãy chọn bài học để xem tài liệu</p>
            ) : selectedNode.lessonResources.length > 0 ? (
              selectedNode.lessonResources.map(res => (
                <div key={res.id} className="group bg-white p-3 rounded border border-gray-200 shadow-sm hover:border-indigo-300 transition-all flex justify-between items-center">
                  <a href={res.url} target="_blank" rel="noreferrer" className="flex items-center text-sm text-indigo-600 hover:underline truncate mr-2">
                    <ExternalLink size={14} className="mr-2 shrink-0" />
                    <span className="truncate">{res.title}</span>
                  </a>
                  <button 
                    onClick={() => handleDeleteLessonResource(res.id)}
                    className="opacity-0 group-hover:opacity-100 p-1 text-red-400 hover:text-red-600 transition-opacity"
                  >
                    <X size={14} />
                  </button>
                </div>
              ))
            ) : (
              <p className="text-xs text-gray-400 text-center py-4 italic">Chưa có tài liệu cho bài học này</p>
            )}
          </div>
        </div>

        {/* Bottom Section: Fixed Global Resources */}
        <div className="h-1/2 flex flex-col bg-white">
          <div className="p-4 border-b bg-indigo-50 flex justify-between items-center sticky top-0 z-10">
            <h3 className="font-bold text-indigo-900 flex items-center">
              <Book size={16} className="mr-2" />
              Tài liệu chung
            </h3>
            <button 
              onClick={handleAddGlobalResource}
              className="p-1 text-indigo-600 hover:bg-white rounded"
            >
              <Plus size={18} />
            </button>
          </div>
          <div className="flex-1 overflow-y-auto p-4 space-y-2">
            {data.globalResources.length > 0 ? (
              data.globalResources.map(res => (
                <div key={res.id} className="group bg-gray-50 p-3 rounded border border-gray-200 flex justify-between items-center hover:bg-white transition-colors">
                  <a href={res.url} target="_blank" rel="noreferrer" className="flex items-center text-sm text-gray-700 hover:text-indigo-600 truncate mr-2">
                    <LinkIcon size={14} className="mr-2 shrink-0 opacity-50" />
                    <span className="truncate font-medium">{res.title}</span>
                  </a>
                  <button 
                    onClick={() => handleDeleteGlobalResource(res.id)}
                    className="opacity-0 group-hover:opacity-100 p-1 text-red-400 hover:text-red-600"
                  >
                    <X size={14} />
                  </button>
                </div>
              ))
            ) : (
              <p className="text-xs text-gray-400 text-center py-4 italic">Chưa có tài liệu chung</p>
            )}
          </div>
        </div>
      </aside>

    </div>
  );
};

export default App;

