import React, { useState, useEffect } from 'react';
import { PlusCircle, Save, Book, ExternalLink, Link as LinkIcon, Trash2, X, Lock, Unlock } from 'lucide-react';
import { BookNode, NodeType, ResourceLink, AppData } from './types';
import { INITIAL_DATA } from './constants';
import TreeItem from './components/TreeItem';

const App: React.FC = () => {
  const [data, setData] = useState<AppData>(() => {
    const saved = localStorage.getItem('teacher_app_data');
    return saved ? JSON.parse(saved) : INITIAL_DATA;
  });

  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [isAdmin, setIsAdmin] = useState(false);

  // Local state for the current editing node
  const [editTitle, setEditTitle] = useState('');
  const [editContent, setEditContent] = useState('');

  // Persist to "database"
  useEffect(() => {
    localStorage.setItem('teacher_app_data', JSON.stringify(data));
  }, [data]);

  const selectedNode = data.nodes.find(n => n.id === selectedId);

  const handleAdminToggle = () => {
    if (!isAdmin) {
      const pass = prompt('Nhập mật khẩu giáo viên (Mặc định: 1234):');
      if (pass === '1234') {
        setIsAdmin(true);
      } else {
        alert('Mật khẩu không chính xác!');
      }
    } else {
      setIsAdmin(false);
      setIsEditing(false);
    }
  };

  const handleAddRoot = () => {
    const newNode: BookNode = {
      id: `node-${Date.now()}`,
      title: 'Chương mới',
      type: 'folder',
      content: '',
      parentId: null,
      lessonResources: []
    };
    setData(prev => ({ ...prev, nodes: [...prev.nodes, newNode] }));
    setSelectedId(newNode.id);
  };

  const handleAddChild = (parentId: string, type: NodeType) => {
    const newNode: BookNode = {
      id: `node-${Date.now()}`,
      title: type === 'folder' ? 'Chương mới' : 'Bài học mới',
      type,
      content: '',
      parentId,
      lessonResources: []
    };
    setData(prev => ({ ...prev, nodes: [...prev.nodes, newNode] }));
    setSelectedId(newNode.id);
  };

  const handleEditNode = (node: BookNode) => {
    setSelectedId(node.id);
    setEditTitle(node.title);
    setEditContent(node.content);
    setIsEditing(true);
  };

  const handleSaveNode = () => {
    if (!selectedId) return;
    setData(prev => ({
      ...prev,
      nodes: prev.nodes.map(n => 
        n.id === selectedId ? { ...n, title: editTitle, content: editContent } : n
      )
    }));
    setIsEditing(false);
  };

  const handleDeleteNode = (id: string) => {
    if (confirm('Bạn có chắc chắn muốn xóa mục này và tất cả các mục con bên trong?')) {
      const idsToDelete = new Set<string>();
      const collectIds = (targetId: string) => {
        idsToDelete.add(targetId);
        data.nodes.filter(n => n.parentId === targetId).forEach(child => collectIds(child.id));
      };
      collectIds(id);
      setData(prev => ({ ...prev, nodes: prev.nodes.filter(n => !idsToDelete.has(n.id)) }));
      if (selectedId && idsToDelete.has(selectedId)) setSelectedId(null);
    }
  };

  const handleAddLessonResource = () => {
    if (!selectedId) return;
    const title = prompt('Nhập tên tài liệu:');
    const url = prompt('Nhập link tài liệu:');
    if (title && url) {
      setData(prev => ({
        ...prev,
        nodes: prev.nodes.map(n => 
          n.id === selectedId 
            ? { ...n, lessonResources: [...n.lessonResources, { id: `res-${Date.now()}`, title, url }] }
            : n
        )
      }));
    }
  };

  const handleDeleteLessonResource = (resId: string) => {
    setData(prev => ({
      ...prev,
      nodes: prev.nodes.map(n => 
        n.id === selectedId 
          ? { ...n, lessonResources: n.lessonResources.filter(r => r.id !== resId) }
          : n
      )
    }));
  };

  const handleAddGlobalResource = () => {
    const title = prompt('Nhập tên tài liệu chung:');
    const url = prompt('Nhập link tài liệu chung:');
    if (title && url) {
      setData(prev => ({
        ...prev,
        globalResources: [...prev.globalResources, { id: `res-${Date.now()}`, title, url }]
      }));
    }
  };

  const handleDeleteGlobalResource = (resId: string) => {
    setData(prev => ({
      ...prev,
      globalResources: prev.globalResources.filter(r => r.id !== resId)
    }));
  };

  return (
    <div className="flex h-screen bg-gray-50 overflow-hidden font-sans">

      {/* PANEL 1: SIDEBAR NAVIGATION */}
      <aside className="w-80 border-r bg-white flex flex-col shadow-sm">
        <div className="p-4 border-b bg-indigo-600 flex justify-between items-center text-white">
          <div className="flex items-center space-x-2">
            <Book size={20} />
            <h2 className="font-bold text-lg">Giáo trình</h2>
          </div>
          {isAdmin && (
            <button 
              onClick={handleAddRoot}
              className="p-1.5 hover:bg-indigo-500 rounded-full transition-colors"
              title="Thêm chương mới"
            >
              <PlusCircle size={20} />
            </button>
          )}
        </div>

        <div className="flex-1 overflow-y-auto p-4">
          {data.nodes.filter(n => n.parentId === null).map(rootNode => (
            <TreeItem 
              key={rootNode.id}
              node={rootNode}
              allNodes={data.nodes}
              selectedId={selectedId}
              isAdmin={isAdmin}
              onSelect={(id) => {
                setSelectedId(id);
                const n = data.nodes.find(item => item.id === id);
                if (n) {
                  setEditTitle(n.title);
                  setEditContent(n.content);
                  setIsEditing(false);
                }
              }}
              onAdd={handleAddChild}
              onEdit={handleEditNode}
              onDelete={handleDeleteNode}
              level={0}
            />
          ))}
          {data.nodes.length === 0 && (
            <p className="text-gray-400 text-center text-sm mt-10 italic">Cây thư mục chưa có nội dung</p>
          )}
        </div>

        {/* Admin Mode Toggle Area */}
        <div className="p-3 border-t bg-gray-50 flex items-center justify-center">
           <button 
            onClick={handleAdminToggle}
            className={`flex items-center space-x-2 px-3 py-1.5 rounded-full text-[10px] font-bold uppercase tracking-wider transition-all duration-300 ${
              isAdmin 
              ? 'bg-amber-100 text-amber-700 ring-1 ring-amber-300' 
              : 'bg-gray-200 text-gray-500 hover:bg-gray-300'
            }`}
           >
             {isAdmin ? <Unlock size={12} /> : <Lock size={12} />}
             <span>{isAdmin ? 'Chế độ Giáo viên' : 'Chế độ Học sinh'}</span>
           </button>
        </div>
      </aside>

      {/* PANEL 2: MAIN CONTENT AREA */}
      <main className="flex-1 flex flex-col min-w-0 bg-white shadow-inner">
        {selectedNode ? (
          <>
            <header className="px-8 py-4 border-b bg-gray-50 flex justify-between items-center h-16 shrink-0">
              {isEditing ? (
                <input 
                  type="text"
                  value={editTitle}
                  onChange={(e) => setEditTitle(e.target.value)}
                  className="text-2xl font-bold bg-white border border-indigo-300 rounded px-2 py-1 w-full max-w-xl focus:outline-none focus:ring-2 focus:ring-indigo-500"
                />
              ) : (
                <h1 className="text-2xl font-bold text-gray-800 truncate">{selectedNode.title}</h1>
              )}

              <div className="flex space-x-2">
                {isAdmin && (
                  isEditing ? (
                    <button 
                      onClick={handleSaveNode}
                      className="flex items-center space-x-2 bg-indigo-600 text-white px-4 py-2 rounded-lg hover:bg-indigo-700 transition-colors shadow-md"
                    >
                      <Save size={18} />
                      <span>Lưu bài học</span>
                    </button>
                  ) : (
                    <button 
                      onClick={() => setIsEditing(true)}
                      className="flex items-center space-x-2 bg-white border border-indigo-200 text-indigo-600 px-4 py-2 rounded-lg hover:bg-indigo-50 transition-colors"
                    >
                      <Edit2 size={18} />
                      <span>Sửa bài học</span>
                    </button>
                  )
                )}
              </div>
            </header>

            <div className="flex-1 overflow-y-auto p-8 prose prose-indigo max-w-none">
              {isEditing ? (
                <textarea 
                  value={editContent}
                  onChange={(e) => setEditContent(e.target.value)}
                  placeholder="Nhập nội dung bài học ở đây..."
                  className="w-full h-full p-4 border rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 font-mono text-sm leading-relaxed"
                />
              ) : (
                <div className="whitespace-pre-wrap leading-relaxed text-gray-700">
                  {selectedNode.content || (
                    <div className="text-gray-400 italic text-center py-20">
                      Không có nội dung cho mục này. {isAdmin && 'Nhấn "Sửa bài học" để thêm nội dung.'}
                    </div>
                  )}
                </div>
              )}
            </div>
          </>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-gray-400 p-10">
            <Book size={64} className="mb-4 opacity-20" />
            <h2 className="text-xl font-medium text-center">Chọn một mục từ cây thư mục để bắt đầu học tập</h2>
          </div>
        )}
      </main>

      {/* PANEL 3: RESOURCE PANEL - Reduced to approx 3/4 width (w-60 instead of w-80) */}
      <aside className="w-60 border-l bg-gray-50 flex flex-col overflow-hidden">
        {/* Top Section: Lesson Specific Resources */}
        <div className="h-1/2 flex flex-col border-b overflow-hidden">
          <div className="p-3 border-b bg-white flex justify-between items-center sticky top-0 z-10 shadow-sm">
            <h3 className="font-bold text-gray-700 flex items-center text-xs uppercase tracking-tight">
              <LinkIcon size={14} className="mr-2 text-indigo-500" />
              Tài liệu bài học
            </h3>
            {isAdmin && selectedNode && (
              <button 
                onClick={handleAddLessonResource}
                className="p-1 text-indigo-600 hover:bg-indigo-50 rounded"
              >
                <Plus size={16} />
              </button>
            )}
          </div>
          <div className="flex-1 overflow-y-auto p-3 space-y-2">
            {!selectedNode ? (
              <p className="text-[10px] text-gray-400 text-center py-4 italic">Chọn bài học để xem tài liệu</p>
            ) : selectedNode.lessonResources.length > 0 ? (
              selectedNode.lessonResources.map(res => (
                <div key={res.id} className="group bg-white p-2 rounded border border-gray-200 shadow-sm hover:border-indigo-300 transition-all flex justify-between items-center">
                  <a href={res.url} target="_blank" rel="noreferrer" className="flex items-center text-xs text-indigo-600 hover:underline truncate mr-1">
                    <ExternalLink size={12} className="mr-1.5 shrink-0" />
                    <span className="truncate">{res.title}</span>
                  </a>
                  {isAdmin && (
                    <button 
                      onClick={() => handleDeleteLessonResource(res.id)}
                      className="opacity-0 group-hover:opacity-100 p-0.5 text-red-400 hover:text-red-600 transition-opacity"
                    >
                      <X size={12} />
                    </button>
                  )}
                </div>
              ))
            ) : (
              <p className="text-[10px] text-gray-400 text-center py-4 italic">Chưa có tài liệu riêng</p>
            )}
          </div>
        </div>

        {/* Bottom Section: Fixed Global Resources */}
        <div className="h-1/2 flex flex-col bg-white overflow-hidden">
          <div className="p-3 border-b bg-indigo-50 flex justify-between items-center sticky top-0 z-10">
            <h3 className="font-bold text-indigo-900 flex items-center text-xs uppercase tracking-tight">
              <Book size={14} className="mr-2" />
              Tài liệu chung
            </h3>
            {isAdmin && (
              <button 
                onClick={handleAddGlobalResource}
                className="p-1 text-indigo-600 hover:bg-white rounded"
              >
                <Plus size={16} />
              </button>
            )}
          </div>
          <div className="flex-1 overflow-y-auto p-3 space-y-2">
            {data.globalResources.length > 0 ? (
              data.globalResources.map(res => (
                <div key={res.id} className="group bg-gray-50 p-2 rounded border border-gray-200 flex justify-between items-center hover:bg-white transition-colors">
                  <a href={res.url} target="_blank" rel="noreferrer" className="flex items-center text-xs text-gray-700 hover:text-indigo-600 truncate mr-1">
                    <LinkIcon size={12} className="mr-1.5 shrink-0 opacity-50" />
                    <span className="truncate font-medium">{res.title}</span>
                  </a>
                  {isAdmin && (
                    <button 
                      onClick={() => handleDeleteGlobalResource(res.id)}
                      className="opacity-0 group-hover:opacity-100 p-0.5 text-red-400 hover:text-red-600"
                    >
                      <X size={12} />
                    </button>
                  )}
                </div>
              ))
            ) : (
              <p className="text-[10px] text-gray-400 text-center py-4 italic">Chưa có tài liệu chung</p>
            )}
          </div>
        </div>
      </aside>

    </div>
  );
};

export default App;

// Helper icons needed by the tree component
const Edit2 = ({ size, className }: { size: number, className?: string }) => (
  <svg xmlns="http://www.w3.org/2000/svg" width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M17 3a2.85 2.83 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5Z"/><path d="m15 5 4 4"/></svg>
);
const Plus = ({ size, className }: { size: number, className?: string }) => (
  <svg xmlns="http://www.w3.org/2000/svg" width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M5 12h14"/><path d="M12 5v14"/></svg>
);

import React, { useState, useEffect } from 'react';
import { 
  PlusCircle, 
  Save, 
  Book, 
  ExternalLink, 
  Link as LinkIcon, 
  Trash2, 
  X, 
  Lock, 
  Unlock,
  Edit,
  Plus,
  Settings,
  User
} from 'lucide-react';
import { BookNode, NodeType, AppData } from './types';
import { INITIAL_DATA } from './constants';
import TreeItem from './components/TreeItem';

const App: React.FC = () => {
  const [data, setData] = useState<AppData>(() => {
    const saved = localStorage.getItem('teacher_app_data');
    return saved ? JSON.parse(saved) : INITIAL_DATA;
  });

  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [isAdmin, setIsAdmin] = useState(false);

  // Local state for the current editing node
  const [editTitle, setEditTitle] = useState('');
  const [editContent, setEditContent] = useState('');

  // Persist to "database"
  useEffect(() => {
    localStorage.setItem('teacher_app_data', JSON.stringify(data));
  }, [data]);

  const selectedNode = data.nodes.find(n => n.id === selectedId);

  const handleAdminToggle = () => {
    if (!isAdmin) {
      const pass = prompt('Nhập mật khẩu giáo viên (Mặc định: 1234):');
      if (pass === '1234') {
        setIsAdmin(true);
        alert('Đã chuyển sang chế độ Giáo viên!');
      } else if (pass !== null) {
        alert('Mật khẩu không chính xác!');
      }
    } else {
      if (confirm('Thoát chế độ Giáo viên?')) {
        setIsAdmin(false);
        setIsEditing(false);
      }
    }
  };

  const handleAddRoot = () => {
    const newNode: BookNode = {
      id: `node-${Date.now()}`,
      title: 'Chương mới',
      type: 'folder',
      content: '',
      parentId: null,
      lessonResources: []
    };
    setData(prev => ({ ...prev, nodes: [...prev.nodes, newNode] }));
    setSelectedId(newNode.id);
    setEditTitle(newNode.title);
    setEditContent(newNode.content);
    setIsEditing(true);
  };

  const handleAddChild = (parentId: string, type: NodeType) => {
    const newNode: BookNode = {
      id: `node-${Date.now()}`,
      title: type === 'folder' ? 'Chương mới' : 'Bài học mới',
      type,
      content: '',
      parentId,
      lessonResources: []
    };
    setData(prev => ({ ...prev, nodes: [...prev.nodes, newNode] }));
    setSelectedId(newNode.id);
    setEditTitle(newNode.title);
    setEditContent(newNode.content);
    setIsEditing(true);
  };

  const handleEditNode = (node: BookNode) => {
    setSelectedId(node.id);
    setEditTitle(node.title);
    setEditContent(node.content);
    setIsEditing(true);
  };

  const handleSaveNode = () => {
    if (!selectedId) return;
    setData(prev => ({
      ...prev,
      nodes: prev.nodes.map(n => 
        n.id === selectedId ? { ...n, title: editTitle, content: editContent } : n
      )
    }));
    setIsEditing(false);
  };

  const handleDeleteNode = (id: string) => {
    if (confirm('Bạn có chắc chắn muốn xóa mục này và tất cả các mục con bên trong?')) {
      const idsToDelete = new Set<string>();
      const collectIds = (targetId: string) => {
        idsToDelete.add(targetId);
        data.nodes.filter(n => n.parentId === targetId).forEach(child => collectIds(child.id));
      };
      collectIds(id);
      setData(prev => ({ ...prev, nodes: prev.nodes.filter(n => !idsToDelete.has(n.id)) }));
      if (selectedId && idsToDelete.has(selectedId)) setSelectedId(null);
    }
  };

  const handleAddLessonResource = () => {
    if (!selectedId) return;
    const title = prompt('Nhập tên tài liệu:');
    const url = prompt('Nhập link tài liệu:');
    if (title && url) {
      setData(prev => ({
        ...prev,
        nodes: prev.nodes.map(n => 
          n.id === selectedId 
            ? { ...n, lessonResources: [...n.lessonResources, { id: `res-${Date.now()}`, title, url }] }
            : n
        )
      }));
    }
  };

  const handleDeleteLessonResource = (resId: string) => {
    setData(prev => ({
      ...prev,
      nodes: prev.nodes.map(n => 
        n.id === selectedId 
          ? { ...n, lessonResources: n.lessonResources.filter(r => r.id !== resId) }
          : n
      )
    }));
  };

  const handleAddGlobalResource = () => {
    const title = prompt('Nhập tên tài liệu chung:');
    const url = prompt('Nhập link tài liệu chung:');
    if (title && url) {
      setData(prev => ({
        ...prev,
        globalResources: [...prev.globalResources, { id: `res-${Date.now()}`, title, url }]
      }));
    }
  };

  const handleDeleteGlobalResource = (resId: string) => {
    setData(prev => ({
      ...prev,
      globalResources: prev.globalResources.filter(r => r.id !== resId)
    }));
  };

  return (
    <div className="flex h-screen bg-gray-50 overflow-hidden font-sans">

      {/* PANEL 1: SIDEBAR NAVIGATION */}
      <aside className={`w-80 border-r bg-white flex flex-col shadow-sm transition-colors duration-300 ${isAdmin ? 'border-amber-200' : 'border-gray-200'}`}>
        <div className={`p-4 border-b flex justify-between items-center text-white transition-colors duration-300 ${isAdmin ? 'bg-amber-600' : 'bg-indigo-600'}`}>
          <div className="flex items-center space-x-2">
            <Book size={20} />
            <h2 className="font-bold text-lg">Giáo trình</h2>
          </div>
          {isAdmin && (
            <button 
              onClick={handleAddRoot}
              className="p-1.5 hover:bg-black/10 rounded-full transition-colors"
              title="Thêm chương mới"
            >
              <PlusCircle size={20} />
            </button>
          )}
        </div>

        <div className="flex-1 overflow-y-auto p-4 custom-scrollbar">
          {data.nodes.filter(n => n.parentId === null).map(rootNode => (
            <TreeItem 
              key={rootNode.id}
              node={rootNode}
              allNodes={data.nodes}
              selectedId={selectedId}
              isAdmin={isAdmin}
              onSelect={(id) => {
                setSelectedId(id);
                const n = data.nodes.find(item => item.id === id);
                if (n) {
                  setEditTitle(n.title);
                  setEditContent(n.content);
                  setIsEditing(false);
                }
              }}
              onAdd={handleAddChild}
              onEdit={handleEditNode}
              onDelete={handleDeleteNode}
              level={0}
            />
          ))}
          {data.nodes.length === 0 && (
            <p className="text-gray-400 text-center text-sm mt-10 italic">Cây thư mục trống</p>
          )}
        </div>

        {/* Admin Mode Toggle Area - Improved Visibility */}
        <div className="p-4 border-t bg-gray-50 flex flex-col items-center gap-2">
           <button 
            onClick={handleAdminToggle}
            className={`w-full flex items-center justify-center space-x-3 px-4 py-2.5 rounded-lg text-xs font-bold uppercase tracking-widest transition-all duration-300 shadow-sm ${
              isAdmin 
              ? 'bg-amber-500 text-white hover:bg-amber-600 shadow-amber-200' 
              : 'bg-white border border-gray-300 text-gray-600 hover:bg-gray-100'
            }`}
           >
             {isAdmin ? <Unlock size={14} /> : <Lock size={14} />}
             <span>{isAdmin ? 'Chế độ Giáo viên' : 'Chế độ Học sinh'}</span>
           </button>
           <div className="text-[10px] text-gray-400 flex items-center gap-1">
             {isAdmin ? <Settings size={10} /> : <User size={10} />}
             <span>{isAdmin ? 'Quyền chỉnh sửa: Bật' : 'Quyền chỉnh sửa: Tắt'}</span>
           </div>
        </div>
      </aside>

      {/* PANEL 2: MAIN CONTENT AREA */}
      <main className="flex-1 flex flex-col min-w-0 bg-white shadow-inner relative">
        {isAdmin && (
          <div className="absolute top-0 left-0 right-0 h-0.5 bg-amber-500 z-50"></div>
        )}

        {selectedNode ? (
          <>
            <header className="px-8 py-4 border-b bg-gray-50 flex justify-between items-center h-16 shrink-0">
              {isEditing ? (
                <input 
                  type="text"
                  value={editTitle}
                  onChange={(e) => setEditTitle(e.target.value)}
                  className="text-2xl font-bold bg-white border border-indigo-300 rounded px-2 py-1 w-full max-w-xl focus:outline-none focus:ring-2 focus:ring-indigo-500"
                />
              ) : (
                <h1 className="text-2xl font-bold text-gray-800 truncate">{selectedNode.title}</h1>
              )}

              <div className="flex space-x-2">
                {isAdmin && (
                  isEditing ? (
                    <button 
                      onClick={handleSaveNode}
                      className="flex items-center space-x-2 bg-indigo-600 text-white px-4 py-2 rounded-lg hover:bg-indigo-700 transition-colors shadow-md"
                    >
                      <Save size={18} />
                      <span>Lưu nội dung</span>
                    </button>
                  ) : (
                    <button 
                      onClick={() => setIsEditing(true)}
                      className="flex items-center space-x-2 bg-white border border-indigo-200 text-indigo-600 px-4 py-2 rounded-lg hover:bg-indigo-50 transition-colors"
                    >
                      <Edit size={18} />
                      <span>Sửa nội dung</span>
                    </button>
                  )
                )}
              </div>
            </header>

            <div className="flex-1 overflow-y-auto p-8 prose prose-indigo max-w-none">
              {isEditing ? (
                <textarea 
                  value={editContent}
                  onChange={(e) => setEditContent(e.target.value)}
                  placeholder="Nhập nội dung bài học ở đây..."
                  className="w-full h-full p-6 border-2 border-dashed border-indigo-100 rounded-xl focus:outline-none focus:ring-2 focus:ring-indigo-500 font-mono text-sm leading-relaxed resize-none bg-indigo-50/10"
                />
              ) : (
                <div className="whitespace-pre-wrap leading-relaxed text-gray-700 text-lg">
                  {selectedNode.content || (
                    <div className="text-gray-400 italic text-center py-20 flex flex-col items-center">
                      <Book size={48} className="mb-4 opacity-10" />
                      <p>Mục này chưa có nội dung văn bản.</p>
                      {isAdmin && <p className="text-sm mt-2">Nhấn "Sửa nội dung" để bắt đầu viết.</p>}
                    </div>
                  )}
                </div>
              )}
            </div>
          </>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-gray-300 p-10">
            <Book size={80} className="mb-6 opacity-20" />
            <h2 className="text-2xl font-semibold text-gray-400">Chọn một bài học từ menu bên trái</h2>
            <p className="mt-2 text-gray-400">Nội dung và tài liệu sẽ hiển thị tại đây.</p>
          </div>
