      {/* PANEL 3: RESOURCE PANEL - Reduced width to 60 (approx 240px) */}
      <aside className="w-60 border-l bg-gray-50 flex flex-col overflow-hidden shrink-0">
        {/* Top Section: Lesson Specific Resources */}
        <div className="h-1/2 flex flex-col border-b overflow-hidden">
          <div className="p-3 border-b bg-white flex justify-between items-center sticky top-0 z-10 shadow-sm">
            <h3 className="font-bold text-gray-700 flex items-center text-[10px] uppercase tracking-wider">
              <LinkIcon size={12} className="mr-2 text-indigo-500" />
              Tài liệu bài
            </h3>
            {isAdmin && selectedNode && (
              <button 
                onClick={handleAddLessonResource}
                className="p-1 text-indigo-600 hover:bg-indigo-50 rounded transition-colors"
                title="Thêm tài liệu bài học"
              >
                <Plus size={16} />
              </button>
            )}
          </div>
          <div className="flex-1 overflow-y-auto p-3 space-y-2 custom-scrollbar">
            {!selectedNode ? (
              <p className="text-[10px] text-gray-400 text-center py-4 italic">Chọn bài học trước</p>
            ) : selectedNode.lessonResources.length > 0 ? (
              selectedNode.lessonResources.map(res => (
                <div key={res.id} className="group bg-white p-2.5 rounded-lg border border-gray-200 shadow-sm hover:border-indigo-300 transition-all flex justify-between items-center">
                  <a href={res.url} target="_blank" rel="noreferrer" className="flex items-center text-[11px] text-indigo-600 font-medium hover:underline truncate mr-1">
                    <ExternalLink size={12} className="mr-1.5 shrink-0" />
                    <span className="truncate">{res.title}</span>
                  </a>
                  {isAdmin && (
                    <button 
                      onClick={() => handleDeleteLessonResource(res.id)}
                      className="opacity-0 group-hover:opacity-100 p-1 text-red-400 hover:text-red-600 transition-opacity"
                    >
                      <X size={12} />
                    </button>
                  )}
                </div>
              ))
            ) : (
              <p className="text-[10px] text-gray-400 text-center py-4 italic">Chưa có tài liệu</p>
            )}
          </div>
        </div>

        {/* Bottom Section: Fixed Global Resources */}
        <div className="h-1/2 flex flex-col bg-white overflow-hidden">
          <div className="p-3 border-b bg-indigo-50 flex justify-between items-center sticky top-0 z-10">
            <h3 className="font-bold text-indigo-900 flex items-center text-[10px] uppercase tracking-wider">
              <Book size={12} className="mr-2" />
              Dùng chung
            </h3>
            {isAdmin && (
              <button 
                onClick={handleAddGlobalResource}
                className="p-1 text-indigo-600 hover:bg-white rounded transition-colors"
                title="Thêm tài liệu dùng chung"
              >
                <Plus size={16} />
              </button>
            )}
          </div>
          <div className="flex-1 overflow-y-auto p-3 space-y-2 custom-scrollbar">
            {data.globalResources.length > 0 ? (
              data.globalResources.map(res => (
                <div key={res.id} className="group bg-gray-50 p-2.5 rounded-lg border border-gray-100 flex justify-between items-center hover:bg-indigo-50/30 transition-colors">
                  <a href={res.url} target="_blank" rel="noreferrer" className="flex items-center text-[11px] text-gray-600 hover:text-indigo-600 font-medium truncate mr-1">
                    <LinkIcon size={12} className="mr-1.5 shrink-0 opacity-40" />
                    <span className="truncate">{res.title}</span>
                  </a>
                  {isAdmin && (
                    <button 
                      onClick={() => handleDeleteGlobalResource(res.id)}
                      className="opacity-0 group-hover:opacity-100 p-1 text-red-400 hover:text-red-600 transition-opacity"
                    >
                      <X size={12} />
                    </button>
                  )}
                </div>
              ))
            ) : (
              <p className="text-[10px] text-gray-400 text-center py-4 italic">Chưa có tài liệu chung</p>
