export default App;

import React, { useState, useEffect } from 'react';
import { 
  PlusCircle, 
  Save, 
  Book, 
  ExternalLink, 
  Link as LinkIcon, 
  Trash2, 
  X, 
  Lock, 
  Unlock,
  Pencil,
  Plus,
  Settings,
  User,
  ChevronRight
} from 'lucide-react';
import { BookNode, NodeType, AppData } from './types';
import { INITIAL_DATA } from './constants';
import TreeItem from './components/TreeItem';

const App: React.FC = () => {
  const [data, setData] = useState<AppData>(() => {
    const saved = localStorage.getItem('teacher_app_data');
    return saved ? JSON.parse(saved) : INITIAL_DATA;
  });

  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [isAdmin, setIsAdmin] = useState(false);

  const [editTitle, setEditTitle] = useState('');
  const [editContent, setEditContent] = useState('');

  useEffect(() => {
    localStorage.setItem('teacher_app_data', JSON.stringify(data));
  }, [data]);

  const selectedNode = data.nodes.find(n => n.id === selectedId);

  const handleAdminToggle = () => {
    if (!isAdmin) {
      const pass = prompt('Nhập mật khẩu giáo viên (Mặc định: 1234):');
      if (pass === '1234') {
        setIsAdmin(true);
      } else if (pass !== null) {
        alert('Mật khẩu không chính xác!');
      }
    } else {
      if (confirm('Thoát chế độ Giáo viên?')) {
        setIsAdmin(false);
        setIsEditing(false);
      }
    }
  };

  const handleAddRoot = () => {
    const newNode: BookNode = {
      id: `node-${Date.now()}`,
      title: 'Chương mới',
      type: 'folder',
      content: '',
      parentId: null,
      lessonResources: []
    };
    setData(prev => ({ ...prev, nodes: [...prev.nodes, newNode] }));
    setSelectedId(newNode.id);
    setEditTitle(newNode.title);
    setEditContent(newNode.content);
    setIsEditing(true);
  };

  const handleAddChild = (parentId: string, type: NodeType) => {
    const newNode: BookNode = {
      id: `node-${Date.now()}`,
      title: type === 'folder' ? 'Chương mới' : 'Bài học mới',
      type,
      content: '',
      parentId,
      lessonResources: []
    };
    setData(prev => ({ ...prev, nodes: [...prev.nodes, newNode] }));
    setSelectedId(newNode.id);
    setEditTitle(newNode.title);
    setEditContent(newNode.content);
    setIsEditing(true);
  };

  const handleEditNode = (node: BookNode) => {
    setSelectedId(node.id);
    setEditTitle(node.title);
    setEditContent(node.content);
    setIsEditing(true);
  };

  const handleSaveNode = () => {
    if (!selectedId) return;
    setData(prev => ({
      ...prev,
      nodes: prev.nodes.map(n => 
        n.id === selectedId ? { ...n, title: editTitle, content: editContent } : n
      )
    }));
    setIsEditing(false);
  };

  const handleDeleteNode = (id: string) => {
    if (confirm('Bạn có chắc chắn muốn xóa mục này?')) {
      const idsToDelete = new Set<string>();
      const collectIds = (targetId: string) => {
        idsToDelete.add(targetId);
        data.nodes.filter(n => n.parentId === targetId).forEach(child => collectIds(child.id));
      };
      collectIds(id);
      setData(prev => ({ ...prev, nodes: prev.nodes.filter(n => !idsToDelete.has(n.id)) }));
      if (selectedId && idsToDelete.has(selectedId)) setSelectedId(null);
    }
  };

  const handleAddLessonResource = () => {
    if (!selectedId) return;
    const title = prompt('Nhập tên tài liệu:');
    const url = prompt('Nhập link tài liệu:');
    if (title && url) {
      setData(prev => ({
        ...prev,
        nodes: prev.nodes.map(n => 
          n.id === selectedId 
            ? { ...n, lessonResources: [...n.lessonResources, { id: `res-${Date.now()}`, title, url }] }
            : n
        )
      }));
    }
  };

  const handleDeleteLessonResource = (resId: string) => {
    setData(prev => ({
      ...prev,
      nodes: prev.nodes.map(n => 
        n.id === selectedId 
          ? { ...n, lessonResources: n.lessonResources.filter(r => r.id !== resId) }
          : n
      )
    }));
  };

  const handleAddGlobalResource = () => {
    const title = prompt('Nhập tên tài liệu chung:');
    const url = prompt('Nhập link tài liệu chung:');
    if (title && url) {
      setData(prev => ({
        ...prev,
        globalResources: [...prev.globalResources, { id: `res-${Date.now()}`, title, url }]
      }));
    }
  };

  const handleDeleteGlobalResource = (resId: string) => {
    setData(prev => ({
      ...prev,
      globalResources: prev.globalResources.filter(r => r.id !== resId)
    }));
  };

  return (
    <div className="flex h-screen bg-gray-100 overflow-hidden font-sans">

      {/* PANEL 1: SIDEBAR */}
      <aside className={`w-80 border-r bg-white flex flex-col shadow-lg z-20 transition-all duration-300 ${isAdmin ? 'border-amber-300' : 'border-gray-200'}`}>
        <div className={`p-4 border-b flex justify-between items-center text-white shadow-md ${isAdmin ? 'bg-amber-600' : 'bg-indigo-600'}`}>
          <div className="flex items-center space-x-2">
            <Book size={20} />
            <h2 className="font-bold text-lg tracking-tight">Giáo trình</h2>
          </div>
          {isAdmin && (
            <button 
              onClick={handleAddRoot}
              className="p-1.5 bg-white/20 hover:bg-white/30 rounded-full transition-colors"
              title="Thêm chương mới"
            >
              <Plus size={18} />
            </button>
          )}
        </div>

        <div className="flex-1 overflow-y-auto p-4 custom-scrollbar">
          {data.nodes.filter(n => n.parentId === null).map(rootNode => (
            <TreeItem 
              key={rootNode.id}
              node={rootNode}
              allNodes={data.nodes}
              selectedId={selectedId}
              isAdmin={isAdmin}
              onSelect={(id) => {
                setSelectedId(id);
                const n = data.nodes.find(item => item.id === id);
                if (n) {
                  setEditTitle(n.title);
                  setEditContent(n.content);
                  setIsEditing(false);
                }
              }}
              onAdd={handleAddChild}
              onEdit={handleEditNode}
              onDelete={handleDeleteNode}
              level={0}
            />
          ))}
          {data.nodes.length === 0 && (
            <div className="flex flex-col items-center justify-center h-40 text-gray-400">
                <PlusCircle size={32} className="mb-2 opacity-20" />
                <p className="text-xs italic text-center">Chưa có nội dung.<br/>Vui lòng bật chế độ giáo viên để thêm.</p>
            </div>
          )}
        </div>

        {/* Footer Admin Toggle */}
        <div className="p-4 border-t bg-gray-50 flex flex-col items-center gap-3">
           <button 
            onClick={handleAdminToggle}
            className={`w-full flex items-center justify-center space-x-3 px-4 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all duration-300 shadow-sm border ${
              isAdmin 
              ? 'bg-amber-500 text-white border-amber-600 shadow-amber-200 hover:bg-amber-600 scale-[1.02]' 
              : 'bg-white text-gray-600 border-gray-200 hover:bg-gray-50'
            }`}
           >
             {isAdmin ? <Unlock size={14} className="animate-pulse" /> : <Lock size={14} />}
             <span>{isAdmin ? 'Chế độ Giáo viên' : 'Chế độ Học sinh'}</span>
           </button>
           <div className="flex items-center gap-2 text-[10px] text-gray-400">
             {isAdmin ? <Settings size={10} /> : <User size={10} />}
             <span className="font-medium">{isAdmin ? 'CÓ QUYỀN CHỈNH SỬA' : 'CHỈ XEM NỘI DUNG'}</span>
           </div>
        </div>
      </aside>

      {/* PANEL 2: CONTENT */}
      <main className="flex-1 flex flex-col min-w-0 bg-white relative">
        {isAdmin && <div className="absolute top-0 left-0 right-0 h-1 bg-amber-500 z-30"></div>}

        {selectedNode ? (
          <>
            <header className="px-8 py-4 border-b bg-white flex justify-between items-center h-16 shrink-0 z-10 shadow-sm">
              {isEditing ? (
                <input 
                  type="text"
                  value={editTitle}
                  onChange={(e) => setEditTitle(e.target.value)}
                  className="text-xl font-bold bg-gray-50 border border-indigo-200 rounded-lg px-3 py-1.5 w-full max-w-xl focus:outline-none focus:ring-2 focus:ring-amber-400"
                />
              ) : (
                <div className="flex items-center space-x-3 truncate">
                    <div className={`p-2 rounded-lg ${selectedNode.type === 'folder' ? 'bg-amber-100 text-amber-600' : 'bg-blue-100 text-blue-600'}`}>
                        {selectedNode.type === 'folder' ? <Book size={18}/> : <ChevronRight size={18}/>}
                    </div>
                    <h1 className="text-xl font-bold text-gray-800 truncate">{selectedNode.title}</h1>
                </div>
              )}

              <div className="flex space-x-2">
                {isAdmin && (
                  isEditing ? (
                    <button 
                      onClick={handleSaveNode}
                      className="flex items-center space-x-2 bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700 transition-all font-bold text-sm shadow-md"
                    >
                      <Save size={16} />
                      <span>Lưu lại</span>
                    </button>
                  ) : (
                    <button 
                      onClick={() => setIsEditing(true)}
                      className="flex items-center space-x-2 bg-amber-50 border border-amber-200 text-amber-700 px-4 py-2 rounded-lg hover:bg-amber-100 transition-all font-bold text-sm"
                    >
                      <Pencil size={16} />
                      <span>Sửa bài học</span>
                    </button>
                  )
                )}
              </div>
            </header>

            <div className="flex-1 overflow-y-auto p-10 custom-scrollbar">
              {isEditing ? (
                <div className="h-full flex flex-col space-y-4">
                    <textarea 
                    value={editContent}
                    onChange={(e) => setEditContent(e.target.value)}
                    placeholder="Nhập nội dung bài học ở đây..."
                    className="flex-1 p-8 border-2 border-dashed border-gray-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-amber-500 font-mono text-sm leading-relaxed resize-none bg-gray-50/50"
                    />
                    <p className="text-[10px] text-gray-400">Nội dung tự động lưu vào bộ nhớ tạm thời.</p>
                </div>
              ) : (
                <div className="max-w-4xl mx-auto">
                    <div className="whitespace-pre-wrap leading-relaxed text-gray-700 text-lg">
                    {selectedNode.content || (
                        <div className="text-gray-400 italic text-center py-24 flex flex-col items-center border-2 border-dashed border-gray-100 rounded-3xl">
                            <Book size={64} className="mb-4 opacity-5" />
                            <p className="text-xl">Bài học này chưa có nội dung text.</p>
                            {isAdmin && <button onClick={() => setIsEditing(true)} className="mt-4 text-amber-600 font-bold hover:underline">Nhấn vào đây để bắt đầu soạn bài</button>}
                        </div>
                    )}
                    </div>
                </div>
              )}
            </div>
          </>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-gray-300 p-10">
            <div className="relative">
                <Book size={100} className="mb-6 opacity-10" />
                <div className="absolute -right-2 -top-2 bg-indigo-500 text-white p-2 rounded-full animate-bounce">
                    <ChevronRight size={20} />
                </div>
            </div>
            <h2 className="text-2xl font-bold text-gray-400">Sẵn sàng để học tập?</h2>
            <p className="mt-2 text-gray-400 max-w-xs text-center">Hãy chọn một chương hoặc bài học từ menu bên trái để bắt đầu khám phá kiến thức.</p>
          </div>
        )}
      </main>

      {/* PANEL 3: RESOURCES (Smaller width w-60) */}
      <aside className="w-60 border-l bg-gray-50 flex flex-col overflow-hidden shrink-0 shadow-inner">
        {/* Dynamic Lesson Resources */}
        <div className="h-1/2 flex flex-col border-b overflow-hidden">
          <div className="p-4 border-b bg-white flex justify-between items-center sticky top-0 z-10">
            <h3 className="font-bold text-gray-700 flex items-center text-[10px] uppercase tracking-widest">
              <LinkIcon size={12} className="mr-2 text-indigo-500" />
              Tài liệu bài
            </h3>
            {isAdmin && selectedNode && (
              <button 
                onClick={handleAddLessonResource}
                className="p-1 text-amber-600 hover:bg-amber-50 rounded-full transition-colors"
                title="Thêm tài liệu bài học"
              >
                <Plus size={16} />
              </button>
            )}
          </div>
          <div className="flex-1 overflow-y-auto p-4 space-y-3 custom-scrollbar">
            {!selectedNode ? (
              <p className="text-[10px] text-gray-400 text-center py-8 italic">Chọn bài học</p>
            ) : selectedNode.lessonResources.length > 0 ? (
              selectedNode.lessonResources.map(res => (
                <div key={res.id} className="group bg-white p-3 rounded-xl border border-gray-200 shadow-sm hover:border-indigo-300 transition-all flex justify-between items-center">
                  <a href={res.url} target="_blank" rel="noreferrer" className="flex items-center text-[11px] text-indigo-600 font-bold hover:underline truncate mr-1">
                    <ExternalLink size={12} className="mr-2 shrink-0 opacity-70" />
                    <span className="truncate">{res.title}</span>
                  </a>
                  {isAdmin && (
                    <button 
                      onClick={() => handleDeleteLessonResource(res.id)}
                      className="opacity-0 group-hover:opacity-100 p-1 text-red-400 hover:text-red-600 transition-opacity"
                    >
                      <X size={12} />
                    </button>
                  )}
                </div>
              ))
            ) : (
              <p className="text-[10px] text-gray-400 text-center py-8 italic">Chưa có link</p>
            )}
          </div>
        </div>

        {/* Global Fixed Resources */}
        <div className="h-1/2 flex flex-col bg-white overflow-hidden">
          <div className="p-4 border-b bg-indigo-50 flex justify-between items-center sticky top-0 z-10">
            <h3 className="font-bold text-indigo-900 flex items-center text-[10px] uppercase tracking-widest">
              <Book size={12} className="mr-2" />
              Học liệu chung
            </h3>
            {isAdmin && (
              <button 
                onClick={handleAddGlobalResource}
                className="p-1 text-indigo-600 hover:bg-white rounded-full transition-colors"
                title="Thêm học liệu chung"
              >
                <Plus size={16} />
              </button>
            )}
          </div>
          <div className="flex-1 overflow-y-auto p-4 space-y-3 custom-scrollbar">
            {data.globalResources.length > 0 ? (
              data.globalResources.map(res => (
                <div key={res.id} className="group bg-gray-50 p-3 rounded-xl border border-gray-100 flex justify-between items-center hover:bg-indigo-50/50 transition-all">
                  <a href={res.url} target="_blank" rel="noreferrer" className="flex items-center text-[11px] text-gray-700 hover:text-indigo-600 font-bold truncate mr-1">
                    <LinkIcon size={12} className="mr-2 shrink-0 opacity-30" />
                    <span className="truncate">{res.title}</span>
                  </a>
                  {isAdmin && (
                    <button 
                      onClick={() => handleDeleteGlobalResource(res.id)}
                      className="opacity-0 group-hover:opacity-100 p-1 text-red-400 hover:text-red-600"
                    >
                      <X size={12} />
                    </button>
                  )}
                </div>
              ))
            ) : (
              <p className="text-[10px] text-gray-400 text-center py-8 italic">Đang trống</p>
            )}
          </div>
        </div>
      </aside>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 5px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #e5e7eb; border-radius: 10px; }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #d1d5db; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { ChevronRight, ChevronDown, Folder, FileText, Plus, Pencil, Trash2 } from 'lucide-react';
import { BookNode, NodeType } from '../types';

interface TreeItemProps {
  node: BookNode;
  allNodes: BookNode[];
  selectedId: string | null;
  isAdmin: boolean;
  onSelect: (id: string) => void;
  onAdd: (parentId: string, type: NodeType) => void;
  onEdit: (node: BookNode) => void;
  onDelete: (id: string) => void;
  level: number;
}

const TreeItem: React.FC<TreeItemProps> = ({ 
  node, 
  allNodes, 
  selectedId, 
  isAdmin,
  onSelect, 
  onAdd, 
  onEdit, 
  onDelete,
  level 
}) => {
  const [isOpen, setIsOpen] = useState(true);

  const children = allNodes.filter(n => n.parentId === node.id);
  const isSelected = selectedId === node.id;

  return (
    <div className="select-none mb-0.5">
      <div 
        className={`group flex items-center py-2.5 px-3 rounded-xl cursor-pointer transition-all duration-200 ${
          isSelected 
            ? 'bg-indigo-50 border border-indigo-100 text-indigo-700 shadow-sm' 
            : 'hover:bg-gray-50 text-gray-600'
        }`}
        style={{ marginLeft: `${level * 0.75}rem` }}
        onClick={() => onSelect(node.id)}
      >
        <div className="flex items-center flex-1 min-w-0">
          {node.type === 'folder' ? (
            <button 
              onClick={(e) => { e.stopPropagation(); setIsOpen(!isOpen); }}
              className={`p-1 mr-1 rounded-md hover:bg-black/5 transition-colors ${isSelected ? 'text-indigo-600' : 'text-gray-400'}`}
            >
              {isOpen ? <ChevronDown size={14} strokeWidth={3} /> : <ChevronRight size={14} strokeWidth={3} />}
            </button>
          ) : (
            <div className="w-5" />
          )}

          {node.type === 'folder' ? (
            <Folder size={16} className={`mr-2 shrink-0 ${isSelected ? 'text-indigo-500' : 'text-amber-400'}`} fill={isSelected ? 'currentColor' : 'none'} fillOpacity={0.1} />
          ) : (
            <FileText size={16} className={`mr-2 shrink-0 ${isSelected ? 'text-indigo-500' : 'text-blue-400'}`} />
          )}

          <span className={`truncate text-sm ${isSelected ? 'font-bold' : 'font-medium'}`}>{node.title}</span>
        </div>

        {isAdmin && (
          <div className="hidden group-hover:flex items-center space-x-1 ml-2">
            {node.type === 'folder' && (
              <button 
                onClick={(e) => { e.stopPropagation(); onAdd(node.id, 'lesson'); }}
                className="p-1 hover:bg-indigo-100 rounded-lg text-indigo-500 transition-colors"
                title="Thêm bài học"
              >
                <Plus size={14} />
              </button>
            )}
            <button 
              onClick={(e) => { e.stopPropagation(); onEdit(node); }}
              className="p-1 hover:bg-amber-100 rounded-lg text-amber-500 transition-colors"
              title="Sửa tên"
            >
              <Pencil size={14} />
            </button>
            <button 
              onClick={(e) => { e.stopPropagation(); onDelete(node.id); }}
              className="p-1 hover:bg-red-100 rounded-lg text-red-500 transition-colors"
              title="Xóa"
            >
              <Trash2 size={14} />
            </button>
          </div>
        )}
      </div>

      {node.type === 'folder' && isOpen && children.length > 0 && (
        <div className="mt-1 relative">
          <div className="absolute left-4 top-0 bottom-2 w-px bg-gray-100"></div>
          {children.map(child => (
            <TreeItem 
              key={child.id}
              node={child}
              allNodes={allNodes}
              selectedId={selectedId}
              isAdmin={isAdmin}
              onSelect={onSelect}
              onAdd={onAdd}
              onEdit={onEdit}
              onDelete={onDelete}
              level={level + 1}
            />
          ))}
        </div>
      )}
    </div>
  );
};

