                    <span className="truncate">{res.title}</span>
                  </a>
                  {isAdmin && (
                    <button 
                      onClick={() => handleDeleteGlobalResource(res.id)}
                      className="opacity-0 group-hover:opacity-100 p-1 text-red-400 hover:text-red-600"
                    >
                      <X size={12} />
                    </button>
                  )}
                </div>
              ))
            ) : (
              <p className="text-[10px] text-gray-400 text-center py-8 italic font-medium">Chưa có link chung</p>
            )}
          </div>
        </div>
      </aside>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 5px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #94a3b8; }
      `}</style>
    </div>
  );
};

