            <div className="p-6">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-xl font-bold text-gray-800 flex items-center">
                  <ShieldCheck className="mr-2 text-amber-500" />
                  Xác minh Giáo viên
                </h3>
                <button onClick={() => setShowPassModal(false)} className="text-gray-400 hover:text-gray-600">
                  <X size={24} />
                </button>
              </div>

              <form onSubmit={verifyPassword}>
                <p className="text-sm text-gray-500 mb-4">Vui lòng nhập mật khẩu để truy cập quyền chỉnh sửa bài học (Mặc định: 1234).</p>
                <div className="relative mb-6">
                  <input 
                    type="password"
                    autoFocus
                    value={passInput}
                    onChange={(e) => { setPassInput(e.target.value); setPassError(false); }}
                    className={`w-full px-4 py-3 bg-gray-50 border-2 rounded-xl focus:outline-none transition-all ${passError ? 'border-red-400 focus:ring-red-100' : 'border-gray-100 focus:border-amber-400 focus:ring-amber-50'}`}
                    placeholder="••••"
                  />
                  {passError && (
                    <div className="mt-2 text-red-500 text-xs flex items-center font-bold">
                      <AlertCircle size={14} className="mr-1" /> Mật khẩu không đúng!
                    </div>
                  )}
                </div>

                <div className="flex gap-3">
                  <button 
                    type="button"
                    onClick={() => setShowPassModal(false)}
                    className="flex-1 py-3 text-sm font-bold text-gray-500 bg-gray-100 rounded-xl hover:bg-gray-200 transition-colors"
                  >
                    Hủy bỏ
                  </button>
                  <button 
                    type="submit"
                    className="flex-1 py-3 text-sm font-bold text-white bg-amber-500 rounded-xl hover:bg-amber-600 shadow-lg shadow-amber-200 transition-all active:scale-95"
                  >
                    Xác nhận
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}

      {/* PANEL 1: SIDEBAR */}
      <aside className={`w-80 border-r bg-white flex flex-col shadow-lg z-20 transition-all duration-300 ${isAdmin ? 'border-amber-300 ring-4 ring-amber-50' : 'border-gray-200'}`}>
        <div className={`p-5 border-b flex justify-between items-center text-white shadow-md transition-colors duration-500 ${isAdmin ? 'bg-amber-600' : 'bg-indigo-600'}`}>
          <div className="flex items-center space-x-2">
            <Book size={24} />
            <h2 className="font-black text-xl tracking-tight uppercase">Sách bài học</h2>
          </div>
          {isAdmin && (
            <button 
              onClick={handleAddRoot}
              className="p-1.5 bg-white/20 hover:bg-white/40 rounded-full transition-all active:scale-90"
              title="Thêm chương mới"
            >
              <Plus size={20} />
            </button>
          )}
        </div>

        <div className="flex-1 overflow-y-auto p-4 custom-scrollbar bg-white">
          {data.nodes.filter(n => n.parentId === null).map(rootNode => (
            <TreeItem 
              key={rootNode.id}
              node={rootNode}
              allNodes={data.nodes}
              selectedId={selectedId}
              isAdmin={isAdmin}
              onSelect={(id) => {
                setSelectedId(id);
                const n = data.nodes.find(item => item.id === id);
                if (n) {
                  setEditTitle(n.title);
                  setEditContent(n.content);
                  setIsEditing(false);
                }
              }}
              onAdd={handleAddChild}
              onEdit={handleEditNode}
              onDelete={handleDeleteNode}
              level={0}
            />
          ))}
          {data.nodes.length === 0 && (
            <div className="flex flex-col items-center justify-center h-48 text-gray-300">
                <PlusCircle size={48} className="mb-3 opacity-10" />
                <p className="text-xs font-bold text-center uppercase tracking-widest">Danh mục trống</p>
            </div>
          )}
        </div>

        {/* Footer Toggle Mode */}
        <div className="p-4 border-t bg-gray-50 flex flex-col items-center gap-3">
           <button 
            onClick={handleToggleClick}
            className={`w-full flex items-center justify-center space-x-3 px-4 py-4 rounded-2xl text-xs font-black uppercase tracking-[0.1em] transition-all duration-300 shadow-md border-2 ${
              isAdmin 
              ? 'bg-amber-500 text-white border-amber-600 shadow-amber-200 hover:bg-amber-600' 
              : 'bg-white text-indigo-600 border-indigo-100 hover:border-indigo-300 hover:bg-indigo-50 active:scale-95'
            }`}
           >
             {isAdmin ? <Unlock size={16} /> : <Lock size={16} />}
             <span>{isAdmin ? 'Thoát quyền GV' : 'Vào chế độ GV'}</span>
           </button>
           <div className={`flex items-center gap-2 text-[10px] font-black uppercase tracking-widest ${isAdmin ? 'text-amber-600' : 'text-gray-400'}`}>
             {isAdmin ? <Settings size={12} /> : <User size={12} />}
             <span>{isAdmin ? 'Đang là GIÁO VIÊN' : 'Đang là HỌC SINH'}</span>
           </div>
        </div>
      </aside>

      {/* PANEL 2: CONTENT AREA */}
      <main className="flex-1 flex flex-col min-w-0 bg-white relative">
        {isAdmin && <div className="absolute top-0 left-0 right-0 h-1.5 bg-amber-500 z-30 animate-pulse"></div>}

        {selectedNode ? (
          <>
            <header className="px-8 py-4 border-b bg-white flex justify-between items-center h-20 shrink-0 z-10 shadow-sm">
              {isEditing ? (
                <div className="flex-1 max-w-2xl mr-4">
                  <label className="text-[10px] font-bold text-amber-600 uppercase mb-1 block">Tên đề mục</label>
                  <input 
                    type="text"
                    value={editTitle}
                    onChange={(e) => setEditTitle(e.target.value)}
                    className="text-xl font-bold bg-amber-50/50 border-2 border-amber-100 rounded-xl px-4 py-2 w-full focus:outline-none focus:border-amber-400 transition-all"
                  />
                </div>
              ) : (
                <div className="flex items-center space-x-4 truncate">
                    <div className={`p-3 rounded-2xl shadow-sm ${selectedNode.type === 'folder' ? 'bg-amber-100 text-amber-600' : 'bg-blue-100 text-blue-600'}`}>
                        {selectedNode.type === 'folder' ? <Book size={20}/> : <ChevronRight size={20}/>}
                    </div>
                    <h1 className="text-2xl font-black text-gray-800 truncate tracking-tight">{selectedNode.title}</h1>
                </div>
              )}

              <div className="flex space-x-3">
                {isAdmin && (
                  isEditing ? (
                    <button 
                      onClick={handleSaveNode}
                      className="flex items-center space-x-2 bg-emerald-500 text-white px-6 py-3 rounded-xl hover:bg-emerald-600 transition-all font-black text-sm shadow-lg shadow-emerald-100 active:scale-95"
                    >
                      <Save size={18} />
                      <span>LƯU BÀI</span>
                    </button>
                  ) : (
                    <button 
                      onClick={() => setIsEditing(true)}
                      className="flex items-center space-x-2 bg-amber-50 border-2 border-amber-100 text-amber-700 px-6 py-3 rounded-xl hover:bg-amber-100 transition-all font-black text-sm active:scale-95"
                    >
                      <Pencil size={18} />
                      <span>SỬA NỘI DUNG</span>
                    </button>
                  )
                )}
              </div>
            </header>

            <div className="flex-1 overflow-y-auto p-12 custom-scrollbar bg-gray-50/30">
              {isEditing ? (
                <div className="h-full max-w-5xl mx-auto flex flex-col space-y-4">
                    <label className="text-[10px] font-bold text-amber-600 uppercase block">Soạn thảo văn bản</label>
                    <textarea 
                      value={editContent}
                      onChange={(e) => setEditContent(e.target.value)}
                      placeholder="Gõ nội dung bài học tại đây..."
                      className="flex-1 p-10 border-2 border-dashed border-gray-200 rounded-3xl focus:outline-none focus:ring-4 focus:ring-amber-100 focus:border-amber-400 font-mono text-base leading-relaxed resize-none bg-white shadow-inner transition-all"
                    />
                </div>
              ) : (
                <div className="max-w-4xl mx-auto bg-white p-12 rounded-[32px] shadow-sm border border-gray-100 min-h-[500px]">
                    <div className="whitespace-pre-wrap leading-loose text-gray-700 text-lg">
                    {selectedNode.content || (
                        <div className="text-gray-300 italic text-center py-32 flex flex-col items-center">
                            <Book size={80} className="mb-6 opacity-5" />
                            <p className="text-2xl font-bold opacity-20">Nội dung trống</p>
                            {isAdmin && <button onClick={() => setIsEditing(true)} className="mt-6 bg-amber-500 text-white px-6 py-3 rounded-2xl font-black shadow-lg shadow-amber-100 hover:scale-105 transition-all">SOẠN BÀI NGAY</button>}
                        </div>
                    )}
                    </div>
                </div>
              )}
            </div>
          </>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-gray-300 p-10 bg-gray-50/30">
            <div className="relative mb-10">
                <Book size={120} className="opacity-10 text-indigo-900" />
                <div className="absolute -right-4 -top-4 bg-indigo-500 text-white p-4 rounded-3xl shadow-xl animate-bounce">
                    <ChevronRight size={32} strokeWidth={3} />
                </div>
            </div>
            <h2 className="text-3xl font-black text-gray-400 tracking-tighter uppercase">Chọn một đề mục</h2>
            <p className="mt-4 text-gray-400 max-w-sm text-center font-medium leading-relaxed">Hãy chọn một chương hoặc bài học từ danh sách bên trái để bắt đầu khám phá nội dung.</p>
          </div>
        )}
      </main>

      {/* PANEL 3: RESOURCES */}
      <aside className="w-60 border-l bg-gray-50 flex flex-col overflow-hidden shrink-0 shadow-inner">
        {/* Lesson Specific Resources */}
        <div className="h-1/2 flex flex-col border-b overflow-hidden">
          <div className="p-4 border-b bg-white flex justify-between items-center sticky top-0 z-10 shadow-sm">
            <h3 className="font-black text-gray-500 flex items-center text-[10px] uppercase tracking-widest">
              <LinkIcon size={14} className="mr-2 text-indigo-500" />
              Tài liệu bài này
            </h3>
            {isAdmin && selectedNode && (
              <button 
                onClick={() => handleAddResource(false)}
                className="p-1.5 text-amber-600 hover:bg-amber-50 rounded-lg transition-all active:scale-90"
                title="Thêm link"
              >
                <Plus size={18} strokeWidth={3} />
              </button>
            )}
          </div>
          <div className="flex-1 overflow-y-auto p-4 space-y-3 custom-scrollbar">
            {!selectedNode ? (
              <div className="text-[10px] text-gray-300 text-center py-10 font-bold uppercase tracking-tighter italic">Chưa chọn bài</div>
            ) : selectedNode.lessonResources.length > 0 ? (
              selectedNode.lessonResources.map(res => (
                <div key={res.id} className="group bg-white p-3.5 rounded-2xl border border-gray-100 shadow-sm hover:border-indigo-300 hover:shadow-md transition-all flex justify-between items-center">
                  <a href={res.url} target="_blank" rel="noreferrer" className="flex items-center text-[11px] text-indigo-600 font-black hover:underline truncate mr-1">
                    <ExternalLink size={12} className="mr-2 shrink-0 opacity-60" />
                    <span className="truncate">{res.title}</span>
                  </a>
                  {isAdmin && (
                    <button 
                      onClick={() => handleDeleteResource(res.id, false)}
                      className="opacity-0 group-hover:opacity-100 p-1 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all"
                    >
                      <X size={14} />
                    </button>
                  )}
                </div>
              ))
            ) : (
              <div className="text-[10px] text-gray-300 text-center py-10 italic">Không có link riêng</div>
            )}
          </div>
        </div>

        {/* Global Resources */}
        <div className="h-1/2 flex flex-col bg-white overflow-hidden">
          <div className="p-4 border-b bg-indigo-50 flex justify-between items-center sticky top-0 z-10 shadow-sm">
            <h3 className="font-black text-indigo-900 flex items-center text-[10px] uppercase tracking-widest">
              <Settings size={14} className="mr-2" />
              Tài liệu chung
            </h3>
            {isAdmin && (
              <button 
                onClick={() => handleAddResource(true)}
                className="p-1.5 text-indigo-600 hover:bg-white rounded-lg transition-all active:scale-90"
                title="Thêm link chung"
              >
                <Plus size={18} strokeWidth={3} />
              </button>
            )}
          </div>
          <div className="flex-1 overflow-y-auto p-4 space-y-3 custom-scrollbar">
            {data.globalResources.length > 0 ? (
              data.globalResources.map(res => (
                <div key={res.id} className="group bg-gray-50/50 p-3.5 rounded-2xl border border-gray-100 flex justify-between items-center hover:bg-indigo-50/50 transition-all">
                  <a href={res.url} target="_blank" rel="noreferrer" className="flex items-center text-[11px] text-gray-700 hover:text-indigo-600 font-bold truncate mr-1">
                    <LinkIcon size={12} className="mr-2 shrink-0 opacity-30" />
                    <span className="truncate tracking-tight">{res.title}</span>
                  </a>
                  {isAdmin && (
                    <button 
                      onClick={() => handleDeleteResource(res.id, true)}
                      className="opacity-0 group-hover:opacity-100 p-1 text-red-400 hover:text-red-600 transition-all"
                    >
                      <X size={14} />
                    </button>
                  )}
                </div>
              ))
            ) : (
              <div className="text-[10px] text-gray-300 text-center py-10 italic uppercase font-bold tracking-widest">Trống</div>
            )}
          </div>
        </div>
      </aside>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 6px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; border: 2px solid transparent; background-clip: content-box; }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #cbd5e1; background-clip: content-box; }
      `}</style>
    </div>
  );
};

export default App;

