      ]
    },
    {
      id: 'root-2',
      title: 'Chương 2: Tài liệu tham khảo',
      type: 'folder',
      url: '',
      parentId: null,
      lessonResources: []
    },
    {
      id: 'lesson-2-1',
      title: 'Bài 2: Tài liệu HTML (MDN)',
      type: 'lesson',
      url: 'https://developer.mozilla.org/en-US/docs/Web/HTML',
      parentId: 'root-2',
      lessonResources: []
    }
  ],
  globalResources: [
    { id: 'g-1', title: 'Thư viện trực tuyến', url: 'https://archive.org' },
