import React, { useState, useEffect, useCallback } from 'react';
import { 
  PlusCircle, 
  Save, 
  Book, 
  ExternalLink, 
  Link as LinkIcon, 
  Trash2, 
  X, 
  Lock, 
  Unlock,
  Pencil,
  Plus,
  Settings,
  User,
  ChevronRight,
  ShieldCheck,
  AlertCircle,
  Globe,
  Maximize2
} from 'lucide-react';
import { BookNode, NodeType, AppData } from './types';
import { INITIAL_DATA } from './constants';
import TreeItem from './components/TreeItem';

const App: React.FC = () => {
  const [data, setData] = useState<AppData>(() => {
    const saved = localStorage.getItem('teacher_app_data_v2');
    return saved ? JSON.parse(saved) : INITIAL_DATA;
  });

  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [isAdmin, setIsAdmin] = useState(false);

  const [showPassModal, setShowPassModal] = useState(false);
  const [passInput, setPassInput] = useState('');
  const [passError, setPassError] = useState(false);

  const [editTitle, setEditTitle] = useState('');
  const [editUrl, setEditUrl] = useState('');

  useEffect(() => {
    localStorage.setItem('teacher_app_data_v2', JSON.stringify(data));
  }, [data]);

  const selectedNode = data.nodes.find(n => n.id === selectedId);

  const handleToggleClick = () => {
    if (!isAdmin) {
      setShowPassModal(true);
      setPassInput('');
      setPassError(false);
    } else {
      if (window.confirm('Bạn muốn thoát khỏi quyền Giáo viên?')) {
        setIsAdmin(false);
        setIsEditing(false);
      }
    }
  };

  const verifyPassword = (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (passInput === '1234') {
      setIsAdmin(true);
      setShowPassModal(false);
      setPassError(false);
    } else {
      setPassError(true);
    }
  };

  const handleAddRoot = () => {
    const newNode: BookNode = {
      id: `node-${Date.now()}`,
      title: 'Chương mới',
      type: 'folder',
      url: '',
      parentId: null,
      lessonResources: []
    };
    setData(prev => ({ ...prev, nodes: [...prev.nodes, newNode] }));
    setSelectedId(newNode.id);
    setEditTitle(newNode.title);
    setEditUrl(newNode.url);
    setIsEditing(true);
  };

  const handleAddChild = (parentId: string, type: NodeType) => {
    const newNode: BookNode = {
      id: `node-${Date.now()}`,
      title: type === 'folder' ? 'Chương mới' : 'Bài học mới',
      type,
      url: '',
      parentId,
      lessonResources: []
    };
    setData(prev => ({ ...prev, nodes: [...prev.nodes, newNode] }));
    setSelectedId(newNode.id);
    setEditTitle(newNode.title);
    setEditUrl(newNode.url);
    setIsEditing(true);
  };

  const handleEditNode = (node: BookNode) => {
    setSelectedId(node.id);
    setEditTitle(node.title);
    setEditUrl(node.url);
    setIsEditing(true);
  };

  const handleSaveNode = () => {
    if (!selectedId) return;
    setData(prev => ({
      ...prev,
      nodes: prev.nodes.map(n => 
        n.id === selectedId ? { ...n, title: editTitle, url: editUrl } : n
      )
    }));
    setIsEditing(false);
  };

  const handleDeleteNode = (id: string) => {
    if (window.confirm('Bạn có chắc chắn muốn xóa mục này?')) {
      const idsToDelete = new Set<string>();
      const collectIds = (targetId: string) => {
        idsToDelete.add(targetId);
        data.nodes.filter(n => n.parentId === targetId).forEach(child => collectIds(child.id));
      };
      collectIds(id);
      setData(prev => ({ ...prev, nodes: prev.nodes.filter(n => !idsToDelete.has(n.id)) }));
      if (selectedId && idsToDelete.has(selectedId)) setSelectedId(null);
    }
  };

  const handleAddResource = (isGlobal: boolean) => {
    const title = window.prompt('Nhập tên tài liệu:');
    const url = window.prompt('Nhập link tài liệu:');
    if (!title || !url) return;

    if (isGlobal) {
      setData(prev => ({
        ...prev,
        globalResources: [...prev.globalResources, { id: `res-${Date.now()}`, title, url }]
      }));
    } else if (selectedId) {
      setData(prev => ({
        ...prev,
        nodes: prev.nodes.map(n => 
          n.id === selectedId 
            ? { ...n, lessonResources: [...n.lessonResources, { id: `res-${Date.now()}`, title, url }] }
            : n
        )
      }));
    }
  };

  const handleDeleteResource = (resId: string, isGlobal: boolean) => {
    if (isGlobal) {
      setData(prev => ({
        ...prev,
        globalResources: prev.globalResources.filter(r => r.id !== resId)
      }));
    } else {
      setData(prev => ({
        ...prev,
        nodes: prev.nodes.map(n => 
          n.id === selectedId 
            ? { ...n, lessonResources: n.lessonResources.filter(r => r.id !== resId) }
            : n
        )
      }));
    }
  };

  return (
    <div className="flex h-screen bg-gray-100 overflow-hidden font-sans relative">

      {/* MODAL NHẬP MẬT KHẨU */}
      {showPassModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-sm overflow-hidden">
            <div className="p-6">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-xl font-bold text-gray-800 flex items-center">
                  <ShieldCheck className="mr-2 text-amber-500" />
                  Xác minh GV
                </h3>
                <button onClick={() => setShowPassModal(false)} className="text-gray-400 hover:text-gray-600">
                  <X size={24} />
                </button>
              </div>

              <form onSubmit={verifyPassword}>
                <p className="text-sm text-gray-500 mb-4">Nhập mật khẩu Giáo viên (1234).</p>
                <input 
                  type="password"
                  autoFocus
                  value={passInput}
                  onChange={(e) => { setPassInput(e.target.value); setPassError(false); }}
                  className={`w-full px-4 py-3 bg-gray-50 border-2 rounded-xl mb-4 focus:outline-none ${passError ? 'border-red-400' : 'border-gray-100 focus:border-amber-400'}`}
                  placeholder="••••"
                />
                {passError && <div className="text-red-500 text-xs mb-4">Mật khẩu không chính xác!</div>}
                <button 
                  type="submit"
                  className="w-full py-3 text-sm font-black text-white bg-amber-500 rounded-xl hover:bg-amber-600 shadow-lg"
                >
                  XÁC NHẬN
                </button>
              </form>
            </div>
          </div>
        </div>
      )}

      {/* PANEL 1: SIDEBAR (MENU CÂY) */}
      <aside className={`w-80 border-r bg-white flex flex-col shadow-lg z-20 transition-all duration-300 ${isAdmin ? 'border-amber-300 ring-4 ring-amber-50' : 'border-gray-200'}`}>
        <div className={`p-5 border-b flex justify-between items-center text-white transition-colors duration-500 ${isAdmin ? 'bg-amber-600' : 'bg-indigo-600'}`}>
          <div className="flex items-center space-x-2">
            <Book size={24} />
            <h2 className="font-black text-xl tracking-tight uppercase">Mục lục sách</h2>
          </div>
          {isAdmin && (
            <button onClick={handleAddRoot} className="p-1.5 bg-white/20 hover:bg-white/40 rounded-full">
              <Plus size={20} />
            </button>
          )}
        </div>

        <div className="flex-1 overflow-y-auto p-4 custom-scrollbar">
          {data.nodes.filter(n => n.parentId === null).map(rootNode => (
            <TreeItem 
              key={rootNode.id}
              node={rootNode}
              allNodes={data.nodes}
              selectedId={selectedId}
              isAdmin={isAdmin}
              onSelect={(id) => {
                setSelectedId(id);
                const n = data.nodes.find(item => item.id === id);
                if (n) {
                  setEditTitle(n.title);
                  setEditUrl(n.url);
                  setIsEditing(false);
                }
              }}
              onAdd={handleAddChild}
              onEdit={handleEditNode}
              onDelete={handleDeleteNode}
              level={0}
            />
          ))}
        </div>

        <div className="p-4 border-t bg-gray-50">
           <button 
            onClick={handleToggleClick}
            className={`w-full flex items-center justify-center space-x-3 px-4 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
              isAdmin ? 'bg-amber-500 text-white' : 'bg-white text-indigo-600 border border-indigo-100 shadow-sm'
            }`}
           >
             {isAdmin ? <Unlock size={14} /> : <Lock size={14} />}
             <span>{isAdmin ? 'Thoát quyền GV' : 'Học sinh -> GV'}</span>
           </button>
        </div>
      </aside>

      {/* PANEL 2: CONTENT AREA (NHÚNG TRANG WEB) */}
      <main className="flex-1 flex flex-col min-w-0 bg-white relative">
        {isAdmin && <div className="absolute top-0 left-0 right-0 h-1.5 bg-amber-500 z-30"></div>}

        {selectedNode ? (
          <>
            <header className="px-8 py-4 border-b bg-white flex justify-between items-center h-20 shrink-0 z-10 shadow-sm">
              {isEditing ? (
                <div className="flex-1 max-w-2xl mr-4">
                  <input 
                    type="text"
                    value={editTitle}
                    onChange={(e) => setEditTitle(e.target.value)}
                    placeholder="Tên tiêu đề..."
                    className="text-lg font-bold border-b-2 border-amber-400 w-full focus:outline-none mb-1"
                  />
                  <div className="flex items-center text-xs text-gray-400">
                    <Globe size={12} className="mr-1" />
                    <input 
                      type="text"
                      value={editUrl}
                      onChange={(e) => setEditUrl(e.target.value)}
                      placeholder="Dán link trang web hoặc file vào đây..."
                      className="w-full focus:outline-none italic"
                    />
                  </div>
                </div>
              ) : (
                <div className="flex items-center space-x-4 truncate">
                    <div className={`p-3 rounded-2xl ${selectedNode.type === 'folder' ? 'bg-amber-100 text-amber-600' : 'bg-blue-100 text-blue-600'}`}>
                        {selectedNode.type === 'folder' ? <Book size={20}/> : <Globe size={20}/>}
                    </div>
                    <div>
                        <h1 className="text-xl font-black text-gray-800 truncate">{selectedNode.title}</h1>
                        <p className="text-[10px] text-gray-400 font-mono truncate max-w-md">{selectedNode.url || 'Chưa gắn link'}</p>
                    </div>
                </div>
              )}

              <div className="flex space-x-3">
                {isAdmin && (
                  isEditing ? (
                    <button onClick={handleSaveNode} className="flex items-center space-x-2 bg-emerald-500 text-white px-6 py-2 rounded-xl font-black text-xs shadow-md">
                      <Save size={16} /> <span>LƯU LINK</span>
                    </button>
                  ) : (
                    <button onClick={() => setIsEditing(true)} className="flex items-center space-x-2 bg-amber-50 border border-amber-100 text-amber-700 px-6 py-2 rounded-xl font-black text-xs">
                      <Pencil size={16} /> <span>SỬA LINK</span>
                    </button>
                  )
                )}
                {!isEditing && selectedNode.url && (
                    <a href={selectedNode.url} target="_blank" rel="noreferrer" className="flex items-center space-x-2 bg-gray-100 text-gray-600 px-4 py-2 rounded-xl font-black text-xs hover:bg-gray-200">
                        <Maximize2 size={16} /> <span>MỞ TAB MỚI</span>
                    </a>
                )}
              </div>
            </header>

            <div className="flex-1 bg-gray-200 relative overflow-hidden">
              {isEditing ? (
                <div className="absolute inset-0 flex flex-col items-center justify-center p-10 text-center bg-gray-50">
                    <div className="w-16 h-16 bg-amber-100 text-amber-600 rounded-full flex items-center justify-center mb-4">
                        <Globe size={32} />
                    </div>
                    <h3 className="text-xl font-bold text-gray-800 mb-2">Chỉnh sửa liên kết bài học</h3>
                    <p className="text-gray-500 max-w-md text-sm mb-6">Bạn hãy nhập địa chỉ trang web hoặc tài liệu (URL) vào ô phía trên để hiển thị nội dung tại đây.</p>
                    <div className="w-full max-w-lg bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
                        <p className="text-xs text-left text-gray-400 mb-2 font-bold uppercase">Gợi ý địa chỉ:</p>
                        <ul className="text-xs text-left space-y-2 text-indigo-500 italic">
                            <li>• https://vi.wikipedia.org/wiki/React</li>
                            <li>• https://docs.google.com/presentation/d/...</li>
                            <li>• https://www.youtube.com/embed/VIDEO_ID</li>
                        </ul>
                    </div>
                </div>
              ) : selectedNode.url ? (
                <iframe 
                    src={selectedNode.url} 
                    className="w-full h-full border-none bg-white"
                    title={selectedNode.title}
                    allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                    allowFullScreen
                />
              ) : (
                <div className="absolute inset-0 flex flex-col items-center justify-center text-gray-400 bg-gray-50">
                    <Globe size={64} className="mb-4 opacity-10" />
                    <p className="text-lg font-bold opacity-30 italic">Bài học này chưa được gắn link nội dung</p>
                    {isAdmin && <button onClick={() => setIsEditing(true)} className="mt-4 bg-amber-500 text-white px-4 py-2 rounded-lg text-xs font-bold">GẮN LINK NGAY</button>}
                </div>
              )}
            </div>
          </>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-gray-300 p-10 bg-gray-50/50">
            <Book size={100} className="mb-6 opacity-10" />
            <h2 className="text-2xl font-black text-gray-400 uppercase tracking-tighter">Chọn bài học để xem nội dung</h2>
          </div>
        )}
      </main>

      {/* PANEL 3: RESOURCES (LINK TÀI LIỆU) */}
      <aside className="w-60 border-l bg-gray-50 flex flex-col overflow-hidden shrink-0 shadow-inner">
        {/* Tài liệu bài học */}
        <div className="h-1/2 flex flex-col border-b overflow-hidden">
          <div className="p-4 border-b bg-white flex justify-between items-center sticky top-0 z-10 shadow-sm">
            <h3 className="font-black text-gray-500 flex items-center text-[9px] uppercase tracking-widest">
              <LinkIcon size={12} className="mr-2 text-indigo-500" />
              Tài liệu bài này
            </h3>
            {isAdmin && selectedNode && (
              <button onClick={() => handleAddResource(false)} className="p-1 text-amber-600 hover:bg-amber-50 rounded-lg">
                <Plus size={16} />
              </button>
            )}
          </div>
          <div className="flex-1 overflow-y-auto p-3 space-y-2 custom-scrollbar">
            {selectedNode?.lessonResources.map(res => (
                <div key={res.id} className="group bg-white p-2.5 rounded-xl border border-gray-100 shadow-sm hover:border-indigo-200 flex justify-between items-center">
                  <a href={res.url} target="_blank" rel="noreferrer" className="text-[10px] text-indigo-600 font-bold hover:underline truncate flex items-center">
                    <ExternalLink size={10} className="mr-1.5 opacity-60" />
                    <span className="truncate">{res.title}</span>
                  </a>
                  {isAdmin && (
                    <button onClick={() => handleDeleteResource(res.id, false)} className="opacity-0 group-hover:opacity-100 text-red-400"><X size={12} /></button>
                  )}
                </div>
            ))}
            {(!selectedNode || selectedNode.lessonResources.length === 0) && (
                <p className="text-[9px] text-gray-300 text-center py-8 italic font-bold uppercase">Trống</p>
            )}
          </div>
        </div>

        {/* Tài liệu chung */}
        <div className="h-1/2 flex flex-col bg-white overflow-hidden">
          <div className="p-4 border-b bg-indigo-50 flex justify-between items-center sticky top-0 z-10 shadow-sm">
            <h3 className="font-black text-indigo-900 flex items-center text-[9px] uppercase tracking-widest">
              <Settings size={12} className="mr-2" />
              Tài liệu chung
            </h3>
            {isAdmin && (
              <button onClick={() => handleAddResource(true)} className="p-1 text-indigo-600 hover:bg-white rounded-lg">
                <Plus size={16} />
              </button>
            )}
          </div>
          <div className="flex-1 overflow-y-auto p-3 space-y-2 custom-scrollbar">
            {data.globalResources.map(res => (
                <div key={res.id} className="group bg-gray-50 p-2.5 rounded-xl border border-gray-100 flex justify-between items-center hover:bg-indigo-50 transition-colors">
                  <a href={res.url} target="_blank" rel="noreferrer" className="text-[10px] text-gray-700 hover:text-indigo-600 font-bold truncate flex items-center">
                    <LinkIcon size={10} className="mr-1.5 opacity-30" />
                    <span className="truncate">{res.title}</span>
                  </a>
                  {isAdmin && (
                    <button onClick={() => handleDeleteResource(res.id, true)} className="opacity-0 group-hover:opacity-100 text-red-400"><X size={12} /></button>
                  )}
                </div>
            ))}
          </div>
        </div>
      </aside>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { ChevronRight, ChevronDown, Folder, Globe, Plus, Pencil, Trash2 } from 'lucide-react';
import { BookNode, NodeType } from '../types';

interface TreeItemProps {
  node: BookNode;
  allNodes: BookNode[];
  selectedId: string | null;
  isAdmin: boolean;
  onSelect: (id: string) => void;
  onAdd: (parentId: string, type: NodeType) => void;
  onEdit: (node: BookNode) => void;
  onDelete: (id: string) => void;
  level: number;
}

const TreeItem: React.FC<TreeItemProps> = ({ 
  node, 
  allNodes, 
  selectedId, 
  isAdmin,
  onSelect, 
  onAdd, 
  onEdit, 
  onDelete,
  level 
}) => {
  const [isOpen, setIsOpen] = useState(true);

  const children = allNodes.filter(n => n.parentId === node.id);
  const isSelected = selectedId === node.id;

  return (
    <div className="select-none mb-1">
      <div 
        className={`group flex items-center py-2 px-3 rounded-xl cursor-pointer transition-all ${
          isSelected 
            ? 'bg-indigo-600 text-white shadow-md' 
            : 'hover:bg-gray-100 text-gray-600'
        }`}
        style={{ marginLeft: `${level * 0.75}rem` }}
        onClick={() => onSelect(node.id)}
      >
        <div className="flex items-center flex-1 min-w-0">
          {node.type === 'folder' ? (
            <button 
              onClick={(e) => { e.stopPropagation(); setIsOpen(!isOpen); }}
              className={`p-1 mr-1 rounded-md ${isSelected ? 'text-white/50 hover:text-white' : 'text-gray-400 hover:bg-gray-200'}`}
            >
              {isOpen ? <ChevronDown size={12} strokeWidth={3} /> : <ChevronRight size={12} strokeWidth={3} />}
            </button>
          ) : (
            <div className="w-4 mr-1" />
          )}

          {node.type === 'folder' ? (
            <Folder size={14} className={`mr-2 shrink-0 ${isSelected ? 'text-white' : 'text-amber-400'}`} />
          ) : (
            <Globe size={14} className={`mr-2 shrink-0 ${isSelected ? 'text-white' : 'text-blue-400'}`} />
          )}

          <span className={`truncate text-xs ${isSelected ? 'font-black' : 'font-medium'}`}>{node.title}</span>
        </div>

        {isAdmin && (
          <div className="hidden group-hover:flex items-center space-x-1 ml-2">
            {node.type === 'folder' && (
              <button 
                onClick={(e) => { e.stopPropagation(); onAdd(node.id, 'lesson'); }}
                className={`p-1 rounded-lg ${isSelected ? 'hover:bg-white/20' : 'hover:bg-indigo-100 text-indigo-500'}`}
              >
                <Plus size={12} />
              </button>
            )}
            <button 
              onClick={(e) => { e.stopPropagation(); onEdit(node); }}
              className={`p-1 rounded-lg ${isSelected ? 'hover:bg-white/20' : 'hover:bg-amber-100 text-amber-500'}`}
            >
              <Pencil size={12} />
            </button>
            <button 
              onClick={(e) => { e.stopPropagation(); onDelete(node.id); }}
              className={`p-1 rounded-lg ${isSelected ? 'hover:bg-white/20' : 'hover:bg-red-100 text-red-500'}`}
            >
              <Trash2 size={12} />
            </button>
          </div>
        )}
      </div>

      {node.type === 'folder' && isOpen && children.length > 0 && (
        <div className="mt-1">
          {children.map(child => (
            <TreeItem 
              key={child.id}
              node={child}
              allNodes={allNodes}
              selectedId={selectedId}
              isAdmin={isAdmin}
              onSelect={onSelect}
              onAdd={onAdd}
              onEdit={onEdit}
              onDelete={onDelete}
              level={level + 1}
            />
          ))}
        </div>
      )}
    </div>
  );
};

export default TreeItem;

import React, { useState, useEffect } from 'react';
import { 
  Book, 
  ExternalLink, 
  Link as LinkIcon, 
  X, 
  Lock, 
  Unlock,
  Pencil,
  Plus,
  Settings,
  User,
  ChevronRight,
  ShieldCheck,
  AlertCircle,
  Globe,
  Maximize2,
  Save
} from 'lucide-react';
import { BookNode, NodeType, AppData } from './types';
import { INITIAL_DATA } from './constants';
import TreeItem from './components/TreeItem';

const App: React.FC = () => {
  const [data, setData] = useState<AppData>(() => {
    const saved = localStorage.getItem('teacher_app_data_v3');
    return saved ? JSON.parse(saved) : INITIAL_DATA;
  });

  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [isAdmin, setIsAdmin] = useState(false);

  // Modal states
  const [showPassModal, setShowPassModal] = useState(false);
  const [passInput, setPassInput] = useState('');
  const [passError, setPassError] = useState(false);

  // Node Edit Modal
  const [showNodeModal, setShowNodeModal] = useState(false);
  const [nodeModalData, setNodeModalData] = useState<{
    id?: string;
    parentId: string | null;
    type: NodeType;
    title: string;
    url: string;
  }>({ parentId: null, type: 'lesson', title: '', url: '' });

  useEffect(() => {
    localStorage.setItem('teacher_app_data_v3', JSON.stringify(data));
  }, [data]);

  const selectedNode = data.nodes.find(n => n.id === selectedId);

  // FIX: Admin Toggle Logic
  const handleToggleClick = () => {
    if (!isAdmin) {
      setShowPassModal(true);
      setPassInput('');
      setPassError(false);
    } else {
      if (window.confirm('Bạn có chắc chắn muốn thoát quyền Giáo viên?')) {
        setIsAdmin(false);
        // Reset any pending edit states
        setShowNodeModal(false);
      }
    }
  };

  const verifyPassword = (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (passInput === '1234') {
      setIsAdmin(true);
      setShowPassModal(false);
      setPassError(false);
    } else {
      setPassError(true);
    }
  };

  // Node Management via Modal
  const openAddNodeModal = (parentId: string | null, type: NodeType) => {
    setNodeModalData({ parentId, type, title: '', url: '' });
    setShowNodeModal(true);
  };

  const openEditNodeModal = (node: BookNode) => {
    setNodeModalData({ 
      id: node.id, 
      parentId: node.parentId, 
      type: node.type, 
      title: node.title, 
      url: node.url 
    });
    setShowNodeModal(true);
  };

  const saveNode = (e: React.FormEvent) => {
    e.preventDefault();
    if (!nodeModalData.title.trim()) return alert('Vui lòng nhập tên đề mục');

    if (nodeModalData.id) {
      // Update existing
      setData(prev => ({
        ...prev,
        nodes: prev.nodes.map(n => 
          n.id === nodeModalData.id 
            ? { ...n, title: nodeModalData.title, url: nodeModalData.url } 
            : n
        )
      }));
    } else {
      // Add new
      const newNode: BookNode = {
        id: `node-${Date.now()}`,
        title: nodeModalData.title,
        type: nodeModalData.type,
        url: nodeModalData.url,
        parentId: nodeModalData.parentId,
        lessonResources: []
      };
      setData(prev => ({ ...prev, nodes: [...prev.nodes, newNode] }));
      setSelectedId(newNode.id);
    }
    setShowNodeModal(false);
  };

  const handleDeleteNode = (id: string) => {
    if (window.confirm('Xóa mục này và tất cả các mục con bên trong?')) {
      const idsToDelete = new Set<string>();
      const collectIds = (targetId: string) => {
        idsToDelete.add(targetId);
        data.nodes.filter(n => n.parentId === targetId).forEach(child => collectIds(child.id));
      };
      collectIds(id);
      setData(prev => ({ ...prev, nodes: prev.nodes.filter(n => !idsToDelete.has(n.id)) }));
      if (selectedId && idsToDelete.has(selectedId)) setSelectedId(null);
    }
  };

  const handleAddResource = (isGlobal: boolean) => {
    const title = window.prompt('Nhập tên tài liệu:');
    const url = window.prompt('Nhập link tài liệu:');
    if (!title || !url) return;

    if (isGlobal) {
      setData(prev => ({
        ...prev,
        globalResources: [...prev.globalResources, { id: `res-${Date.now()}`, title, url }]
      }));
    } else if (selectedId) {
      setData(prev => ({
        ...prev,
        nodes: prev.nodes.map(n => 
          n.id === selectedId 
            ? { ...n, lessonResources: [...n.lessonResources, { id: `res-${Date.now()}`, title, url }] }
            : n
        )
      }));
    }
  };

  const handleDeleteResource = (resId: string, isGlobal: boolean) => {
    if (isGlobal) {
      setData(prev => ({
        ...prev,
        globalResources: prev.globalResources.filter(r => r.id !== resId)
      }));
    } else {
      setData(prev => ({
        ...prev,
        nodes: prev.nodes.map(n => 
          n.id === selectedId 
            ? { ...n, lessonResources: n.lessonResources.filter(r => r.id !== resId) }
            : n
        )
      }));
    }
  };

  return (
    <div className="flex h-screen bg-gray-100 overflow-hidden font-sans relative">

      {/* 1. PASSWORD MODAL */}
      {showPassModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-sm overflow-hidden animate-in zoom-in duration-200">
            <div className="p-6">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-xl font-bold text-gray-800 flex items-center">
                  <ShieldCheck className="mr-2 text-amber-500" /> Xác minh GV
                </h3>
                <button onClick={() => setShowPassModal(false)} className="text-gray-400 hover:text-gray-600"><X size={20}/></button>
              </div>
              <form onSubmit={verifyPassword}>
                <p className="text-xs text-gray-500 mb-4 font-medium italic">Mật khẩu mặc định: 1234</p>
                <input 
                  type="password" autoFocus value={passInput}
                  onChange={(e) => { setPassInput(e.target.value); setPassError(false); }}
                  className={`w-full px-4 py-3 bg-gray-50 border-2 rounded-xl mb-4 focus:outline-none ${passError ? 'border-red-400' : 'border-gray-100 focus:border-amber-400'}`}
                  placeholder="Nhập mật khẩu..."
                />
                {passError && <div className="text-red-500 text-[10px] mb-4 font-bold uppercase tracking-tight">Sai mật khẩu!</div>}
                <button type="submit" className="w-full py-3 text-sm font-black text-white bg-amber-500 rounded-xl hover:bg-amber-600 shadow-lg shadow-amber-100">XÁC NHẬN</button>
              </form>
            </div>
          </div>
        </div>
      )}

      {/* 2. ADD/EDIT NODE MODAL (Form nhỏ) */}
      {showNodeModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/40 backdrop-blur-[2px]">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden animate-in slide-in-from-bottom-4 duration-300">
            <div className="p-6">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-lg font-black text-gray-800 uppercase tracking-tight flex items-center">
                  {nodeModalData.id ? <Pencil size={18} className="mr-2 text-blue-500"/> : <Plus size={18} className="mr-2 text-green-500"/>}
                  {nodeModalData.id ? 'Cập nhật mục' : `Thêm ${nodeModalData.type === 'folder' ? 'Chương' : 'Bài học'}`}
                </h3>
                <button onClick={() => setShowNodeModal(false)} className="text-gray-300 hover:text-gray-500"><X size={20}/></button>
              </div>
              <form onSubmit={saveNode} className="space-y-4">
                <div>
                  <label className="text-[10px] font-black text-gray-400 uppercase mb-1 block">Tên hiển thị</label>
                  <input 
                    type="text" autoFocus value={nodeModalData.title}
                    onChange={(e) => setNodeModalData({...nodeModalData, title: e.target.value})}
                    placeholder="VD: Chương 1, Bài 2..."
                    className="w-full px-4 py-3 bg-gray-50 border-2 border-gray-100 rounded-xl focus:outline-none focus:border-blue-400 transition-all font-bold text-gray-700"
                  />
                </div>
                <div>
                  <label className="text-[10px] font-black text-gray-400 uppercase mb-1 block">Đường dẫn (URL / Link)</label>
                  <input 
                    type="text" value={nodeModalData.url}
                    onChange={(e) => setNodeModalData({...nodeModalData, url: e.target.value})}
                    placeholder="https://..."
                    className="w-full px-4 py-3 bg-gray-50 border-2 border-gray-100 rounded-xl focus:outline-none focus:border-blue-400 transition-all font-mono text-xs"
                  />
                  <p className="text-[10px] text-gray-400 mt-2 italic">Dán link trang web, file PDF hoặc video muốn hiển thị.</p>
                </div>
                <div className="flex gap-3 pt-4">
                  <button type="button" onClick={() => setShowNodeModal(false)} className="flex-1 py-3 text-xs font-black text-gray-400 hover:bg-gray-50 rounded-xl">HỦY</button>
                  <button type="submit" className="flex-1 py-3 text-xs font-black text-white bg-indigo-600 hover:bg-indigo-700 rounded-xl shadow-lg shadow-indigo-100 uppercase tracking-widest flex items-center justify-center gap-2">
                    <Save size={14} /> LƯU LẠI
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}

      {/* PANEL 1: SIDEBAR */}
      <aside className={`w-80 border-r bg-white flex flex-col shadow-lg z-20 transition-all duration-300 ${isAdmin ? 'border-amber-300 ring-4 ring-amber-50/50' : 'border-gray-200'}`}>
