              <div className="flex space-x-3">
                {isAdmin && (
                    <button onClick={() => openEditNodeModal(selectedNode)} className="flex items-center space-x-2 bg-amber-50 border border-amber-100 text-amber-700 px-6 py-2 rounded-xl font-black text-xs hover:bg-amber-100 transition-all">
                      <Pencil size={16} /> <span>CHỈNH SỬA LINK</span>
                    </button>
                )}
                {selectedNode.url && (
                    <a href={selectedNode.url} target="_blank" rel="noreferrer" className="flex items-center space-x-2 bg-gray-100 text-gray-600 px-4 py-2 rounded-xl font-black text-xs hover:bg-gray-200 transition-all">
                        <Maximize2 size={16} /> <span>MỞ TRANG GỐC</span>
                    </a>
                )}
              </div>
            </header>

            <div className="flex-1 bg-gray-200 relative">
              {selectedNode.url ? (
                <iframe 
                    src={selectedNode.url} 
                    className="w-full h-full border-none bg-white"
                    title={selectedNode.title}
                    allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                    allowFullScreen
                />
              ) : (
                <div className="absolute inset-0 flex flex-col items-center justify-center text-gray-400 bg-gray-50 p-10 text-center">
                    <Globe size={64} className="mb-4 opacity-10" />
                    <p className="text-lg font-bold opacity-30 italic">Bài học này chưa được gắn liên kết nội dung</p>
                    {isAdmin && <button onClick={() => openEditNodeModal(selectedNode)} className="mt-4 bg-amber-500 text-white px-6 py-3 rounded-2xl font-black text-xs shadow-lg shadow-amber-100 uppercase tracking-widest">GẮN LINK NGAY</button>}
                </div>
              )}
            </div>
          </>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-gray-300 p-10 bg-gray-50/50">
            <Book size={100} className="mb-6 opacity-10" />
            <h2 className="text-2xl font-black text-gray-400 uppercase tracking-tighter">Chọn bài học để bắt đầu</h2>
            <p className="mt-2 text-gray-400 font-medium">Chọn một chương hoặc bài học từ danh mục bên trái.</p>
          </div>
        )}
      </main>

      {/* PANEL 3: RESOURCES */}
      <aside className="w-60 border-l bg-gray-50 flex flex-col overflow-hidden shrink-0 shadow-inner">
        <div className="h-1/2 flex flex-col border-b overflow-hidden">
          <div className="p-4 border-b bg-white flex justify-between items-center sticky top-0 z-10 shadow-sm">
            <h3 className="font-black text-gray-500 flex items-center text-[9px] uppercase tracking-widest">
              <LinkIcon size={12} className="mr-2 text-indigo-500" /> Tài liệu bài học
            </h3>
            {isAdmin && selectedNode && (
              <button onClick={() => handleAddResource(false)} className="p-1 text-amber-600 hover:bg-amber-50 rounded-lg"><Plus size={16} /></button>
            )}
          </div>
          <div className="flex-1 overflow-y-auto p-3 space-y-2 custom-scrollbar">
            {selectedNode?.lessonResources.map(res => (
                <div key={res.id} className="group bg-white p-2.5 rounded-xl border border-gray-100 shadow-sm hover:border-indigo-200 flex justify-between items-center transition-all">
                  <a href={res.url} target="_blank" rel="noreferrer" className="text-[10px] text-indigo-600 font-bold hover:underline truncate flex items-center">
                    <ExternalLink size={10} className="mr-1.5 opacity-60" />
                    <span className="truncate">{res.title}</span>
                  </a>
                  {isAdmin && (
                    <button onClick={() => handleDeleteResource(res.id, false)} className="opacity-0 group-hover:opacity-100 text-red-400 transition-opacity"><X size={12} /></button>
                  )}
                </div>
            ))}
            {(!selectedNode || selectedNode.lessonResources.length === 0) && (
                <p className="text-[9px] text-gray-300 text-center py-8 italic font-bold uppercase tracking-widest">Trống</p>
            )}
          </div>
        </div>

        <div className="h-1/2 flex flex-col bg-white overflow-hidden">
          <div className="p-4 border-b bg-indigo-50/50 flex justify-between items-center sticky top-0 z-10 shadow-sm">
            <h3 className="font-black text-indigo-900 flex items-center text-[9px] uppercase tracking-widest">
              <Settings size={12} className="mr-2" /> Tài liệu chung
            </h3>
            {isAdmin && (
              <button onClick={() => handleAddResource(true)} className="p-1 text-indigo-600 hover:bg-white rounded-lg"><Plus size={16} /></button>
            )}
          </div>
          <div className="flex-1 overflow-y-auto p-3 space-y-2 custom-scrollbar">
            {data.globalResources.map(res => (
                <div key={res.id} className="group bg-gray-50 p-2.5 rounded-xl border border-gray-100 flex justify-between items-center hover:bg-indigo-50 transition-colors">
                  <a href={res.url} target="_blank" rel="noreferrer" className="text-[10px] text-gray-700 hover:text-indigo-600 font-bold truncate flex items-center">
                    <LinkIcon size={10} className="mr-1.5 opacity-30" />
                    <span className="truncate">{res.title}</span>
                  </a>
                  {isAdmin && (
                    <button onClick={() => handleDeleteResource(res.id, true)} className="opacity-0 group-hover:opacity-100 text-red-400 transition-opacity"><X size={12} /></button>
                  )}
