      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
        @keyframes in { from { opacity: 0; transform: scale(0.95); } to { opacity: 1; transform: scale(1); } }
        .animate-in { animation: in 0.2s ease-out; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { 
  Book, 
  ExternalLink, 
  Link as LinkIcon, 
  X, 
  Lock, 
  Unlock,
  Pencil,
  Plus,
  Settings,
  User,
  ChevronRight,
  ShieldCheck,
  Globe,
  Maximize2,
  Save,
  Loader2,
  LogOut,
  GraduationCap
} from 'lucide-react';
import { BookNode, NodeType, AppData } from './types';
import { INITIAL_DATA } from './constants';
import TreeItem from './components/TreeItem';

const App: React.FC = () => {
  const [data, setData] = useState<AppData>(() => {
    const saved = localStorage.getItem('teacher_app_data_v4');
    return saved ? JSON.parse(saved) : INITIAL_DATA;
  });

  const [role, setRole] = useState<'none' | 'teacher' | 'student'>('none');
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [iframeLoading, setIframeLoading] = useState(false);

  // Node Edit Modal (Form nhỏ)
  const [showNodeModal, setShowNodeModal] = useState(false);
  const [nodeModalData, setNodeModalData] = useState<{
    id?: string;
    parentId: string | null;
    type: NodeType;
    title: string;
    url: string;
  }>({ parentId: null, type: 'lesson', title: '', url: '' });

  useEffect(() => {
    localStorage.setItem('teacher_app_data_v4', JSON.stringify(data));
  }, [data]);

  const selectedNode = data.nodes.find(n => n.id === selectedId);

  // Xử lý khi chọn bài học
  const handleSelectNode = (id: string) => {
    setSelectedId(id);
    const node = data.nodes.find(n => n.id === id);
    if (node && node.url) {
      setIframeLoading(true);
    }
  };

  // Node Management
  const openAddNodeModal = (parentId: string | null, type: NodeType) => {
    setNodeModalData({ parentId, type, title: '', url: '' });
    setShowNodeModal(true);
  };

  const openEditNodeModal = (node: BookNode) => {
    setNodeModalData({ 
      id: node.id, 
      parentId: node.parentId, 
      type: node.type, 
      title: node.title, 
      url: node.url 
    });
    setShowNodeModal(true);
  };

  const saveNode = (e: React.FormEvent) => {
    e.preventDefault();
    if (!nodeModalData.title.trim()) return;

    if (nodeModalData.id) {
      setData(prev => ({
        ...prev,
        nodes: prev.nodes.map(n => 
          n.id === nodeModalData.id ? { ...n, title: nodeModalData.title, url: nodeModalData.url } : n
        )
      }));
    } else {
      const newNode: BookNode = {
        id: `node-${Date.now()}`,
        title: nodeModalData.title,
        type: nodeModalData.type,
        url: nodeModalData.url,
        parentId: nodeModalData.parentId,
        lessonResources: []
      };
      setData(prev => ({ ...prev, nodes: [...prev.nodes, newNode] }));
      setSelectedId(newNode.id);
    }
    setShowNodeModal(false);
  };

  const handleDeleteNode = (id: string) => {
    if (window.confirm('Xóa mục này?')) {
      const idsToDelete = new Set<string>();
      const collectIds = (targetId: string) => {
        idsToDelete.add(targetId);
        data.nodes.filter(n => n.parentId === targetId).forEach(child => collectIds(child.id));
      };
      collectIds(id);
      setData(prev => ({ ...prev, nodes: prev.nodes.filter(n => !idsToDelete.has(n.id)) }));
      if (selectedId && idsToDelete.has(selectedId)) setSelectedId(null);
    }
  };

  const handleAddResource = (isGlobal: boolean) => {
    const title = window.prompt('Tên tài liệu:');
    const url = window.prompt('Link:');
    if (!title || !url) return;

    if (isGlobal) {
      setData(prev => ({ ...prev, globalResources: [...prev.globalResources, { id: `res-${Date.now()}`, title, url }] }));
    } else if (selectedId) {
      setData(prev => ({
        ...prev,
        nodes: prev.nodes.map(n => 
          n.id === selectedId ? { ...n, lessonResources: [...n.lessonResources, { id: `res-${Date.now()}`, title, url }] } : n
        )
      }));
    }
  };

  const handleDeleteResource = (resId: string, isGlobal: boolean) => {
    if (isGlobal) {
      setData(prev => ({ ...prev, globalResources: prev.globalResources.filter(r => r.id !== resId) }));
    } else {
      setData(prev => ({
        ...prev,
        nodes: prev.nodes.map(n => 
          n.id === selectedId ? { ...n, lessonResources: n.lessonResources.filter(r => r.id !== resId) } : n
        )
      }));
    }
  };

  // MÀN HÌNH CHỌN VAI TRÒ
  if (role === 'none') {
    return (
      <div className="h-screen w-full flex items-center justify-center bg-gray-50 p-6">
        <div className="max-w-4xl w-full grid grid-cols-1 md:grid-cols-2 gap-8">
          {/* Lựa chọn Học sinh */}
          <button 
            onClick={() => setRole('student')}
            className="group bg-white p-10 rounded-[40px] shadow-xl hover:shadow-2xl transition-all border-4 border-transparent hover:border-indigo-500 flex flex-col items-center text-center space-y-6"
          >
            <div className="w-24 h-24 bg-indigo-100 text-indigo-600 rounded-3xl flex items-center justify-center group-hover:scale-110 transition-transform">
              <GraduationCap size={48} />
            </div>
            <div>
              <h2 className="text-3xl font-black text-gray-800">HỌC SINH</h2>
              <p className="text-gray-500 mt-2 font-medium">Xem bài giảng, tài liệu học tập và hướng dẫn từ giáo viên.</p>
            </div>
            <div className="px-8 py-3 bg-indigo-600 text-white rounded-2xl font-black text-sm tracking-widest uppercase">Vào xem bài</div>
          </button>

          {/* Lựa chọn Giáo viên */}
          <button 
            onClick={() => {
              const pass = window.prompt('Nhập mật khẩu giáo viên (1234):');
              if (pass === '1234') setRole('teacher');
              else if (pass !== null) alert('Sai mật khẩu!');
            }}
            className="group bg-white p-10 rounded-[40px] shadow-xl hover:shadow-2xl transition-all border-4 border-transparent hover:border-amber-500 flex flex-col items-center text-center space-y-6"
          >
            <div className="w-24 h-24 bg-amber-100 text-amber-600 rounded-3xl flex items-center justify-center group-hover:scale-110 transition-transform">
              <ShieldCheck size={48} />
            </div>
            <div>
              <h2 className="text-3xl font-black text-gray-800">GIÁO VIÊN</h2>
              <p className="text-gray-500 mt-2 font-medium">Soạn thảo giáo án, quản lý danh mục và đính kèm tài liệu.</p>
            </div>
            <div className="px-8 py-3 bg-amber-500 text-white rounded-2xl font-black text-sm tracking-widest uppercase">Quản lý bài học</div>
          </button>
        </div>
      </div>
    );
  }

  const isAdmin = role === 'teacher';

  return (
    <div className="flex h-screen bg-white overflow-hidden font-sans relative">

      {/* FORM NHỎ ĐỂ THÊM/SỬA MENU */}
      {showNodeModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/40 backdrop-blur-sm">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden animate-in fade-in zoom-in duration-200">
            <div className="p-8">
              <div className="flex justify-between items-center mb-6">
                <h3 className="font-black text-gray-800 uppercase tracking-tight">
                  {nodeModalData.id ? 'Sửa thông tin' : 'Thêm mục mới'}
                </h3>
                <button onClick={() => setShowNodeModal(false)} className="text-gray-300 hover:text-gray-500"><X size={20}/></button>
              </div>
              <form onSubmit={saveNode} className="space-y-5">
                <div>
                  <label className="text-[10px] font-black text-gray-400 uppercase mb-1 block">Tên hiển thị</label>
                  <input 
                    type="text" autoFocus value={nodeModalData.title}
                    onChange={(e) => setNodeModalData({...nodeModalData, title: e.target.value})}
                    placeholder="VD: Chương 1..."
                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:border-indigo-500 font-bold"
                  />
                </div>
                <div>
                  <label className="text-[10px] font-black text-gray-400 uppercase mb-1 block">Link liên kết (URL)</label>
                  <input 
                    type="text" value={nodeModalData.url}
                    onChange={(e) => setNodeModalData({...nodeModalData, url: e.target.value})}
                    placeholder="https://..."
                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:border-indigo-500 font-mono text-xs"
                  />
                </div>
                <button type="submit" className="w-full py-4 text-xs font-black text-white bg-indigo-600 rounded-xl shadow-lg hover:bg-indigo-700 transition-all uppercase tracking-widest">
                  Lưu thay đổi
                </button>
              </form>
            </div>
          </div>
        </div>
      )}

      {/* PANEL 1: SIDEBAR */}
      <aside className={`w-72 border-r flex flex-col shrink-0 transition-colors ${isAdmin ? 'bg-amber-50/30 border-amber-100' : 'bg-white border-gray-100'}`}>
        <div className={`p-6 border-b flex justify-between items-center text-white ${isAdmin ? 'bg-amber-500' : 'bg-indigo-600'}`}>
          <div className="flex items-center space-x-2">
            <Book size={20} />
            <h2 className="font-black text-lg tracking-tight uppercase">Danh mục</h2>
          </div>
          {isAdmin && (
            <button onClick={() => openAddNodeModal(null, 'folder')} className="p-1 hover:bg-white/20 rounded-lg"><Plus size={20} /></button>
          )}
        </div>

        <div className="flex-1 overflow-y-auto p-4 custom-scrollbar">
          {data.nodes.filter(n => n.parentId === null).map(rootNode => (
            <TreeItem 
              key={rootNode.id}
              node={rootNode}
              allNodes={data.nodes}
              selectedId={selectedId}
              isAdmin={isAdmin}
              onSelect={handleSelectNode}
              onAdd={openAddNodeModal}
              onEdit={openEditNodeModal}
              onDelete={handleDeleteNode}
              level={0}
            />
          ))}
        </div>

        <div className="p-4 border-t border-gray-100">
           <button 
            onClick={() => { if(window.confirm('Quay lại màn hình chính?')) setRole('none'); }}
            className="w-full flex items-center justify-center space-x-2 px-4 py-3 rounded-xl text-[10px] font-black uppercase bg-gray-100 text-gray-500 hover:bg-gray-200 transition-all"
           >
             <LogOut size={14} />
             <span>Thoát chế độ {isAdmin ? 'GV' : 'HS'}</span>
           </button>
        </div>
      </aside>

      {/* PANEL 2: CONTENT AREA */}
      <main className="flex-1 flex flex-col min-w-0 relative">
        {selectedNode ? (
          <>
            <header className="px-8 py-4 border-b border-gray-100 bg-white flex justify-between items-center h-20 shrink-0">
                <div className="flex items-center space-x-4">
                    <div className={`p-2.5 rounded-xl ${selectedNode.type === 'folder' ? 'bg-amber-50 text-amber-500' : 'bg-indigo-50 text-indigo-500'}`}>
                        {selectedNode.type === 'folder' ? <Book size={18}/> : <Globe size={18}/>}
                    </div>
                    <h1 className="text-lg font-black text-gray-800 truncate tracking-tight">{selectedNode.title}</h1>
                </div>

                <div className="flex space-x-2">
                    {isAdmin && (
                        <button onClick={() => openEditNodeModal(selectedNode)} className="p-2.5 text-amber-600 bg-amber-50 rounded-xl hover:bg-amber-100 transition-all"><Pencil size={18} /></button>
                    )}
                    {selectedNode.url && (
                        <a href={selectedNode.url} target="_blank" rel="noreferrer" className="p-2.5 text-gray-400 bg-gray-50 rounded-xl hover:bg-gray-100"><Maximize2 size={18} /></a>
                    )}
                </div>
            </header>

            <div className="flex-1 bg-gray-50 relative">
              {iframeLoading && (
                <div className="absolute inset-0 z-10 flex flex-col items-center justify-center bg-white/80 backdrop-blur-sm">
                  <Loader2 size={40} className="animate-spin text-indigo-500 mb-4" />
                  <p className="text-xs font-black text-gray-400 uppercase tracking-widest">Đang tải nội dung...</p>
                </div>
              )}
              {selectedNode.url ? (
                <iframe 
                    src={selectedNode.url} 
                    className="w-full h-full border-none"
                    onLoad={() => setIframeLoading(false)}
                    title={selectedNode.title}
                />
              ) : (
                <div className="absolute inset-0 flex flex-col items-center justify-center text-gray-300 p-10 text-center">
                    <Globe size={60} className="mb-4 opacity-10" />
                    <p className="text-sm font-bold opacity-30 italic">Bài học chưa có liên kết</p>
                </div>
              )}
            </div>
          </>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-gray-200 p-10">
            <Book size={80} className="mb-4 opacity-10" />
            <h2 className="text-xl font-black uppercase tracking-tighter">Chọn một bài học từ danh mục</h2>
          </div>
        )}
      </main>

      {/* PANEL 3: RESOURCES */}
      <aside className="w-56 border-l border-gray-100 bg-gray-50/50 flex flex-col shrink-0">
        <div className="h-1/2 flex flex-col border-b border-gray-100">
          <div className="p-4 border-b border-gray-100 bg-white flex justify-between items-center sticky top-0">
            <h3 className="font-black text-[9px] text-gray-400 uppercase tracking-widest flex items-center">
              <LinkIcon size={12} className="mr-2 text-indigo-400" /> Tài liệu bài học
            </h3>
            {isAdmin && selectedNode && (
              <button onClick={() => handleAddResource(false)} className="text-indigo-600 hover:scale-110 transition-transform"><Plus size={16} /></button>
            )}
          </div>
          <div className="flex-1 overflow-y-auto p-3 space-y-2 custom-scrollbar">
            {selectedNode?.lessonResources.map(res => (
                <div key={res.id} className="group bg-white p-3 rounded-xl border border-gray-100 shadow-sm flex justify-between items-center transition-all hover:border-indigo-200">
                  <a href={res.url} target="_blank" rel="noreferrer" className="text-[10px] text-indigo-600 font-bold hover:underline truncate mr-1">
                    {res.title}
                  </a>
                  {isAdmin && (
                    <button onClick={() => handleDeleteResource(res.id, false)} className="text-red-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"><X size={12} /></button>
                  )}
                </div>
            ))}
            {(!selectedNode || selectedNode.lessonResources.length === 0) && (
                <p className="text-[9px] text-gray-300 text-center py-6 italic uppercase font-bold">Trống</p>
            )}
          </div>
        </div>

