import React, { useState, useEffect } from 'react';
import { 
  Book, 
  ExternalLink, 
  Link as LinkIcon, 
  X, 
  Lock, 
  Unlock,
  Pencil,
  Plus,
  Settings,
  ChevronRight,
  ShieldCheck,
  Globe,
  Maximize2,
  Save,
  Loader2,
  LogOut,
  GraduationCap,
  KeyRound
} from 'lucide-react';
import { BookNode, NodeType, AppData } from './types';
import { INITIAL_DATA } from './constants';
import TreeItem from './components/TreeItem';

const App: React.FC = () => {
  const [data, setData] = useState<AppData>(() => {
    const saved = localStorage.getItem('teacher_app_data_v5');
    return saved ? JSON.parse(saved) : INITIAL_DATA;
  });

  const [role, setRole] = useState<'none' | 'teacher' | 'student'>('none');
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [iframeLoading, setIframeLoading] = useState(false);

  // Password Input State for Landing Page
  const [showPassInput, setShowPassInput] = useState(false);
  const [teacherPass, setTeacherPass] = useState('');
  const [passError, setPassError] = useState(false);

  // Node Edit Modal
  const [showNodeModal, setShowNodeModal] = useState(false);
  const [nodeModalData, setNodeModalData] = useState<{
    id?: string;
    parentId: string | null;
    type: NodeType;
    title: string;
    url: string;
  }>({ parentId: null, type: 'lesson', title: '', url: '' });

  useEffect(() => {
    localStorage.setItem('teacher_app_data_v5', JSON.stringify(data));
  }, [data]);

  const selectedNode = data.nodes.find(n => n.id === selectedId);

  const handleSelectNode = (id: string) => {
    setSelectedId(id);
    const node = data.nodes.find(n => n.id === id);
    if (node && node.url) {
      setIframeLoading(true);
    }
  };

  const openAddNodeModal = (parentId: string | null, type: NodeType) => {
    setNodeModalData({ parentId, type, title: '', url: '' });
    setShowNodeModal(true);
  };

  const openEditNodeModal = (node: BookNode) => {
    setNodeModalData({ 
      id: node.id, 
      parentId: node.parentId, 
      type: node.type, 
      title: node.title, 
      url: node.url 
    });
    setShowNodeModal(true);
  };

  const saveNode = (e: React.FormEvent) => {
    e.preventDefault();
    if (!nodeModalData.title.trim()) return;

    if (nodeModalData.id) {
      setData(prev => ({
        ...prev,
        nodes: prev.nodes.map(n => 
          n.id === nodeModalData.id ? { ...n, title: nodeModalData.title, url: nodeModalData.url } : n
        )
      }));
    } else {
      const newNode: BookNode = {
        id: `node-${Date.now()}`,
        title: nodeModalData.title,
        type: nodeModalData.type,
        url: nodeModalData.url,
        parentId: nodeModalData.parentId,
        lessonResources: []
      };
      setData(prev => ({ ...prev, nodes: [...prev.nodes, newNode] }));
      setSelectedId(newNode.id);
    }
    setShowNodeModal(false);
  };

  const handleDeleteNode = (id: string) => {
    if (confirm('Xóa mục này?')) {
      const idsToDelete = new Set<string>();
      const collectIds = (targetId: string) => {
        idsToDelete.add(targetId);
        data.nodes.filter(n => n.parentId === targetId).forEach(child => collectIds(child.id));
      };
      collectIds(id);
      setData(prev => ({ ...prev, nodes: prev.nodes.filter(n => !idsToDelete.has(n.id)) }));
      if (selectedId && idsToDelete.has(selectedId)) setSelectedId(null);
    }
  };

  const handleVerifyTeacher = (e: React.FormEvent) => {
    e.preventDefault();
    if (teacherPass === '1234') {
      setRole('teacher');
      setShowPassInput(false);
      setTeacherPass('');
      setPassError(false);
    } else {
      setPassError(true);
    }
  };

  const handleAddResource = (isGlobal: boolean) => {
    const title = prompt('Tên tài liệu:');
    const url = prompt('Link:');
    if (!title || !url) return;

    if (isGlobal) {
      setData(prev => ({ ...prev, globalResources: [...prev.globalResources, { id: `res-${Date.now()}`, title, url }] }));
    } else if (selectedId) {
      setData(prev => ({
        ...prev,
        nodes: prev.nodes.map(n => 
          n.id === selectedId ? { ...n, lessonResources: [...n.lessonResources, { id: `res-${Date.now()}`, title, url }] } : n
        )
      }));
    }
  };

  const handleDeleteResource = (resId: string, isGlobal: boolean) => {
    if (isGlobal) {
      setData(prev => ({ ...prev, globalResources: prev.globalResources.filter(r => r.id !== resId) }));
    } else {
      setData(prev => ({
        ...prev,
        nodes: prev.nodes.map(n => 
          n.id === selectedId ? { ...n, lessonResources: n.lessonResources.filter(r => r.id !== resId) } : n
        )
      }));
    }
  };

  // MÀN HÌNH CHỌN VAI TRÒ (LANDING PAGE)
  if (role === 'none') {
    return (
      <div className="h-screen w-full flex items-center justify-center bg-gray-50 p-6 overflow-hidden">
        <div className="max-w-4xl w-full grid grid-cols-1 md:grid-cols-2 gap-8">
          {/* Lựa chọn Học sinh */}
          <button 
            onClick={() => setRole('student')}
            className="group bg-white p-10 rounded-[40px] shadow-xl hover:shadow-2xl transition-all border-4 border-transparent hover:border-indigo-500 flex flex-col items-center text-center space-y-6"
          >
            <div className="w-20 h-20 bg-indigo-100 text-indigo-600 rounded-3xl flex items-center justify-center group-hover:rotate-6 transition-transform">
              <GraduationCap size={40} />
            </div>
            <div>
              <h2 className="text-2xl font-black text-gray-800 uppercase tracking-tight">Học sinh</h2>
              <p className="text-gray-500 mt-2 text-sm">Vào xem nội dung bài học và tài liệu giáo viên cung cấp.</p>
            </div>
            <div className="px-8 py-3 bg-indigo-600 text-white rounded-2xl font-black text-xs tracking-widest uppercase">Bắt đầu học</div>
          </button>

          {/* Lựa chọn Giáo viên */}
          <div className="relative group">
            {!showPassInput ? (
              <button 
                onClick={() => setShowPassInput(true)}
                className="w-full bg-white p-10 rounded-[40px] shadow-xl hover:shadow-2xl transition-all border-4 border-transparent hover:border-amber-500 flex flex-col items-center text-center space-y-6"
              >
                <div className="w-20 h-20 bg-amber-100 text-amber-600 rounded-3xl flex items-center justify-center group-hover:-rotate-6 transition-transform">
                  <ShieldCheck size={40} />
                </div>
                <div>
                  <h2 className="text-2xl font-black text-gray-800 uppercase tracking-tight">Giáo viên</h2>
                  <p className="text-gray-500 mt-2 text-sm">Đăng nhập để quản lý danh mục, bài giảng và tài liệu.</p>
                </div>
                <div className="px-8 py-3 bg-amber-500 text-white rounded-2xl font-black text-xs tracking-widest uppercase">Quản lý bài học</div>
              </button>
            ) : (
              <div className="bg-white p-10 rounded-[40px] shadow-2xl border-4 border-amber-500 flex flex-col items-center text-center space-y-4 animate-in zoom-in duration-200">
                <div className="w-16 h-16 bg-amber-100 text-amber-600 rounded-full flex items-center justify-center">
                  <KeyRound size={28} />
                </div>
                <h3 className="font-black text-gray-800 uppercase tracking-tighter">Nhập mật khẩu</h3>
                <form onSubmit={handleVerifyTeacher} className="w-full space-y-3">
                  <input 
                    type="password" autoFocus
                    value={teacherPass}
                    onChange={(e) => { setTeacherPass(e.target.value); setPassError(false); }}
                    placeholder="Mật khẩu (1234)"
                    className={`w-full px-4 py-3 bg-gray-50 border-2 rounded-xl text-center focus:outline-none ${passError ? 'border-red-400 animate-shake' : 'border-gray-100 focus:border-amber-400'}`}
                  />
                  {passError && <p className="text-red-500 text-[10px] font-bold uppercase">Sai mật khẩu!</p>}
                  <div className="flex gap-2 pt-2">
                    <button type="button" onClick={() => setShowPassInput(false)} className="flex-1 py-3 text-[10px] font-black text-gray-400 bg-gray-50 rounded-xl hover:bg-gray-100">HỦY</button>
                    <button type="submit" className="flex-2 py-3 px-6 text-[10px] font-black text-white bg-amber-500 rounded-xl shadow-lg hover:bg-amber-600 uppercase tracking-widest">XÁC NHẬN</button>
                  </div>
                </form>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  const isAdmin = role === 'teacher';

  return (
    <div className="flex h-screen bg-white overflow-hidden font-sans relative">

      {/* MODAL THÊM/SỬA MENU (FORM NHỎ) */}
      {showNodeModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/40 backdrop-blur-sm">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden animate-in fade-in zoom-in duration-200">
            <div className="p-8">
              <div className="flex justify-between items-center mb-6">
                <h3 className="font-black text-gray-800 uppercase tracking-tight text-sm">
                  {nodeModalData.id ? 'Cập nhật đề mục' : 'Thêm đề mục mới'}
                </h3>
                <button onClick={() => setShowNodeModal(false)} className="text-gray-300 hover:text-gray-500 transition-colors"><X size={20}/></button>
              </div>
              <form onSubmit={saveNode} className="space-y-5">
                <div>
                  <label className="text-[10px] font-black text-gray-400 uppercase mb-1.5 block">Tên mục hiển thị</label>
                  <input 
                    type="text" autoFocus value={nodeModalData.title}
                    onChange={(e) => setNodeModalData({...nodeModalData, title: e.target.value})}
                    placeholder="VD: Chương 1: Cơ bản..."
                    className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl focus:outline-none focus:border-indigo-400 font-bold text-gray-700"
                  />
                </div>
                <div>
                  <label className="text-[10px] font-black text-gray-400 uppercase mb-1.5 block">Đường dẫn liên kết (URL)</label>
                  <input 
                    type="text" value={nodeModalData.url}
                    onChange={(e) => setNodeModalData({...nodeModalData, url: e.target.value})}
                    placeholder="https://..."
                    className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl focus:outline-none focus:border-indigo-400 font-mono text-[11px]"
                  />
                  <p className="mt-2 text-[9px] text-gray-400 italic font-medium leading-relaxed">Gắn link Wikipedia, Google Docs, PDF hoặc video để nhúng nội dung.</p>
                </div>
                <button type="submit" className="w-full py-4 text-xs font-black text-white bg-indigo-600 rounded-xl shadow-lg hover:bg-indigo-700 transition-all uppercase tracking-widest flex items-center justify-center gap-2">
                  <Save size={14} /> Lưu thay đổi
                </button>
              </form>
            </div>
          </div>
        </div>
      )}

      {/* PANEL 1: SIDEBAR */}
      <aside className={`w-72 border-r flex flex-col shrink-0 transition-all duration-500 ${isAdmin ? 'bg-amber-50/20 border-amber-100' : 'bg-white border-gray-100'}`}>
        <div className={`p-6 border-b flex justify-between items-center text-white transition-colors duration-500 ${isAdmin ? 'bg-amber-500' : 'bg-indigo-600'}`}>
          <div className="flex items-center space-x-2">
            <Book size={20} />
            <h2 className="font-black text-lg tracking-tight uppercase">Danh mục</h2>
          </div>
          {isAdmin && (
            <button onClick={() => openAddNodeModal(null, 'folder')} className="p-1.5 bg-white/20 hover:bg-white/40 rounded-xl transition-all active:scale-90"><Plus size={18} /></button>
          )}
        </div>

        <div className="flex-1 overflow-y-auto p-4 custom-scrollbar">
          {data.nodes.filter(n => n.parentId === null).map(rootNode => (
            <TreeItem 
              key={rootNode.id}
              node={rootNode}
              allNodes={data.nodes}
              selectedId={selectedId}
              isAdmin={isAdmin}
              onSelect={handleSelectNode}
              onAdd={openAddNodeModal}
              onEdit={openEditNodeModal}
              onDelete={handleDeleteNode}
              level={0}
            />
          ))}
        </div>

        <div className="p-4 border-t border-gray-100">
           <button 
            onClick={() => { if(confirm('Quay lại màn hình chính?')) setRole('none'); }}
            className="w-full flex items-center justify-center space-x-2 px-4 py-3 rounded-xl text-[10px] font-black uppercase bg-gray-50 text-gray-400 hover:bg-gray-100 hover:text-gray-600 transition-all shadow-sm"
           >
             <LogOut size={14} />
             <span>Thoát chế độ {isAdmin ? 'GV' : 'HS'}</span>
           </button>
        </div>
      </aside>

      {/* PANEL 2: CONTENT AREA */}
      <main className="flex-1 flex flex-col min-w-0 relative bg-white">
        {selectedNode ? (
          <>
            <header className="px-8 py-4 border-b border-gray-50 bg-white flex justify-between items-center h-20 shrink-0 z-10">
                <div className="flex items-center space-x-4 min-w-0">
                    <div className={`p-2.5 rounded-xl shrink-0 ${selectedNode.type === 'folder' ? 'bg-amber-50 text-amber-500' : 'bg-indigo-50 text-indigo-500'}`}>
                        {selectedNode.type === 'folder' ? <Book size={18}/> : <Globe size={18}/>}
                    </div>
                    <div className="min-w-0">
                      <h1 className="text-lg font-black text-gray-800 truncate tracking-tight">{selectedNode.title}</h1>
                      <p className="text-[10px] text-gray-400 font-mono truncate max-w-xs">{selectedNode.url || 'Chưa gắn link'}</p>
                    </div>
                </div>

                <div className="flex space-x-2 shrink-0">
                    {isAdmin && (
                        <button onClick={() => openEditNodeModal(selectedNode)} className="p-2.5 text-amber-600 bg-amber-50 rounded-xl hover:bg-amber-100 transition-all border border-amber-100/50 shadow-sm"><Pencil size={18} /></button>
                    )}
                    {selectedNode.url && (
                        <a href={selectedNode.url} target="_blank" rel="noreferrer" className="p-2.5 text-gray-400 bg-gray-50 rounded-xl hover:bg-gray-100 border border-gray-200/50 shadow-sm"><Maximize2 size={18} /></a>
                    )}
                </div>
            </header>

            <div className="flex-1 bg-gray-50 relative overflow-hidden">
              {iframeLoading && (
                <div className="absolute inset-0 z-10 flex flex-col items-center justify-center bg-white/70 backdrop-blur-[1px]">
                  <Loader2 size={32} className="animate-spin text-indigo-500 mb-3" />
                  <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Đang tải...</p>
                </div>
              )}
              {selectedNode.url ? (
                <iframe 
                    src={selectedNode.url} 
                    className="w-full h-full border-none shadow-inner bg-white"
                    onLoad={() => setIframeLoading(false)}
                    title={selectedNode.title}
                    allowFullScreen
                />
              ) : (
                <div className="absolute inset-0 flex flex-col items-center justify-center text-gray-300 p-10 text-center">
                    <Globe size={60} className="mb-4 opacity-5" />
                    <p className="text-sm font-bold opacity-30 italic">Đề mục này chưa có liên kết nội dung</p>
                    {isAdmin && (
                      <button onClick={() => openEditNodeModal(selectedNode)} className="mt-4 px-6 py-3 bg-amber-500 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg shadow-amber-100">Gắn link ngay</button>
                    )}
                </div>
              )}
            </div>
          </>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-gray-200 p-10">
            <div className="p-10 bg-gray-50 rounded-full mb-6">
              <Book size={80} className="opacity-10" />
            </div>
            <h2 className="text-xl font-black uppercase tracking-tighter text-gray-300">Chọn một bài học từ danh mục bên trái</h2>
            <p className="mt-2 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Hệ thống bài giảng trực tuyến</p>
          </div>
        )}
      </main>

      {/* PANEL 3: RESOURCES */}
      <aside className="w-60 border-l border-gray-50 bg-gray-50/30 flex flex-col shrink-0">
        <div className="h-1/2 flex flex-col border-b border-gray-100 overflow-hidden">
          <div className="p-4 border-b border-gray-100 bg-white flex justify-between items-center sticky top-0 z-10">
            <h3 className="font-black text-[9px] text-gray-400 uppercase tracking-widest flex items-center">
              <LinkIcon size={12} className="mr-2 text-indigo-400" /> Tài liệu bài học
            </h3>
            {isAdmin && selectedNode && (
              <button onClick={() => handleAddResource(false)} className="text-indigo-600 hover:scale-110 transition-transform p-1 bg-indigo-50 rounded-lg"><Plus size={14} /></button>
            )}
          </div>
          <div className="flex-1 overflow-y-auto p-3 space-y-2 custom-scrollbar bg-white/50">
            {selectedNode?.lessonResources.map(res => (
                <div key={res.id} className="group bg-white p-3 rounded-xl border border-gray-100 shadow-sm flex justify-between items-center transition-all hover:border-indigo-200 hover:shadow-md">
                  <a href={res.url} target="_blank" rel="noreferrer" className="text-[10px] text-indigo-600 font-bold hover:underline truncate mr-2">
                    {res.title}
                  </a>
                  {isAdmin && (
                    <button onClick={() => handleDeleteResource(res.id, false)} className="text-red-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"><X size={12} /></button>
                  )}
                </div>
            ))}
            {(!selectedNode || selectedNode.lessonResources.length === 0) && (
                <div className="flex flex-col items-center py-10 opacity-20">
                  <X size={20} className="mb-2" />
                  <p className="text-[9px] text-center italic uppercase font-bold">Chưa có tài liệu</p>
                </div>
            )}
          </div>
        </div>

        <div className="h-1/2 flex flex-col bg-white overflow-hidden">
          <div className="p-4 border-b border-gray-100 bg-gray-50/50 flex justify-between items-center sticky top-0 z-10">
            <h3 className="font-black text-[9px] text-indigo-900 uppercase tracking-widest flex items-center">
              <Settings size={12} className="mr-2" /> Tài liệu chung
            </h3>
            {isAdmin && (
              <button onClick={() => handleAddResource(true)} className="text-indigo-600 hover:scale-110 transition-transform p-1 bg-white rounded-lg shadow-sm"><Plus size={14} /></button>
            )}
          </div>
          <div className="flex-1 overflow-y-auto p-3 space-y-2 custom-scrollbar">
            {data.globalResources.map(res => (
                <div key={res.id} className="group bg-gray-50/80 p-3 rounded-xl border border-gray-100 flex justify-between items-center hover:bg-white hover:border-indigo-100 transition-all">
                  <a href={res.url} target="_blank" rel="noreferrer" className="text-[10px] text-gray-700 font-bold truncate mr-2">
                    {res.title}
                  </a>
                  {isAdmin && (
                    <button onClick={() => handleDeleteResource(res.id, true)} className="text-red-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"><X size={12} /></button>
                  )}
                </div>
            ))}
          </div>
        </div>
      </aside>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 3px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; }
        @keyframes shake {
          0%, 100% { transform: translateX(0); }
          25% { transform: translateX(-4px); }
          75% { transform: translateX(4px); }
        }
        .animate-shake { animation: shake 0.2s ease-in-out 0s 2; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { 
  Book, 
  ExternalLink, 
  Link as LinkIcon, 
  X, 
  Lock, 
  Unlock,
  Pencil,
  Plus,
  Settings,
  ChevronRight,
  ShieldCheck,
  Globe,
  Maximize2,
  Save,
  Loader2,
  LogOut,
  GraduationCap,
  KeyRound,
  Trash2,
  AlertTriangle
} from 'lucide-react';
import { BookNode, NodeType, AppData, ResourceLink } from './types';
import { INITIAL_DATA } from './constants';
import TreeItem from './components/TreeItem';

const App: React.FC = () => {
  const [data, setData] = useState<AppData>(() => {
    const saved = localStorage.getItem('teacher_app_data_v6');
    return saved ? JSON.parse(saved) : INITIAL_DATA;
  });

  const [role, setRole] = useState<'none' | 'teacher' | 'student'>('none');
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [iframeLoading, setIframeLoading] = useState(false);

  // States cho các Modal
  const [showPassInput, setShowPassInput] = useState(false);
  const [teacherPass, setTeacherPass] = useState('');
  const [passError, setPassError] = useState(false);

  // Modal thêm/sửa Menu
  const [showNodeModal, setShowNodeModal] = useState(false);
  const [nodeModalData, setNodeModalData] = useState<{
    id?: string;
    parentId: string | null;
    type: NodeType;
    title: string;
    url: string;
  }>({ parentId: null, type: 'lesson', title: '', url: '' });

  // Modal thêm/sửa Tài liệu (Resource)
  const [showResourceModal, setShowResourceModal] = useState(false);
  const [resourceModalData, setResourceModalData] = useState({
    isGlobal: false,
    title: '',
    url: ''
  });

  // Modal xác nhận Xóa
  const [showDeleteConfirm, setShowDeleteConfirm] = useState<{
    type: 'node' | 'resource';
    id: string;
    isGlobal?: boolean;
    title: string;
  } | null>(null);

  useEffect(() => {
    localStorage.setItem('teacher_app_data_v6', JSON.stringify(data));
  }, [data]);

  const selectedNode = data.nodes.find(n => n.id === selectedId);

  const handleSelectNode = (id: string) => {
    setSelectedId(id);
    const node = data.nodes.find(n => n.id === id);
    if (node && node.url) {
      setIframeLoading(true);
    }
  };

  // QUẢN LÝ MENU (NODE)
  const openAddNodeModal = (parentId: string | null, type: NodeType) => {
    setNodeModalData({ parentId, type, title: '', url: '' });
    setShowNodeModal(true);
  };

  const openEditNodeModal = (node: BookNode) => {
    setNodeModalData({ 
      id: node.id, 
      parentId: node.parentId, 
      type: node.type, 
      title: node.title, 
      url: node.url 
    });
    setShowNodeModal(true);
  };

  const saveNode = (e: React.FormEvent) => {
    e.preventDefault();
    if (!nodeModalData.title.trim()) return;

    if (nodeModalData.id) {
      setData(prev => ({
        ...prev,
        nodes: prev.nodes.map(n => 
          n.id === nodeModalData.id ? { ...n, title: nodeModalData.title, url: nodeModalData.url } : n
        )
      }));
    } else {
      const newNode: BookNode = {
        id: `node-${Date.now()}`,
        title: nodeModalData.title,
        type: nodeModalData.type,
        url: nodeModalData.url,
        parentId: nodeModalData.parentId,
        lessonResources: []
      };
      setData(prev => ({ ...prev, nodes: [...prev.nodes, newNode] }));
      setSelectedId(newNode.id);
    }
    setShowNodeModal(false);
  };

  // QUẢN LÝ TÀI LIỆU (RESOURCE)
  const openResourceModal = (isGlobal: boolean) => {
    setResourceModalData({ isGlobal, title: '', url: '' });
    setShowResourceModal(true);
  };

  const saveResource = (e: React.FormEvent) => {
    e.preventDefault();
    const { title, url, isGlobal } = resourceModalData;
    if (!title.trim() || !url.trim()) return;

    const newRes: ResourceLink = { id: `res-${Date.now()}`, title, url };

    if (isGlobal) {
      setData(prev => ({
        ...prev,
        globalResources: [...prev.globalResources, newRes]
      }));
    } else if (selectedId) {
      setData(prev => ({
        ...prev,
        nodes: prev.nodes.map(n => 
          n.id === selectedId 
            ? { ...n, lessonResources: [...n.lessonResources, newRes] } 
            : n
        )
      }));
    }
    setShowResourceModal(false);
  };

  // XỬ LÝ XÓA
  const executeDelete = () => {
    if (!showDeleteConfirm) return;
    const { type, id, isGlobal } = showDeleteConfirm;

    if (type === 'node') {
      const idsToDelete = new Set<string>();
      const collectIds = (targetId: string) => {
        idsToDelete.add(targetId);
        data.nodes.filter(n => n.parentId === targetId).forEach(child => collectIds(child.id));
      };
      collectIds(id);
      setData(prev => ({ ...prev, nodes: prev.nodes.filter(n => !idsToDelete.has(n.id)) }));
      if (selectedId && idsToDelete.has(selectedId)) setSelectedId(null);
    } else {
      if (isGlobal) {
        setData(prev => ({ ...prev, globalResources: prev.globalResources.filter(r => r.id !== id) }));
      } else {
        setData(prev => ({
          ...prev,
          nodes: prev.nodes.map(n => 
            n.id === selectedId ? { ...n, lessonResources: n.lessonResources.filter(r => r.id !== id) } : n
          )
        }));
      }
    }
    setShowDeleteConfirm(null);
  };

  const handleVerifyTeacher = (e: React.FormEvent) => {
    e.preventDefault();
    if (teacherPass === '1234') {
      setRole('teacher');
      setShowPassInput(false);
      setTeacherPass('');
      setPassError(false);
    } else {
      setPassError(true);
    }
  };

  // LANDING PAGE
  if (role === 'none') {
    return (
      <div className="h-screen w-full flex items-center justify-center bg-gray-50 p-6 overflow-hidden">
        <div className="max-w-4xl w-full grid grid-cols-1 md:grid-cols-2 gap-8">
          <button 
            onClick={() => setRole('student')}
            className="group bg-white p-10 rounded-[40px] shadow-xl hover:shadow-2xl transition-all border-4 border-transparent hover:border-indigo-500 flex flex-col items-center text-center space-y-6"
          >
            <div className="w-20 h-20 bg-indigo-100 text-indigo-600 rounded-3xl flex items-center justify-center group-hover:rotate-6 transition-transform">
              <GraduationCap size={40} />
            </div>
            <div>
              <h2 className="text-2xl font-black text-gray-800 uppercase tracking-tight">Học sinh</h2>
              <p className="text-gray-500 mt-2 text-sm">Vào xem nội dung bài học và tài liệu giáo viên cung cấp.</p>
            </div>
            <div className="px-8 py-3 bg-indigo-600 text-white rounded-2xl font-black text-xs tracking-widest uppercase">Bắt đầu học</div>
          </button>

          <div className="relative group">
            {!showPassInput ? (
              <button 
                onClick={() => setShowPassInput(true)}
                className="w-full h-full bg-white p-10 rounded-[40px] shadow-xl hover:shadow-2xl transition-all border-4 border-transparent hover:border-amber-500 flex flex-col items-center text-center space-y-6"
              >
                <div className="w-20 h-20 bg-amber-100 text-amber-600 rounded-3xl flex items-center justify-center group-hover:-rotate-6 transition-transform">
                  <ShieldCheck size={40} />
                </div>
                <div>
                  <h2 className="text-2xl font-black text-gray-800 uppercase tracking-tight">Giáo viên</h2>
                  <p className="text-gray-500 mt-2 text-sm">Đăng nhập để quản lý danh mục, bài giảng và tài liệu.</p>
                </div>
                <div className="px-8 py-3 bg-amber-500 text-white rounded-2xl font-black text-xs tracking-widest uppercase">Quản lý bài học</div>
              </button>
            ) : (
              <div className="bg-white p-10 rounded-[40px] shadow-2xl border-4 border-amber-500 flex flex-col items-center text-center space-y-4 animate-in zoom-in duration-200 h-full justify-center">
                <div className="w-16 h-16 bg-amber-100 text-amber-600 rounded-full flex items-center justify-center">
                  <KeyRound size={28} />
                </div>
                <h3 className="font-black text-gray-800 uppercase tracking-tighter">Xác minh quyền GV</h3>
                <form onSubmit={handleVerifyTeacher} className="w-full space-y-3">
                  <input 
                    type="password" autoFocus
                    value={teacherPass}
                    onChange={(e) => { setTeacherPass(e.target.value); setPassError(false); }}
                    placeholder="Mật khẩu (1234)"
                    className={`w-full px-4 py-3 bg-gray-50 border-2 rounded-xl text-center focus:outline-none ${passError ? 'border-red-400 animate-shake' : 'border-gray-100 focus:border-amber-400'}`}
                  />
                  {passError && <p className="text-red-500 text-[10px] font-bold uppercase">Mật khẩu không đúng!</p>}
                  <div className="flex gap-2 pt-2">
                    <button type="button" onClick={() => setShowPassInput(false)} className="flex-1 py-3 text-[10px] font-black text-gray-400 bg-gray-50 rounded-xl hover:bg-gray-100 uppercase">Hủy</button>
                    <button type="submit" className="flex-2 py-3 px-6 text-[10px] font-black text-white bg-amber-500 rounded-xl shadow-lg hover:bg-amber-600 uppercase tracking-widest">Vào Quản lý</button>
                  </div>
                </form>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  const isAdmin = role === 'teacher';

  return (
    <div className="flex h-screen bg-white overflow-hidden font-sans relative">

      {/* 1. MODAL THÊM/SỬA MENU */}
      {showNodeModal && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-black/40 backdrop-blur-sm">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden animate-in zoom-in duration-200">
            <div className="p-8">
              <div className="flex justify-between items-center mb-6">
                <h3 className="font-black text-gray-800 uppercase tracking-tight text-sm">
                  {nodeModalData.id ? 'Cập nhật mục' : 'Thêm mục mới'}
                </h3>
                <button onClick={() => setShowNodeModal(false)} className="text-gray-300 hover:text-gray-500 transition-colors"><X size={20}/></button>
              </div>
              <form onSubmit={saveNode} className="space-y-5">
                <div>
                  <label className="text-[10px] font-black text-gray-400 uppercase mb-1.5 block">Tên mục hiển thị</label>
                  <input 
                    type="text" autoFocus value={nodeModalData.title}
                    onChange={(e) => setNodeModalData({...nodeModalData, title: e.target.value})}
                    placeholder="VD: Bài 1: Khái niệm..."
                    className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl focus:outline-none focus:border-indigo-400 font-bold text-gray-700"
                  />
                </div>
                <div>
                  <label className="text-[10px] font-black text-gray-400 uppercase mb-1.5 block">Link nội dung (URL)</label>
                  <input 
                    type="text" value={nodeModalData.url}
                    onChange={(e) => setNodeModalData({...nodeModalData, url: e.target.value})}
                    placeholder="https://..."
                    className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl focus:outline-none focus:border-indigo-400 font-mono text-[11px]"
                  />
                </div>
                <button type="submit" className="w-full py-4 text-xs font-black text-white bg-indigo-600 rounded-xl shadow-lg hover:bg-indigo-700 transition-all uppercase tracking-widest flex items-center justify-center gap-2">
                  <Save size={14} /> Lưu lại
                </button>
              </form>
            </div>
          </div>
        </div>
      )}

      {/* 2. MODAL THÊM TÀI LIỆU (RESOURCE) */}
      {showResourceModal && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-black/40 backdrop-blur-sm">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden animate-in zoom-in duration-200">
            <div className="p-8">
              <div className="flex justify-between items-center mb-6">
                <h3 className="font-black text-gray-800 uppercase tracking-tight text-sm">
                  Thêm {resourceModalData.isGlobal ? 'tài liệu chung' : 'tài liệu bài học'}
                </h3>
                <button onClick={() => setShowResourceModal(false)} className="text-gray-300 hover:text-gray-500 transition-colors"><X size={20}/></button>
              </div>
              <form onSubmit={saveResource} className="space-y-5">
                <div>
                  <label className="text-[10px] font-black text-gray-400 uppercase mb-1.5 block">Tên tài liệu</label>
                  <input 
                    type="text" autoFocus value={resourceModalData.title}
                    onChange={(e) => setResourceModalData({...resourceModalData, title: e.target.value})}
                    placeholder="VD: File thực hành..."
                    className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl focus:outline-none focus:border-indigo-400 font-bold text-gray-700"
                  />
                </div>
                <div>
                  <label className="text-[10px] font-black text-gray-400 uppercase mb-1.5 block">Link tài liệu (URL)</label>
                  <input 
                    type="text" value={resourceModalData.url}
                    onChange={(e) => setResourceModalData({...resourceModalData, url: e.target.value})}
                    placeholder="https://drive.google.com/..."
                    className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl focus:outline-none focus:border-indigo-400 font-mono text-[11px]"
                  />
                </div>
                <button type="submit" className="w-full py-4 text-xs font-black text-white bg-blue-600 rounded-xl shadow-lg hover:bg-blue-700 transition-all uppercase tracking-widest flex items-center justify-center gap-2">
                  <Plus size={14} /> Thêm tài liệu
                </button>
              </form>
            </div>
          </div>
        </div>
      )}

      {/* 3. MODAL XÁC NHẬN XÓA */}
      {showDeleteConfirm && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-xs overflow-hidden animate-in zoom-in duration-200">
            <div className="p-8 text-center">
              <div className="w-16 h-16 bg-red-100 text-red-500 rounded-full flex items-center justify-center mx-auto mb-4">
                <AlertTriangle size={32} />
              </div>
              <h3 className="font-black text-gray-800 uppercase text-sm mb-2">Xác nhận xóa?</h3>
              <p className="text-xs text-gray-500 mb-6">Bạn có chắc chắn muốn xóa mục <span className="font-bold text-gray-800">"{showDeleteConfirm.title}"</span> không?</p>
              <div className="flex gap-2">
                <button onClick={() => setShowDeleteConfirm(null)} className="flex-1 py-3 text-[10px] font-black text-gray-400 bg-gray-50 rounded-xl hover:bg-gray-100 uppercase">Hủy</button>
                <button onClick={executeDelete} className="flex-1 py-3 text-[10px] font-black text-white bg-red-500 rounded-xl hover:bg-red-600 shadow-lg shadow-red-100 uppercase">Xóa ngay</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* PANEL 1: SIDEBAR */}
      <aside className={`w-72 border-r flex flex-col shrink-0 transition-all duration-500 ${isAdmin ? 'bg-amber-50/20 border-amber-100' : 'bg-white border-gray-100'}`}>
        <div className={`p-6 border-b flex justify-between items-center text-white transition-colors duration-500 ${isAdmin ? 'bg-amber-500' : 'bg-indigo-600'}`}>
          <div className="flex items-center space-x-2">
            <Book size={20} />
            <h2 className="font-black text-lg tracking-tight uppercase">Danh mục</h2>
          </div>
          {isAdmin && (
            <button onClick={() => openAddNodeModal(null, 'folder')} className="p-1.5 bg-white/20 hover:bg-white/40 rounded-xl transition-all active:scale-90"><Plus size={18} /></button>
          )}
        </div>

        <div className="flex-1 overflow-y-auto p-4 custom-scrollbar">
          {data.nodes.filter(n => n.parentId === null).map(rootNode => (
            <TreeItem 
              key={rootNode.id}
              node={rootNode}
              allNodes={data.nodes}
              selectedId={selectedId}
              isAdmin={isAdmin}
              onSelect={handleSelectNode}
              onAdd={openAddNodeModal}
              onEdit={openEditNodeModal}
              onDelete={(id) => setShowDeleteConfirm({ type: 'node', id, title: data.nodes.find(n => n.id === id)?.title || '' })}
              level={0}
            />
          ))}
        </div>

        <div className="p-4 border-t border-gray-100">
           <button 
            onClick={() => setRole('none')}
            className="w-full flex items-center justify-center space-x-2 px-4 py-3 rounded-xl text-[10px] font-black uppercase bg-gray-50 text-gray-400 hover:bg-gray-100 hover:text-gray-600 transition-all shadow-sm"
           >
             <LogOut size={14} />
             <span>Thoát chế độ {isAdmin ? 'GV' : 'HS'}</span>
           </button>
        </div>
      </aside>

      {/* PANEL 2: CONTENT AREA */}
      <main className="flex-1 flex flex-col min-w-0 relative bg-white">
        {selectedNode ? (
          <>
            <header className="px-8 py-4 border-b border-gray-50 bg-white flex justify-between items-center h-20 shrink-0 z-10">
                <div className="flex items-center space-x-4 min-w-0">
                    <div className={`p-2.5 rounded-xl shrink-0 ${selectedNode.type === 'folder' ? 'bg-amber-50 text-amber-500' : 'bg-indigo-50 text-indigo-500'}`}>
                        {selectedNode.type === 'folder' ? <Book size={18}/> : <Globe size={18}/>}
                    </div>
                    <div className="min-w-0">
                      <h1 className="text-lg font-black text-gray-800 truncate tracking-tight">{selectedNode.title}</h1>
                      <p className="text-[10px] text-gray-400 font-mono truncate max-w-xs">{selectedNode.url || 'Chưa gắn link'}</p>
                    </div>
                </div>

                <div className="flex space-x-2 shrink-0">
                    {isAdmin && (
                        <button onClick={() => openEditNodeModal(selectedNode)} className="p-2.5 text-amber-600 bg-amber-50 rounded-xl hover:bg-amber-100 transition-all border border-amber-100/50 shadow-sm"><Pencil size={18} /></button>
                    )}
                    {selectedNode.url && (
                        <a href={selectedNode.url} target="_blank" rel="noreferrer" className="p-2.5 text-gray-400 bg-gray-50 rounded-xl hover:bg-gray-100 border border-gray-200/50 shadow-sm"><Maximize2 size={18} /></a>
                    )}
                </div>
            </header>

            <div className="flex-1 bg-gray-50 relative overflow-hidden">
              {iframeLoading && (
                <div className="absolute inset-0 z-10 flex flex-col items-center justify-center bg-white/70 backdrop-blur-[1px]">
                  <Loader2 size={32} className="animate-spin text-indigo-500 mb-3" />
                  <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Đang tải nội dung...</p>
                </div>
              )}
              {selectedNode.url ? (
                <iframe 
                    src={selectedNode.url} 
                    className="w-full h-full border-none shadow-inner bg-white"
                    onLoad={() => setIframeLoading(false)}
                    title={selectedNode.title}
                    allowFullScreen
                />
              ) : (
                <div className="absolute inset-0 flex flex-col items-center justify-center text-gray-300 p-10 text-center">
                    <Globe size={60} className="mb-4 opacity-5" />
                    <p className="text-sm font-bold opacity-30 italic">Đề mục này chưa có liên kết nội dung</p>
                    {isAdmin && (
                      <button onClick={() => openEditNodeModal(selectedNode)} className="mt-4 px-6 py-3 bg-amber-500 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg shadow-amber-100">Gắn link ngay</button>
                    )}
                </div>
              )}
            </div>
          </>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-gray-200 p-10">
            <div className="p-10 bg-gray-50 rounded-full mb-6">
              <Book size={80} className="opacity-10" />
            </div>
            <h2 className="text-xl font-black uppercase tracking-tighter text-gray-300">Chọn một bài học từ danh mục bên trái</h2>
          </div>
        )}
      </main>

      {/* PANEL 3: RESOURCES */}
      <aside className="w-60 border-l border-gray-50 bg-gray-50/30 flex flex-col shrink-0">
        {/* Tài liệu bài học */}
        <div className="h-1/2 flex flex-col border-b border-gray-100 overflow-hidden">
          <div className="p-4 border-b border-gray-100 bg-white flex justify-between items-center sticky top-0 z-10">
            <h3 className="font-black text-[9px] text-gray-400 uppercase tracking-widest flex items-center">
              <LinkIcon size={12} className="mr-2 text-indigo-400" /> Tài liệu bài học
            </h3>
            {isAdmin && selectedNode && (
              <button 
                onClick={() => openResourceModal(false)} 
                className="text-indigo-600 hover:scale-110 transition-transform p-1.5 bg-indigo-50 rounded-lg"
              >
                <Plus size={14} />
              </button>
            )}
          </div>
          <div className="flex-1 overflow-y-auto p-3 space-y-2 custom-scrollbar bg-white/50">
            {selectedNode?.lessonResources.map(res => (
                <div key={res.id} className="group bg-white p-3 rounded-xl border border-gray-100 shadow-sm flex justify-between items-center transition-all hover:border-indigo-200 hover:shadow-md">
                  <a href={res.url} target="_blank" rel="noreferrer" className="text-[10px] text-indigo-600 font-bold hover:underline truncate mr-2">
                    {res.title}
                  </a>
                  {isAdmin && (
                    <button 
                      onClick={() => setShowDeleteConfirm({ type: 'resource', id: res.id, isGlobal: false, title: res.title })} 
                      className="text-red-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                    >
                      <Trash2 size={12} />
                    </button>
                  )}
                </div>
            ))}
            {(!selectedNode || selectedNode.lessonResources.length === 0) && (
                <div className="flex flex-col items-center py-10 opacity-20">
                  <X size={20} className="mb-2" />
                  <p className="text-[9px] text-center italic uppercase font-bold">Chưa có tài liệu</p>
                </div>
            )}
          </div>
        </div>

        {/* Tài liệu chung */}
        <div className="h-1/2 flex flex-col bg-white overflow-hidden">
          <div className="p-4 border-b border-gray-100 bg-gray-50/50 flex justify-between items-center sticky top-0 z-10">
            <h3 className="font-black text-[9px] text-indigo-900 uppercase tracking-widest flex items-center">
              <Settings size={12} className="mr-2" /> Tài liệu chung
            </h3>
            {isAdmin && (
              <button 
                onClick={() => openResourceModal(true)} 
                className="text-indigo-600 hover:scale-110 transition-transform p-1.5 bg-white rounded-lg shadow-sm"
              >
                <Plus size={14} />
              </button>
            )}
          </div>
          <div className="flex-1 overflow-y-auto p-3 space-y-2 custom-scrollbar">
            {data.globalResources.map(res => (
                <div key={res.id} className="group bg-gray-50/80 p-3 rounded-xl border border-gray-100 flex justify-between items-center hover:bg-white hover:border-indigo-100 transition-all">
                  <a href={res.url} target="_blank" rel="noreferrer" className="text-[10px] text-gray-700 font-bold truncate mr-2">
                    {res.title}
                  </a>
                  {isAdmin && (
                    <button 
                      onClick={() => setShowDeleteConfirm({ type: 'resource', id: res.id, isGlobal: true, title: res.title })} 
                      className="text-red-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                    >
                      <Trash2 size={12} />
                    </button>
                  )}
                </div>
            ))}
          </div>
        </div>
      </aside>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 3px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; }
        @keyframes shake {
          0%, 100% { transform: translateX(0); }
          25% { transform: translateX(-4px); }
          75% { transform: translateX(4px); }
        }
        .animate-shake { animation: shake 0.2s ease-in-out 0s 2; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback } from 'react';
import { 
  Book, Link as LinkIcon, X, Pencil, Plus, Settings, Globe, Maximize2, Save, 
  Loader2, LogOut, GraduationCap, KeyRound, Trash2, AlertTriangle, Cloud, CloudCheck, CloudOff
} from 'lucide-react';
import { createClient } from '@supabase/supabase-js';
import { BookNode, NodeType, AppData, ResourceLink } from './types';
import { INITIAL_DATA } from './constants';
import TreeItem from './components/TreeItem';

// ==========================================
// CẤU HÌNH SUPABASE CỦA BẠN TẠI ĐÂY
// ==========================================
const SUPABASE_URL = 'URL_CỦA_BẠN'; // Thay bằng URL dự án Supabase
const SUPABASE_ANON_KEY = 'KEY_CỦA_BẠN'; // Thay bằng Anon Key
// ==========================================

const supabase = (SUPABASE_URL !== 'URL_CỦA_BẠN') 
  ? createClient(SUPABASE_URL, SUPABASE_ANON_KEY) 
  : null;

const App: React.FC = () => {
  const [data, setData] = useState<AppData>(INITIAL_DATA);
  const [role, setRole] = useState<'none' | 'teacher' | 'student'>('none');
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [iframeLoading, setIframeLoading] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [cloudStatus, setCloudStatus] = useState<'connected' | 'error' | 'local'>('local');

  // Modal States
  const [showPassInput, setShowPassInput] = useState(false);
  const [teacherPass, setTeacherPass] = useState('');
  const [passError, setPassError] = useState(false);
  const [showNodeModal, setShowNodeModal] = useState(false);
  const [nodeModalData, setNodeModalData] = useState<{ id?: string; parentId: string | null; type: NodeType; title: string; url: string; }>({ parentId: null, type: 'lesson', title: '', url: '' });
  const [showResourceModal, setShowResourceModal] = useState(false);
  const [resourceModalData, setResourceModalData] = useState({ isGlobal: false, title: '', url: '' });
  const [showDeleteConfirm, setShowDeleteConfirm] = useState<{ type: 'node' | 'resource'; id: string; isGlobal?: boolean; title: string; } | null>(null);

  // 1. TẢI DỮ LIỆU TỪ CLOUD (SUPABASE)
  const fetchCloudData = useCallback(async () => {
    if (!supabase) return;
    setIsSyncing(true);
    try {
      const { data: cloudRows, error } = await supabase
        .from('app_settings') // Tên bảng bạn tạo trên Supabase
        .select('data')
        .eq('id', 1) // Giả định dùng row id=1 để lưu cấu hình
        .single();

      if (error) throw error;
      if (cloudRows?.data) {
        setData(cloudRows.data);
        setCloudStatus('connected');
      }
    } catch (err) {
      console.error('Fetch error:', err);
      setCloudStatus('error');
      // Fallback sang LocalStorage nếu Cloud lỗi
      const saved = localStorage.getItem('teacher_app_data_v7');
      if (saved) setData(JSON.parse(saved));
    } finally {
      setIsSyncing(false);
    }
  }, []);

  // 2. LƯU DỮ LIỆU LÊN CLOUD
  const saveToCloud = async (newData: AppData) => {
    localStorage.setItem('teacher_app_data_v7', JSON.stringify(newData));
    if (!supabase || role !== 'teacher') return;

    setIsSyncing(true);
    try {
      const { error } = await supabase
        .from('app_settings')
        .upsert({ id: 1, data: newData }); // Cập nhật đè lên row id=1

      if (error) throw error;
      setCloudStatus('connected');
    } catch (err) {
      console.error('Save error:', err);
      setCloudStatus('error');
    } finally {
      setIsSyncing(false);
    }
  };

  useEffect(() => {
    fetchCloudData();
  }, [fetchCloudData]);

  const selectedNode = data.nodes.find(n => n.id === selectedId);

  const handleSelectNode = (id: string) => {
    setSelectedId(id);
    const node = data.nodes.find(n => n.id === id);
    if (node && node.url) setIframeLoading(true);
  };

  const updateData = (newData: AppData) => {
    setData(newData);
    saveToCloud(newData);
  };

  // QUẢN LÝ MENU
  const saveNode = (e: React.FormEvent) => {
    e.preventDefault();
    if (!nodeModalData.title.trim()) return;

    let nextNodes = [...data.nodes];
    if (nodeModalData.id) {
      nextNodes = nextNodes.map(n => n.id === nodeModalData.id ? { ...n, title: nodeModalData.title, url: nodeModalData.url } : n);
    } else {
      const newNode: BookNode = {
        id: `node-${Date.now()}`,
        title: nodeModalData.title,
        type: nodeModalData.type,
        url: nodeModalData.url,
        parentId: nodeModalData.parentId,
        lessonResources: []
      };
      nextNodes.push(newNode);
      setSelectedId(newNode.id);
    }
    updateData({ ...data, nodes: nextNodes });
    setShowNodeModal(false);
  };

  // QUẢN LÝ TÀI LIỆU
  const saveResource = (e: React.FormEvent) => {
    e.preventDefault();
    const { title, url, isGlobal } = resourceModalData;
    if (!title.trim() || !url.trim()) return;
    const newRes: ResourceLink = { id: `res-${Date.now()}`, title, url };

    if (isGlobal) {
      updateData({ ...data, globalResources: [...data.globalResources, newRes] });
    } else if (selectedId) {
      const nextNodes = data.nodes.map(n => n.id === selectedId ? { ...n, lessonResources: [...n.lessonResources, newRes] } : n);
      updateData({ ...data, nodes: nextNodes });
    }
    setShowResourceModal(false);
  };

  const executeDelete = () => {
    if (!showDeleteConfirm) return;
    const { type, id, isGlobal } = showDeleteConfirm;
    let nextData = { ...data };

    if (type === 'node') {
      const idsToDelete = new Set<string>();
      const collectIds = (targetId: string) => {
        idsToDelete.add(targetId);
        data.nodes.filter(n => n.parentId === targetId).forEach(child => collectIds(child.id));
      };
      collectIds(id);
      nextData.nodes = data.nodes.filter(n => !idsToDelete.has(n.id));
      if (selectedId && idsToDelete.has(selectedId)) setSelectedId(null);
    } else {
      if (isGlobal) {
        nextData.globalResources = data.globalResources.filter(r => r.id !== id);
      } else {
        nextData.nodes = data.nodes.map(n => n.id === selectedId ? { ...n, lessonResources: n.lessonResources.filter(r => r.id !== id) } : n);
      }
    }
    updateData(nextData);
    setShowDeleteConfirm(null);
  };

  const handleVerifyTeacher = (e: React.FormEvent) => {
    e.preventDefault();
    if (teacherPass === '1234') {
      setRole('teacher');
      setShowPassInput(false);
      setTeacherPass('');
    } else setPassError(true);
  };

  if (role === 'none') {
    return (
      <div className="h-screen w-full flex items-center justify-center bg-gray-50 p-6 overflow-hidden">
        <div className="max-w-4xl w-full grid grid-cols-1 md:grid-cols-2 gap-8">
          <button onClick={() => setRole('student')} className="group bg-white p-10 rounded-[40px] shadow-xl hover:shadow-2xl transition-all border-4 border-transparent hover:border-indigo-500 flex flex-col items-center text-center space-y-6">
            <div className="w-20 h-20 bg-indigo-100 text-indigo-600 rounded-3xl flex items-center justify-center group-hover:rotate-6 transition-transform">
              <GraduationCap size={40} />
            </div>
            <div>
              <h2 className="text-2xl font-black text-gray-800 uppercase tracking-tight">Học sinh</h2>
              <p className="text-gray-500 mt-2 text-sm">Xem bài giảng Realtime từ Cloud.</p>
            </div>
            <div className="px-8 py-3 bg-indigo-600 text-white rounded-2xl font-black text-xs tracking-widest uppercase">Vào lớp ngay</div>
          </button>

          <div className="relative group">
            {!showPassInput ? (
              <button onClick={() => setShowPassInput(true)} className="w-full h-full bg-white p-10 rounded-[40px] shadow-xl hover:shadow-2xl transition-all border-4 border-transparent hover:border-amber-500 flex flex-col items-center text-center space-y-6">
                <div className="w-20 h-20 bg-amber-100 text-amber-600 rounded-3xl flex items-center justify-center group-hover:-rotate-6 transition-transform">
                  <ShieldCheck size={40} />
                </div>
                <h2 className="text-2xl font-black text-gray-800 uppercase tracking-tight">Giáo viên</h2>
                <div className="px-8 py-3 bg-amber-500 text-white rounded-2xl font-black text-xs tracking-widest uppercase">Soạn bài giảng</div>
              </button>
            ) : (
              <div className="bg-white p-10 rounded-[40px] shadow-2xl border-4 border-amber-500 flex flex-col items-center text-center space-y-4 animate-in zoom-in duration-200 h-full justify-center">
                <KeyRound size={28} className="text-amber-500" />
                <form onSubmit={handleVerifyTeacher} className="w-full space-y-3">
                  <input type="password" autoFocus value={teacherPass} onChange={(e) => { setTeacherPass(e.target.value); setPassError(false); }} placeholder="Mật khẩu (1234)" className={`w-full px-4 py-3 bg-gray-50 border-2 rounded-xl text-center focus:outline-none ${passError ? 'border-red-400 animate-shake' : 'border-gray-100 focus:border-amber-400'}`} />
                  <div className="flex gap-2">
                    <button type="button" onClick={() => setShowPassInput(false)} className="flex-1 py-3 text-[10px] font-black text-gray-400 uppercase">Hủy</button>
                    <button type="submit" className="flex-2 py-3 px-6 text-[10px] font-black text-white bg-amber-500 rounded-xl shadow-lg uppercase">Xác nhận</button>
                  </div>
                </form>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  const isAdmin = role === 'teacher';

  return (
    <div className="flex h-screen bg-white overflow-hidden font-sans relative">

      {/* MODALS */}
      {showNodeModal && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-black/40 backdrop-blur-sm">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm p-8 animate-in zoom-in duration-200">
            <h3 className="font-black text-gray-800 uppercase text-sm mb-6">{nodeModalData.id ? 'Cập nhật mục' : 'Thêm mục mới'}</h3>
            <form onSubmit={saveNode} className="space-y-4">
              <input type="text" autoFocus value={nodeModalData.title} onChange={(e) => setNodeModalData({...nodeModalData, title: e.target.value})} placeholder="Tên mục..." className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl font-bold" />
              <input type="text" value={nodeModalData.url} onChange={(e) => setNodeModalData({...nodeModalData, url: e.target.value})} placeholder="Link URL..." className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl font-mono text-xs" />
              <button type="submit" className="w-full py-4 text-xs font-black text-white bg-indigo-600 rounded-xl shadow-lg uppercase tracking-widest">Lưu lại</button>
              <button type="button" onClick={() => setShowNodeModal(false)} className="w-full text-[10px] font-bold text-gray-400 uppercase py-2">Đóng</button>
            </form>
          </div>
        </div>
      )}

      {showResourceModal && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-black/40 backdrop-blur-sm">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm p-8 animate-in zoom-in duration-200">
            <h3 className="font-black text-gray-800 uppercase text-sm mb-6">Thêm tài liệu</h3>
            <form onSubmit={saveResource} className="space-y-4">
              <input type="text" autoFocus value={resourceModalData.title} onChange={(e) => setResourceModalData({...resourceModalData, title: e.target.value})} placeholder="Tên tài liệu..." className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl font-bold" />
              <input type="text" value={resourceModalData.url} onChange={(e) => setResourceModalData({...resourceModalData, url: e.target.value})} placeholder="Link Drive/PDF..." className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl font-mono text-xs" />
              <button type="submit" className="w-full py-4 text-xs font-black text-white bg-blue-600 rounded-xl shadow-lg uppercase">Thêm ngay</button>
              <button type="button" onClick={() => setShowResourceModal(false)} className="w-full text-[10px] font-bold text-gray-400 uppercase py-2">Hủy</button>
            </form>
          </div>
        </div>
      )}

      {showDeleteConfirm && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-xs p-8 text-center animate-in zoom-in duration-200">
            <AlertTriangle size={32} className="text-red-500 mx-auto mb-4" />
            <p className="text-xs text-gray-500 mb-6 font-medium italic">Xóa mục: <br/><span className="font-black text-gray-800">"{showDeleteConfirm.title}"</span>?</p>
            <div className="flex gap-2">
              <button onClick={() => setShowDeleteConfirm(null)} className="flex-1 py-3 text-[10px] font-black text-gray-400 bg-gray-50 rounded-xl uppercase">Hủy</button>
              <button onClick={executeDelete} className="flex-1 py-3 text-[10px] font-black text-white bg-red-500 rounded-xl shadow-lg uppercase">Xóa</button>
            </div>
          </div>
        </div>
      )}

      {/* SIDEBAR */}
      <aside className={`w-72 border-r flex flex-col shrink-0 transition-all ${isAdmin ? 'bg-amber-50/20' : 'bg-white'}`}>
        <div className={`p-6 border-b flex justify-between items-center text-white ${isAdmin ? 'bg-amber-500 shadow-amber-100' : 'bg-indigo-600 shadow-indigo-100'} shadow-lg`}>
          <div className="flex items-center space-x-2">
            <Book size={20} />
            <h2 className="font-black text-lg uppercase tracking-tight">Danh mục</h2>
          </div>
          {isAdmin && (
            <button onClick={() => openAddNodeModal(null, 'folder')} className="p-1.5 bg-white/20 hover:bg-white/40 rounded-xl"><Plus size={18} /></button>
          )}
        </div>

        <div className="flex-1 overflow-y-auto p-4 custom-scrollbar">
          {data.nodes.filter(n => n.parentId === null).map(rootNode => (
            <TreeItem key={rootNode.id} node={rootNode} allNodes={data.nodes} selectedId={selectedId} isAdmin={isAdmin} onSelect={handleSelectNode} onAdd={openAddNodeModal} onEdit={openEditNodeModal} onDelete={(id) => setShowDeleteConfirm({ type: 'node', id, title: data.nodes.find(n => n.id === id)?.title || '' })} level={0} />
          ))}
        </div>

        <div className="p-4 border-t border-gray-100 bg-white/50 space-y-2">
          {/* Cloud Sync Status Indicator */}
          <div className="flex items-center justify-center space-x-2 py-1 px-3 bg-gray-50 rounded-lg">
            {isSyncing ? (
              <Loader2 size={12} className="animate-spin text-indigo-400" />
            ) : cloudStatus === 'connected' ? (
              <CloudCheck size={12} className="text-green-500" />
            ) : cloudStatus === 'error' ? (
              <CloudOff size={12} className="text-red-400" />
            ) : (
              <Cloud size={12} className="text-gray-300" />
            )}
            <span className="text-[8px] font-black uppercase tracking-widest text-gray-400">
              {isSyncing ? 'Đang đồng bộ...' : cloudStatus === 'connected' ? 'Cloud: Đã kết nối' : 'Cloud: Chưa cấu hình'}
            </span>
          </div>

          <button onClick={() => setRole('none')} className="w-full flex items-center justify-center space-x-2 px-4 py-3 rounded-xl text-[10px] font-black uppercase bg-gray-50 text-gray-400 hover:bg-red-50 hover:text-red-500 transition-all">
             <LogOut size={14} />
             <span>Thoát chế độ {isAdmin ? 'GV' : 'HS'}</span>
          </button>
        </div>
      </aside>

      {/* CONTENT AREA */}
      <main className="flex-1 flex flex-col min-w-0 relative bg-white">
        {selectedNode ? (
          <>
            <header className="px-8 py-4 border-b border-gray-50 flex justify-between items-center h-20 shrink-0 bg-white/80 backdrop-blur-md z-10">
                <div className="flex items-center space-x-4 min-w-0">
                    <div className={`p-2.5 rounded-xl shrink-0 ${selectedNode.type === 'folder' ? 'bg-amber-50 text-amber-500' : 'bg-indigo-50 text-indigo-500'}`}>
                        {selectedNode.type === 'folder' ? <Book size={18}/> : <Globe size={18}/>}
                    </div>
                    <div className="min-w-0">
                      <h1 className="text-lg font-black text-gray-800 truncate tracking-tight uppercase">{selectedNode.title}</h1>
                      <p className="text-[9px] text-gray-400 font-mono truncate">{selectedNode.url || 'Chưa gắn link nội dung'}</p>
                    </div>
                </div>
                <div className="flex space-x-2 shrink-0">
                    {isAdmin && <button onClick={() => openEditNodeModal(selectedNode)} className="p-2.5 text-amber-600 bg-amber-50 rounded-xl hover:bg-amber-100 transition-all"><Pencil size={18} /></button>}
                    {selectedNode.url && <a href={selectedNode.url} target="_blank" rel="noreferrer" className="p-2.5 text-gray-400 bg-gray-50 rounded-xl hover:bg-gray-100"><Maximize2 size={18} /></a>}
                </div>
            </header>

            <div className="flex-1 bg-gray-100 relative overflow-hidden">
              {iframeLoading && (
                <div className="absolute inset-0 z-10 flex flex-col items-center justify-center bg-white/70 backdrop-blur-sm">
                  <Loader2 size={32} className="animate-spin text-indigo-500 mb-3" />
                  <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Đang kết nối bài học...</p>
                </div>
              )}
              {selectedNode.url ? (
                <iframe src={selectedNode.url} className="w-full h-full border-none shadow-inner bg-white" onLoad={() => setIframeLoading(false)} title={selectedNode.title} allowFullScreen />
              ) : (
                <div className="absolute inset-0 flex flex-col items-center justify-center text-gray-300 p-10 text-center">
                    <Globe size={60} className="mb-4 opacity-5" />
                    <p className="text-sm font-bold opacity-30 italic">Nội dung bài học chưa được chuẩn bị</p>
                    {isAdmin && <button onClick={() => openEditNodeModal(selectedNode)} className="mt-4 px-6 py-3 bg-amber-500 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg">Gắn link bài học ngay</button>}
                </div>
              )}
            </div>
          </>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center bg-gray-50/50">
            <div className="p-12 bg-white rounded-full shadow-2xl shadow-gray-200 border-8 border-gray-50">
              <Book size={80} className="text-indigo-100" />
            </div>
            <h2 className="mt-8 text-xl font-black uppercase tracking-tighter text-gray-300">Chọn bài học để bắt đầu</h2>
          </div>
        )}
      </main>

      {/* RESOURCES */}
      <aside className="w-60 border-l border-gray-50 bg-gray-50/30 flex flex-col shrink-0">
        <div className="h-1/2 flex flex-col border-b border-gray-100 overflow-hidden">
          <div className="p-4 border-b border-gray-100 bg-white flex justify-between items-center sticky top-0 z-10">
            <h3 className="font-black text-[9px] text-gray-400 uppercase tracking-widest flex items-center"><LinkIcon size={12} className="mr-2 text-indigo-400" /> Tài liệu riêng</h3>
            {isAdmin && selectedNode && <button onClick={() => openResourceModal(false)} className="text-indigo-600 p-1.5 bg-indigo-50 rounded-lg"><Plus size={14} /></button>}
          </div>
          <div className="flex-1 overflow-y-auto p-3 space-y-2 custom-scrollbar">
            {selectedNode?.lessonResources.map(res => (
                <div key={res.id} className="group bg-white p-3 rounded-xl border border-gray-100 shadow-sm flex justify-between items-center hover:border-indigo-200 hover:shadow-md transition-all">
                  <a href={res.url} target="_blank" rel="noreferrer" className="text-[10px] text-indigo-600 font-bold truncate mr-2">{res.title}</a>
                  {isAdmin && <button onClick={() => setShowDeleteConfirm({ type: 'resource', id: res.id, isGlobal: false, title: res.title })} className="text-red-300 hover:text-red-500 opacity-0 group-hover:opacity-100"><Trash2 size={12} /></button>}
                </div>
            ))}
          </div>
        </div>

        <div className="h-1/2 flex flex-col bg-white overflow-hidden">
          <div className="p-4 border-b border-gray-100 bg-gray-50/50 flex justify-between items-center sticky top-0 z-10">
            <h3 className="font-black text-[9px] text-indigo-900 uppercase tracking-widest flex items-center"><Settings size={12} className="mr-2" /> Tài liệu chung</h3>
            {isAdmin && <button onClick={() => openResourceModal(true)} className="text-indigo-600 p-1.5 bg-white rounded-lg shadow-sm"><Plus size={14} /></button>}
          </div>
          <div className="flex-1 overflow-y-auto p-3 space-y-2 custom-scrollbar">
            {data.globalResources.map(res => (
                <div key={res.id} className="group bg-gray-50/80 p-3 rounded-xl border border-gray-100 flex justify-between items-center hover:bg-white transition-all">
                  <a href={res.url} target="_blank" rel="noreferrer" className="text-[10px] text-gray-700 font-bold truncate mr-2">{res.title}</a>
                  {isAdmin && <button onClick={() => setShowDeleteConfirm({ type: 'resource', id: res.id, isGlobal: true, title: res.title })} className="text-red-300 hover:text-red-500 opacity-0 group-hover:opacity-100"><Trash2 size={12} /></button>}
                </div>
            ))}
          </div>
        </div>
      </aside>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 3px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; }
        @keyframes shake { 0%, 100% { transform: translateX(0); } 25% { transform: translateX(-4px); } 75% { transform: translateX(4px); } }
        .animate-shake { animation: shake 0.2s ease-in-out 0s 2; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback } from 'react';
import { 
  Book, Link as LinkIcon, X, Pencil, Plus, Settings, Globe, Maximize2, Save, 
  Loader2, LogOut, GraduationCap, KeyRound, Trash2, AlertTriangle, Cloud, CloudCheck, CloudOff,
  ShieldCheck
} from 'lucide-react';
import { createClient } from '@supabase/supabase-js';
import { BookNode, NodeType, AppData, ResourceLink } from './types';
import { INITIAL_DATA } from './constants';
import TreeItem from './components/TreeItem';

// ==========================================
// CẤU HÌNH SUPABASE CỦA BẠN TẠI ĐÂY
// ==========================================
const SUPABASE_URL = 'URL_CỦA_BẠN'; // Thay bằng URL dự án Supabase
const SUPABASE_ANON_KEY = 'KEY_CỦA_BẠN'; // Thay bằng Anon Key
// ==========================================

const supabase = (SUPABASE_URL !== 'URL_CỦA_BẠN') 
  ? createClient(SUPABASE_URL, SUPABASE_ANON_KEY) 
  : null;

const App: React.FC = () => {
  const [data, setData] = useState<AppData>(INITIAL_DATA);
  const [role, setRole] = useState<'none' | 'teacher' | 'student'>('none');
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [iframeLoading, setIframeLoading] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [cloudStatus, setCloudStatus] = useState<'connected' | 'error' | 'local'>('local');

  // Modal States
  const [showPassInput, setShowPassInput] = useState(false);
  const [teacherPass, setTeacherPass] = useState('');
  const [passError, setPassError] = useState(false);
  const [showNodeModal, setShowNodeModal] = useState(false);
  const [nodeModalData, setNodeModalData] = useState<{ id?: string; parentId: string | null; type: NodeType; title: string; url: string; }>({ parentId: null, type: 'lesson', title: '', url: '' });
  const [showResourceModal, setShowResourceModal] = useState(false);
  const [resourceModalData, setResourceModalData] = useState({ isGlobal: false, title: '', url: '' });
  const [showDeleteConfirm, setShowDeleteConfirm] = useState<{ type: 'node' | 'resource'; id: string; isGlobal?: boolean; title: string; } | null>(null);

  // 1. TẢI DỮ LIỆU TỪ CLOUD (SUPABASE)
  const fetchCloudData = useCallback(async () => {
    if (!supabase) return;
    setIsSyncing(true);
    try {
      const { data: cloudRows, error } = await supabase
        .from('app_settings') // Tên bảng bạn tạo trên Supabase
        .select('data')
        .eq('id', 1) // Giả định dùng row id=1 để lưu cấu hình
        .single();

      if (error) throw error;
      if (cloudRows?.data) {
        setData(cloudRows.data);
        setCloudStatus('connected');
      }
    } catch (err) {
      console.error('Fetch error:', err);
      setCloudStatus('error');
      // Fallback sang LocalStorage nếu Cloud lỗi
      const saved = localStorage.getItem('teacher_app_data_v7');
      if (saved) setData(JSON.parse(saved));
    } finally {
      setIsSyncing(false);
    }
  }, []);

  // 2. LƯU DỮ LIỆU LÊN CLOUD
  const saveToCloud = async (newData: AppData) => {
    localStorage.setItem('teacher_app_data_v7', JSON.stringify(newData));
    if (!supabase || role !== 'teacher') return;

    setIsSyncing(true);
    try {
      const { error } = await supabase
        .from('app_settings')
        .upsert({ id: 1, data: newData }); // Cập nhật đè lên row id=1

      if (error) throw error;
      setCloudStatus('connected');
    } catch (err) {
      console.error('Save error:', err);
      setCloudStatus('error');
    } finally {
      setIsSyncing(false);
    }
  };

  useEffect(() => {
    fetchCloudData();
  }, [fetchCloudData]);

  const selectedNode = data.nodes.find(n => n.id === selectedId);

  const handleSelectNode = (id: string) => {
    setSelectedId(id);
    const node = data.nodes.find(n => n.id === id);
    if (node && node.url) setIframeLoading(true);
  };

  const updateData = (newData: AppData) => {
    setData(newData);
    saveToCloud(newData);
  };

  // QUẢN LÝ MENU
  const saveNode = (e: React.FormEvent) => {
    e.preventDefault();
    if (!nodeModalData.title.trim()) return;

    let nextNodes = [...data.nodes];
    if (nodeModalData.id) {
      nextNodes = nextNodes.map(n => n.id === nodeModalData.id ? { ...n, title: nodeModalData.title, url: nodeModalData.url } : n);
    } else {
      const newNode: BookNode = {
        id: `node-${Date.now()}`,
        title: nodeModalData.title,
        type: nodeModalData.type,
        url: nodeModalData.url,
        parentId: nodeModalData.parentId,
        lessonResources: []
      };
      nextNodes.push(newNode);
      setSelectedId(newNode.id);
    }
    updateData({ ...data, nodes: nextNodes });
    setShowNodeModal(false);
  };

  // QUẢN LÝ TÀI LIỆU
  const saveResource = (e: React.FormEvent) => {
    e.preventDefault();
    const { title, url, isGlobal } = resourceModalData;
    if (!title.trim() || !url.trim()) return;
    const newRes: ResourceLink = { id: `res-${Date.now()}`, title, url };

    if (isGlobal) {
      updateData({ ...data, globalResources: [...data.globalResources, newRes] });
    } else if (selectedId) {
      const nextNodes = data.nodes.map(n => n.id === selectedId ? { ...n, lessonResources: [...n.lessonResources, newRes] } : n);
      updateData({ ...data, nodes: nextNodes });
    }
    setShowResourceModal(false);
  };

  const executeDelete = () => {
    if (!showDeleteConfirm) return;
    const { type, id, isGlobal } = showDeleteConfirm;
    let nextData = { ...data };

    if (type === 'node') {
      const idsToDelete = new Set<string>();
      const collectIds = (targetId: string) => {
        idsToDelete.add(targetId);
        data.nodes.filter(n => n.parentId === targetId).forEach(child => collectIds(child.id));
      };
      collectIds(id);
      nextData.nodes = data.nodes.filter(n => !idsToDelete.has(n.id));
      if (selectedId && idsToDelete.has(selectedId)) setSelectedId(null);
    } else {
      if (isGlobal) {
        nextData.globalResources = data.globalResources.filter(r => r.id !== id);
      } else {
        nextData.nodes = data.nodes.map(n => n.id === selectedId ? { ...n, lessonResources: n.lessonResources.filter(r => r.id !== id) } : n);
      }
    }
    updateData(nextData);
    setShowDeleteConfirm(null);
  };

  const handleVerifyTeacher = (e: React.FormEvent) => {
    e.preventDefault();
    if (teacherPass === '1234') {
      setRole('teacher');
      setShowPassInput(false);
      setTeacherPass('');
    } else setPassError(true);
  };

  // Helper functions for opening modals
  const openAddNodeModal = (parentId: string | null, type: NodeType) => {
    setNodeModalData({ parentId, type, title: '', url: '' });
    setShowNodeModal(true);
  };

  const openEditNodeModal = (node: BookNode) => {
    setNodeModalData({ id: node.id, parentId: node.parentId, type: node.type, title: node.title, url: node.url });
    setShowNodeModal(true);
  };

  const openResourceModal = (isGlobal: boolean) => {
    setResourceModalData({ isGlobal, title: '', url: '' });
    setShowResourceModal(true);
  };

  if (role === 'none') {
    return (
      <div className="h-screen w-full flex items-center justify-center bg-gray-50 p-6 overflow-hidden">
        <div className="max-w-4xl w-full grid grid-cols-1 md:grid-cols-2 gap-8">
          <button onClick={() => setRole('student')} className="group bg-white p-10 rounded-[40px] shadow-xl hover:shadow-2xl transition-all border-4 border-transparent hover:border-indigo-500 flex flex-col items-center text-center space-y-6">
            <div className="w-20 h-20 bg-indigo-100 text-indigo-600 rounded-3xl flex items-center justify-center group-hover:rotate-6 transition-transform">
              <GraduationCap size={40} />
            </div>
            <div>
              <h2 className="text-2xl font-black text-gray-800 uppercase tracking-tight">Học sinh</h2>
              <p className="text-gray-500 mt-2 text-sm">Xem bài giảng Realtime từ Cloud.</p>
            </div>
            <div className="px-8 py-3 bg-indigo-600 text-white rounded-2xl font-black text-xs tracking-widest uppercase">Vào lớp ngay</div>
          </button>

          <div className="relative group">
            {!showPassInput ? (
              <button onClick={() => setShowPassInput(true)} className="w-full h-full bg-white p-10 rounded-[40px] shadow-xl hover:shadow-2xl transition-all border-4 border-transparent hover:border-amber-500 flex flex-col items-center text-center space-y-6">
                <div className="w-20 h-20 bg-amber-100 text-amber-600 rounded-3xl flex items-center justify-center group-hover:-rotate-6 transition-transform">
                  <ShieldCheck size={40} />
                </div>
                <h2 className="text-2xl font-black text-gray-800 uppercase tracking-tight">Giáo viên</h2>
                <div className="px-8 py-3 bg-amber-500 text-white rounded-2xl font-black text-xs tracking-widest uppercase">Soạn bài giảng</div>
              </button>
            ) : (
              <div className="bg-white p-10 rounded-[40px] shadow-2xl border-4 border-amber-500 flex flex-col items-center text-center space-y-4 animate-in zoom-in duration-200 h-full justify-center">
                <KeyRound size={28} className="text-amber-500" />
                <form onSubmit={handleVerifyTeacher} className="w-full space-y-3">
                  <input type="password" autoFocus value={teacherPass} onChange={(e) => { setTeacherPass(e.target.value); setPassError(false); }} placeholder="Mật khẩu (1234)" className={`w-full px-4 py-3 bg-gray-50 border-2 rounded-xl text-center focus:outline-none ${passError ? 'border-red-400 animate-shake' : 'border-gray-100 focus:border-amber-400'}`} />
                  <div className="flex gap-2">
                    <button type="button" onClick={() => setShowPassInput(false)} className="flex-1 py-3 text-[10px] font-black text-gray-400 uppercase">Hủy</button>
                    <button type="submit" className="flex-2 py-3 px-6 text-[10px] font-black text-white bg-amber-500 rounded-xl shadow-lg uppercase">Xác nhận</button>
                  </div>
                </form>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  const isAdmin = role === 'teacher';

  return (
    <div className="flex h-screen bg-white overflow-hidden font-sans relative">

      {/* MODALS */}
      {showNodeModal && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-black/40 backdrop-blur-sm">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm p-8 animate-in zoom-in duration-200">
            <h3 className="font-black text-gray-800 uppercase text-sm mb-6">{nodeModalData.id ? 'Cập nhật mục' : 'Thêm mục mới'}</h3>
            <form onSubmit={saveNode} className="space-y-4">
              <input type="text" autoFocus value={nodeModalData.title} onChange={(e) => setNodeModalData({...nodeModalData, title: e.target.value})} placeholder="Tên mục..." className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl font-bold" />
              <input type="text" value={nodeModalData.url} onChange={(e) => setNodeModalData({...nodeModalData, url: e.target.value})} placeholder="Link URL..." className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl font-mono text-xs" />
              <button type="submit" className="w-full py-4 text-xs font-black text-white bg-indigo-600 rounded-xl shadow-lg uppercase tracking-widest">Lưu lại</button>
              <button type="button" onClick={() => setShowNodeModal(false)} className="w-full text-[10px] font-bold text-gray-400 uppercase py-2">Đóng</button>
            </form>
          </div>
        </div>
      )}

      {showResourceModal && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-black/40 backdrop-blur-sm">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm p-8 animate-in zoom-in duration-200">
            <h3 className="font-black text-gray-800 uppercase text-sm mb-6">Thêm tài liệu</h3>
            <form onSubmit={saveResource} className="space-y-4">
              <input type="text" autoFocus value={resourceModalData.title} onChange={(e) => setResourceModalData({...resourceModalData, title: e.target.value})} placeholder="Tên tài liệu..." className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl font-bold" />
              <input type="text" value={resourceModalData.url} onChange={(e) => setResourceModalData({...resourceModalData, url: e.target.value})} placeholder="Link Drive/PDF..." className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl font-mono text-xs" />
              <button type="submit" className="w-full py-4 text-xs font-black text-white bg-blue-600 rounded-xl shadow-lg uppercase">Thêm ngay</button>
              <button type="button" onClick={() => setShowResourceModal(false)} className="w-full text-[10px] font-bold text-gray-400 uppercase py-2">Hủy</button>
            </form>
          </div>
        </div>
      )}

      {showDeleteConfirm && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-xs p-8 text-center animate-in zoom-in duration-200">
            <AlertTriangle size={32} className="text-red-500 mx-auto mb-4" />
            <p className="text-xs text-gray-500 mb-6 font-medium italic">Xóa mục: <br/><span className="font-black text-gray-800">"{showDeleteConfirm.title}"</span>?</p>
            <div className="flex gap-2">
              <button onClick={() => setShowDeleteConfirm(null)} className="flex-1 py-3 text-[10px] font-black text-gray-400 bg-gray-50 rounded-xl uppercase">Hủy</button>
              <button onClick={executeDelete} className="flex-1 py-3 text-[10px] font-black text-white bg-red-500 rounded-xl shadow-lg uppercase">Xóa</button>
            </div>
          </div>
        </div>
      )}

      {/* SIDEBAR */}
      <aside className={`w-72 border-r flex flex-col shrink-0 transition-all ${isAdmin ? 'bg-amber-50/20' : 'bg-white'}`}>
        <div className={`p-6 border-b flex justify-between items-center text-white ${isAdmin ? 'bg-amber-500 shadow-amber-100' : 'bg-indigo-600 shadow-indigo-100'} shadow-lg`}>
          <div className="flex items-center space-x-2">
            <Book size={20} />
            <h2 className="font-black text-lg uppercase tracking-tight">Danh mục</h2>
          </div>
          {isAdmin && (
            <button onClick={() => openAddNodeModal(null, 'folder')} className="p-1.5 bg-white/20 hover:bg-white/40 rounded-xl"><Plus size={18} /></button>
          )}
        </div>

        <div className="flex-1 overflow-y-auto p-4 custom-scrollbar">
          {data.nodes.filter(n => n.parentId === null).map(rootNode => (
            <TreeItem key={rootNode.id} node={rootNode} allNodes={data.nodes} selectedId={selectedId} isAdmin={isAdmin} onSelect={handleSelectNode} onAdd={openAddNodeModal} onEdit={openEditNodeModal} onDelete={(id) => setShowDeleteConfirm({ type: 'node', id, title: data.nodes.find(n => n.id === id)?.title || '' })} level={0} />
          ))}
        </div>

        <div className="p-4 border-t border-gray-100 bg-white/50 space-y-2">
          {/* Cloud Sync Status Indicator */}
          <div className="flex items-center justify-center space-x-2 py-1 px-3 bg-gray-50 rounded-lg">
            {isSyncing ? (
              <Loader2 size={12} className="animate-spin text-indigo-400" />
            ) : cloudStatus === 'connected' ? (
              <CloudCheck size={12} className="text-green-500" />
            ) : cloudStatus === 'error' ? (
              <CloudOff size={12} className="text-red-400" />
            ) : (
              <Cloud size={12} className="text-gray-300" />
            )}
            <span className="text-[8px] font-black uppercase tracking-widest text-gray-400">
              {isSyncing ? 'Đang đồng bộ...' : cloudStatus === 'connected' ? 'Cloud: Đã kết nối' : 'Cloud: Chưa cấu hình'}
            </span>
          </div>

          <button onClick={() => setRole('none')} className="w-full flex items-center justify-center space-x-2 px-4 py-3 rounded-xl text-[10px] font-black uppercase bg-gray-50 text-gray-400 hover:bg-red-50 hover:text-red-500 transition-all">
             <LogOut size={14} />
             <span>Thoát chế độ {isAdmin ? 'GV' : 'HS'}</span>
          </button>
        </div>
      </aside>

      {/* CONTENT AREA */}
      <main className="flex-1 flex flex-col min-w-0 relative bg-white">
        {selectedNode ? (
          <>
            <header className="px-8 py-4 border-b border-gray-50 flex justify-between items-center h-20 shrink-0 bg-white/80 backdrop-blur-md z-10">
                <div className="flex items-center space-x-4 min-w-0">
                    <div className={`p-2.5 rounded-xl shrink-0 ${selectedNode.type === 'folder' ? 'bg-amber-50 text-amber-500' : 'bg-indigo-50 text-indigo-500'}`}>
                        {selectedNode.type === 'folder' ? <Book size={18}/> : <Globe size={18}/>}
                    </div>
                    <div className="min-w-0">
                      <h1 className="text-lg font-black text-gray-800 truncate tracking-tight uppercase">{selectedNode.title}</h1>
                      <p className="text-[9px] text-gray-400 font-mono truncate">{selectedNode.url || 'Chưa gắn link nội dung'}</p>
                    </div>
                </div>
                <div className="flex space-x-2 shrink-0">
                    {isAdmin && <button onClick={() => openEditNodeModal(selectedNode)} className="p-2.5 text-amber-600 bg-amber-50 rounded-xl hover:bg-amber-100 transition-all"><Pencil size={18} /></button>}
                    {selectedNode.url && <a href={selectedNode.url} target="_blank" rel="noreferrer" className="p-2.5 text-gray-400 bg-gray-50 rounded-xl hover:bg-gray-100"><Maximize2 size={18} /></a>}
                </div>
            </header>

            <div className="flex-1 bg-gray-100 relative overflow-hidden">
              {iframeLoading && (
                <div className="absolute inset-0 z-10 flex flex-col items-center justify-center bg-white/70 backdrop-blur-sm">
                  <Loader2 size={32} className="animate-spin text-indigo-500 mb-3" />
                  <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Đang kết nối bài học...</p>
                </div>
              )}
              {selectedNode.url ? (
                <iframe src={selectedNode.url} className="w-full h-full border-none shadow-inner bg-white" onLoad={() => setIframeLoading(false)} title={selectedNode.title} allowFullScreen />
              ) : (
                <div className="absolute inset-0 flex flex-col items-center justify-center text-gray-300 p-10 text-center">
                    <Globe size={60} className="mb-4 opacity-5" />
                    <p className="text-sm font-bold opacity-30 italic">Nội dung bài học chưa được chuẩn bị</p>
                    {isAdmin && <button onClick={() => openEditNodeModal(selectedNode)} className="mt-4 px-6 py-3 bg-amber-500 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg">Gắn link bài học ngay</button>}
                </div>
              )}
            </div>
          </>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center bg-gray-50/50">
            <div className="p-12 bg-white rounded-full shadow-2xl shadow-gray-200 border-8 border-gray-50">
              <Book size={80} className="text-indigo-100" />
            </div>
            <h2 className="mt-8 text-xl font-black uppercase tracking-tighter text-gray-300">Chọn bài học để bắt đầu</h2>
          </div>
        )}
      </main>

      {/* RESOURCES */}
      <aside className="w-60 border-l border-gray-50 bg-gray-50/30 flex flex-col shrink-0">
        <div className="h-1/2 flex flex-col border-b border-gray-100 overflow-hidden">
          <div className="p-4 border-b border-gray-100 bg-white flex justify-between items-center sticky top-0 z-10">
            <h3 className="font-black text-[9px] text-gray-400 uppercase tracking-widest flex items-center"><LinkIcon size={12} className="mr-2 text-indigo-400" /> Tài liệu riêng</h3>
            {isAdmin && selectedNode && <button onClick={() => openResourceModal(false)} className="text-indigo-600 p-1.5 bg-indigo-50 rounded-lg"><Plus size={14} /></button>}
          </div>
          <div className="flex-1 overflow-y-auto p-3 space-y-2 custom-scrollbar">
            {selectedNode?.lessonResources.map(res => (
                <div key={res.id} className="group bg-white p-3 rounded-xl border border-gray-100 shadow-sm flex justify-between items-center hover:border-indigo-200 hover:shadow-md transition-all">
                  <a href={res.url} target="_blank" rel="noreferrer" className="text-[10px] text-indigo-600 font-bold truncate mr-2">{res.title}</a>
                  {isAdmin && <button onClick={() => setShowDeleteConfirm({ type: 'resource', id: res.id, isGlobal: false, title: res.title })} className="text-red-300 hover:text-red-500 opacity-0 group-hover:opacity-100"><Trash2 size={12} /></button>}
                </div>
            ))}
          </div>
        </div>

        <div className="h-1/2 flex flex-col bg-white overflow-hidden">
          <div className="p-4 border-b border-gray-100 bg-gray-50/50 flex justify-between items-center sticky top-0 z-10">
            <h3 className="font-black text-[9px] text-indigo-900 uppercase tracking-widest flex items-center"><Settings size={12} className="mr-2" /> Tài liệu chung</h3>
            {isAdmin && <button onClick={() => openResourceModal(true)} className="text-indigo-600 p-1.5 bg-white rounded-lg shadow-sm"><Plus size={14} /></button>}
          </div>
          <div className="flex-1 overflow-y-auto p-3 space-y-2 custom-scrollbar">
            {data.globalResources.map(res => (
                <div key={res.id} className="group bg-gray-50/80 p-3 rounded-xl border border-gray-100 flex justify-between items-center hover:bg-white transition-all">
                  <a href={res.url} target="_blank" rel="noreferrer" className="text-[10px] text-gray-700 font-bold truncate mr-2">{res.title}</a>
                  {isAdmin && <button onClick={() => setShowDeleteConfirm({ type: 'resource', id: res.id, isGlobal: true, title: res.title })} className="text-red-300 hover:text-red-500 opacity-0 group-hover:opacity-100"><Trash2 size={12} /></button>}
                </div>
            ))}
          </div>
        </div>
      </aside>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 3px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; }
        @keyframes shake { 0%, 100% { transform: translateX(0); } 25% { transform: translateX(-4px); } 75% { transform: translateX(4px); } }
        .animate-shake { animation: shake 0.2s ease-in-out 0s 2; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback } from 'react';
import { 
  Book, Link as LinkIcon, X, Pencil, Plus, Settings, Globe, Maximize2, Save, 
  Loader2, LogOut, GraduationCap, KeyRound, Trash2, AlertTriangle, Cloud, CloudCheck, CloudOff,
  ShieldCheck
} from 'lucide-react';
import { createClient } from '@supabase/supabase-js';
import { BookNode, NodeType, AppData, ResourceLink } from './types';
import { INITIAL_DATA } from './constants';
import TreeItem from './components/TreeItem';

// =========================================================================
// 1. DÁN THÔNG TIN SUPABASE CỦA BẠN VÀO ĐÂY:
// =========================================================================
const SUPABASE_URL = 'URL_CỦA_BẠN_Ở_ĐÂY'; // Ví dụ: https://xyz.supabase.co
const SUPABASE_ANON_KEY = 'KEY_CỦA_BẠN_Ở_ĐÂY'; // Chuỗi ký tự dài ngoằng
// =========================================================================

const supabase = (SUPABASE_URL !== 'URL_CỦA_BẠN_Ở_ĐÂY') 
  ? createClient(SUPABASE_URL, SUPABASE_ANON_KEY) 
  : null;

const App: React.FC = () => {
  const [data, setData] = useState<AppData>(INITIAL_DATA);
  const [role, setRole] = useState<'none' | 'teacher' | 'student'>('none');
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [iframeLoading, setIframeLoading] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [cloudStatus, setCloudStatus] = useState<'connected' | 'error' | 'local'>('local');

  // Modal States
  const [showPassInput, setShowPassInput] = useState(false);
  const [teacherPass, setTeacherPass] = useState('');
  const [passError, setPassError] = useState(false);
  const [showNodeModal, setShowNodeModal] = useState(false);
  const [nodeModalData, setNodeModalData] = useState<{ id?: string; parentId: string | null; type: NodeType; title: string; url: string; }>({ parentId: null, type: 'lesson', title: '', url: '' });
  const [showResourceModal, setShowResourceModal] = useState(false);
  const [resourceModalData, setResourceModalData] = useState({ isGlobal: false, title: '', url: '' });
  const [showDeleteConfirm, setShowDeleteConfirm] = useState<{ type: 'node' | 'resource'; id: string; isGlobal?: boolean; title: string; } | null>(null);

  // Tải dữ liệu từ Cloud
  const fetchCloudData = useCallback(async () => {
    if (!supabase) return;
    setIsSyncing(true);
    try {
      const { data: cloudRows, error } = await supabase
        .from('app_settings') 
        .select('data')
        .eq('id', 1) 
        .single();

      if (error) throw error;
      if (cloudRows?.data) {
        setData(cloudRows.data);
        setCloudStatus('connected');
      }
    } catch (err) {
      console.error('Fetch error:', err);
      setCloudStatus('error');
      const saved = localStorage.getItem('teacher_app_data_v7');
      if (saved) setData(JSON.parse(saved));
    } finally {
      setIsSyncing(false);
    }
  }, []);

  // Lưu dữ liệu lên Cloud
  const saveToCloud = async (newData: AppData) => {
    localStorage.setItem('teacher_app_data_v7', JSON.stringify(newData));
    if (!supabase || role !== 'teacher') return;

    setIsSyncing(true);
    try {
      const { error } = await supabase
        .from('app_settings')
        .upsert({ id: 1, data: newData });

      if (error) throw error;
      setCloudStatus('connected');
    } catch (err) {
      console.error('Save error:', err);
      setCloudStatus('error');
    } finally {
      setIsSyncing(false);
    }
  };

  useEffect(() => {
    fetchCloudData();
  }, [fetchCloudData]);

  const updateData = (newData: AppData) => {
    setData(newData);
    saveToCloud(newData);
  };

  const handleSelectNode = (id: string) => {
    setSelectedId(id);
    const node = data.nodes.find(n => n.id === id);
    if (node && node.url) setIframeLoading(true);
  };

  const saveNode = (e: React.FormEvent) => {
    e.preventDefault();
    if (!nodeModalData.title.trim()) return;
    let nextNodes = [...data.nodes];
    if (nodeModalData.id) {
      nextNodes = nextNodes.map(n => n.id === nodeModalData.id ? { ...n, title: nodeModalData.title, url: nodeModalData.url } : n);
    } else {
      const newNode: BookNode = {
        id: `node-${Date.now()}`,
        title: nodeModalData.title,
        type: nodeModalData.type,
        url: nodeModalData.url,
        parentId: nodeModalData.parentId,
        lessonResources: []
      };
      nextNodes.push(newNode);
      setSelectedId(newNode.id);
    }
    updateData({ ...data, nodes: nextNodes });
    setShowNodeModal(false);
  };

  const saveResource = (e: React.FormEvent) => {
    e.preventDefault();
    const { title, url, isGlobal } = resourceModalData;
    if (!title.trim() || !url.trim()) return;
    const newRes: ResourceLink = { id: `res-${Date.now()}`, title, url };
    if (isGlobal) {
      updateData({ ...data, globalResources: [...data.globalResources, newRes] });
    } else if (selectedId) {
      const nextNodes = data.nodes.map(n => n.id === selectedId ? { ...n, lessonResources: [...n.lessonResources, newRes] } : n);
      updateData({ ...data, nodes: nextNodes });
    }
    setShowResourceModal(false);
  };

  const executeDelete = () => {
    if (!showDeleteConfirm) return;
    const { type, id, isGlobal } = showDeleteConfirm;
    let nextData = { ...data };
    if (type === 'node') {
      const idsToDelete = new Set<string>();
      const collectIds = (targetId: string) => {
        idsToDelete.add(targetId);
        data.nodes.filter(n => n.parentId === targetId).forEach(child => collectIds(child.id));
      };
      collectIds(id);
      nextData.nodes = data.nodes.filter(n => !idsToDelete.has(n.id));
      if (selectedId && idsToDelete.has(selectedId)) setSelectedId(null);
    } else {
      if (isGlobal) {
        nextData.globalResources = data.globalResources.filter(r => r.id !== id);
      } else {
        nextData.nodes = data.nodes.map(n => n.id === selectedId ? { ...n, lessonResources: n.lessonResources.filter(r => r.id !== id) } : n);
      }
    }
    updateData(nextData);
    setShowDeleteConfirm(null);
  };

  const openAddNodeModal = (parentId: string | null, type: NodeType) => {
    setNodeModalData({ parentId, type, title: '', url: '' });
    setShowNodeModal(true);
  };

  const openEditNodeModal = (node: BookNode) => {
    setNodeModalData({ id: node.id, parentId: node.parentId, type: node.type, title: node.title, url: node.url });
    setShowNodeModal(true);
  };

  const openResourceModal = (isGlobal: boolean) => {
    setResourceModalData({ isGlobal, title: '', url: '' });
    setShowResourceModal(true);
  };

  if (role === 'none') {
    return (
      <div className="h-screen w-full flex items-center justify-center bg-gray-50 p-6 overflow-hidden">
        <div className="max-w-4xl w-full grid grid-cols-1 md:grid-cols-2 gap-8">
          <button onClick={() => setRole('student')} className="group bg-white p-10 rounded-[40px] shadow-xl hover:shadow-2xl transition-all border-4 border-transparent hover:border-indigo-500 flex flex-col items-center text-center space-y-6">
            <div className="w-20 h-20 bg-indigo-100 text-indigo-600 rounded-3xl flex items-center justify-center group-hover:rotate-6 transition-transform">
              <GraduationCap size={40} />
            </div>
            <div>
              <h2 className="text-2xl font-black text-gray-800 uppercase tracking-tight">Học sinh</h2>
              <p className="text-gray-500 mt-2 text-sm">Xem bài giảng Realtime từ Cloud.</p>
            </div>
            <div className="px-8 py-3 bg-indigo-600 text-white rounded-2xl font-black text-xs tracking-widest uppercase">Vào lớp ngay</div>
          </button>
          <div className="relative group">
            {!showPassInput ? (
              <button onClick={() => setShowPassInput(true)} className="w-full h-full bg-white p-10 rounded-[40px] shadow-xl hover:shadow-2xl transition-all border-4 border-transparent hover:border-amber-500 flex flex-col items-center text-center space-y-6">
                <div className="w-20 h-20 bg-amber-100 text-amber-600 rounded-3xl flex items-center justify-center group-hover:-rotate-6 transition-transform">
                  <ShieldCheck size={40} />
                </div>
                <h2 className="text-2xl font-black text-gray-800 uppercase tracking-tight">Giáo viên</h2>
                <div className="px-8 py-3 bg-amber-500 text-white rounded-2xl font-black text-xs tracking-widest uppercase">Soạn bài giảng</div>
              </button>
            ) : (
              <div className="bg-white p-10 rounded-[40px] shadow-2xl border-4 border-amber-500 flex flex-col items-center text-center space-y-4 animate-in zoom-in duration-200 h-full justify-center">
                <KeyRound size={28} className="text-amber-500" />
                <form onSubmit={(e) => { e.preventDefault(); if (teacherPass === '1234') { setRole('teacher'); setShowPassInput(false); } else setPassError(true); }} className="w-full space-y-3">
                  <input type="password" autoFocus value={teacherPass} onChange={(e) => { setTeacherPass(e.target.value); setPassError(false); }} placeholder="Mật khẩu (1234)" className={`w-full px-4 py-3 bg-gray-50 border-2 rounded-xl text-center focus:outline-none ${passError ? 'border-red-400 animate-shake' : 'border-gray-100 focus:border-amber-400'}`} />
                  <div className="flex gap-2">
                    <button type="button" onClick={() => setShowPassInput(false)} className="flex-1 py-3 text-[10px] font-black text-gray-400 uppercase">Hủy</button>
                    <button type="submit" className="flex-2 py-3 px-6 text-[10px] font-black text-white bg-amber-500 rounded-xl shadow-lg uppercase">Xác nhận</button>
                  </div>
                </form>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  const isAdmin = role === 'teacher';
  const selectedNode = data.nodes.find(n => n.id === selectedId);

  return (
    <div className="flex h-screen bg-white overflow-hidden font-sans relative">
      {showNodeModal && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-black/40 backdrop-blur-sm">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm p-8 animate-in zoom-in duration-200">
            <h3 className="font-black text-gray-800 uppercase text-sm mb-6">{nodeModalData.id ? 'Cập nhật mục' : 'Thêm mục mới'}</h3>
            <form onSubmit={saveNode} className="space-y-4">
              <input type="text" autoFocus value={nodeModalData.title} onChange={(e) => setNodeModalData({...nodeModalData, title: e.target.value})} placeholder="Tên mục..." className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl font-bold" />
              <input type="text" value={nodeModalData.url} onChange={(e) => setNodeModalData({...nodeModalData, url: e.target.value})} placeholder="Link URL..." className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl font-mono text-xs" />
              <button type="submit" className="w-full py-4 text-xs font-black text-white bg-indigo-600 rounded-xl shadow-lg uppercase tracking-widest">Lưu lại</button>
              <button type="button" onClick={() => setShowNodeModal(false)} className="w-full text-[10px] font-bold text-gray-400 uppercase py-2">Đóng</button>
            </form>
          </div>
        </div>
      )}
      {showResourceModal && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-black/40 backdrop-blur-sm">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm p-8 animate-in zoom-in duration-200">
            <h3 className="font-black text-gray-800 uppercase text-sm mb-6">Thêm tài liệu</h3>
            <form onSubmit={saveResource} className="space-y-4">
              <input type="text" autoFocus value={resourceModalData.title} onChange={(e) => setResourceModalData({...resourceModalData, title: e.target.value})} placeholder="Tên tài liệu..." className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl font-bold" />
              <input type="text" value={resourceModalData.url} onChange={(e) => setResourceModalData({...resourceModalData, url: e.target.value})} placeholder="Link Drive/PDF..." className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl font-mono text-xs" />
              <button type="submit" className="w-full py-4 text-xs font-black text-white bg-blue-600 rounded-xl shadow-lg uppercase">Thêm ngay</button>
              <button type="button" onClick={() => setShowResourceModal(false)} className="w-full text-[10px] font-bold text-gray-400 uppercase py-2">Hủy</button>
            </form>
          </div>
        </div>
      )}
      {showDeleteConfirm && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-xs p-8 text-center animate-in zoom-in duration-200">
            <AlertTriangle size={32} className="text-red-500 mx-auto mb-4" />
            <p className="text-xs text-gray-500 mb-6 font-medium italic">Xóa mục: <br/><span className="font-black text-gray-800">"{showDeleteConfirm.title}"</span>?</p>
            <div className="flex gap-2">
              <button onClick={() => setShowDeleteConfirm(null)} className="flex-1 py-3 text-[10px] font-black text-gray-400 bg-gray-50 rounded-xl uppercase">Hủy</button>
              <button onClick={executeDelete} className="flex-1 py-3 text-[10px] font-black text-white bg-red-500 rounded-xl shadow-lg uppercase">Xóa</button>
            </div>
          </div>
        </div>
      )}
      <aside className={`w-72 border-r flex flex-col shrink-0 transition-all ${isAdmin ? 'bg-amber-50/20' : 'bg-white'}`}>
        <div className={`p-6 border-b flex justify-between items-center text-white ${isAdmin ? 'bg-amber-500 shadow-amber-100' : 'bg-indigo-600 shadow-indigo-100'} shadow-lg`}>
          <div className="flex items-center space-x-2"><Book size={20} /><h2 className="font-black text-lg uppercase tracking-tight">Danh mục</h2></div>
          {isAdmin && <button onClick={() => openAddNodeModal(null, 'folder')} className="p-1.5 bg-white/20 hover:bg-white/40 rounded-xl"><Plus size={18} /></button>}
        </div>
        <div className="flex-1 overflow-y-auto p-4 custom-scrollbar">
          {data.nodes.filter(n => n.parentId === null).map(rootNode => (
            <TreeItem key={rootNode.id} node={rootNode} allNodes={data.nodes} selectedId={selectedId} isAdmin={isAdmin} onSelect={handleSelectNode} onAdd={openAddNodeModal} onEdit={openEditNodeModal} onDelete={(id) => setShowDeleteConfirm({ type: 'node', id, title: data.nodes.find(n => n.id === id)?.title || '' })} level={0} />
          ))}
        </div>
        <div className="p-4 border-t border-gray-100 bg-white/50 space-y-2">
          <div className="flex items-center justify-center space-x-2 py-1 px-3 bg-gray-50 rounded-lg">
            {isSyncing ? <Loader2 size={12} className="animate-spin text-indigo-400" /> : cloudStatus === 'connected' ? <CloudCheck size={12} className="text-green-500" /> : cloudStatus === 'error' ? <CloudOff size={12} className="text-red-400" /> : <Cloud size={12} className="text-gray-300" />}
            <span className="text-[8px] font-black uppercase tracking-widest text-gray-400">{isSyncing ? 'Đang đồng bộ...' : cloudStatus === 'connected' ? 'Cloud: Đã kết nối' : 'Cloud: Chưa cấu hình'}</span>
          </div>
          <button onClick={() => setRole('none')} className="w-full flex items-center justify-center space-x-2 px-4 py-3 rounded-xl text-[10px] font-black uppercase bg-gray-50 text-gray-400 hover:bg-red-50 hover:text-red-500 transition-all">
             <LogOut size={14} /><span>Thoát chế độ {isAdmin ? 'GV' : 'HS'}</span>
          </button>
        </div>
      </aside>
      <main className="flex-1 flex flex-col min-w-0 relative bg-white">
        {selectedNode ? (
          <>
            <header className="px-8 py-4 border-b border-gray-50 flex justify-between items-center h-20 shrink-0 bg-white/80 backdrop-blur-md z-10">
                <div className="flex items-center space-x-4 min-w-0">
                    <div className={`p-2.5 rounded-xl shrink-0 ${selectedNode.type === 'folder' ? 'bg-amber-50 text-amber-500' : 'bg-indigo-50 text-indigo-500'}`}>
                        {selectedNode.type === 'folder' ? <Book size={18}/> : <Globe size={18}/>}
                    </div>
                    <div className="min-w-0">
                      <h1 className="text-lg font-black text-gray-800 truncate tracking-tight uppercase">{selectedNode.title}</h1>
                      <p className="text-[9px] text-gray-400 font-mono truncate">{selectedNode.url || 'Chưa gắn link nội dung'}</p>
                    </div>
                </div>
                <div className="flex space-x-2 shrink-0">
                    {isAdmin && <button onClick={() => openEditNodeModal(selectedNode)} className="p-2.5 text-amber-600 bg-amber-50 rounded-xl hover:bg-amber-100 transition-all"><Pencil size={18} /></button>}
                    {selectedNode.url && <a href={selectedNode.url} target="_blank" rel="noreferrer" className="p-2.5 text-gray-400 bg-gray-50 rounded-xl hover:bg-gray-100"><Maximize2 size={18} /></a>}
                </div>
            </header>
            <div className="flex-1 bg-gray-100 relative overflow-hidden">
              {iframeLoading && (
                <div className="absolute inset-0 z-10 flex flex-col items-center justify-center bg-white/70 backdrop-blur-sm">
                  <Loader2 size={32} className="animate-spin text-indigo-500 mb-3" />
                  <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Đang kết nối bài học...</p>
                </div>
              )}
              {selectedNode.url ? (
                <iframe src={selectedNode.url} className="w-full h-full border-none shadow-inner bg-white" onLoad={() => setIframeLoading(false)} title={selectedNode.title} allowFullScreen />
              ) : (
                <div className="absolute inset-0 flex flex-col items-center justify-center text-gray-300 p-10 text-center">
                    <Globe size={60} className="mb-4 opacity-5" />
                    <p className="text-sm font-bold opacity-30 italic">Nội dung bài học chưa được chuẩn bị</p>
                    {isAdmin && <button onClick={() => openEditNodeModal(selectedNode)} className="mt-4 px-6 py-3 bg-amber-500 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg">Gắn link bài học ngay</button>}
                </div>
              )}
            </div>
          </>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center bg-gray-50/50">
            <div className="p-12 bg-white rounded-full shadow-2xl shadow-gray-200 border-8 border-gray-50"><Book size={80} className="text-indigo-100" /></div>
            <h2 className="mt-8 text-xl font-black uppercase tracking-tighter text-gray-300">Chọn bài học để bắt đầu</h2>
          </div>
        )}
      </main>
      <aside className="w-60 border-l border-gray-50 bg-gray-50/30 flex flex-col shrink-0">
        <div className="h-1/2 flex flex-col border-b border-gray-100 overflow-hidden">
          <div className="p-4 border-b border-gray-100 bg-white flex justify-between items-center sticky top-0 z-10">
            <h3 className="font-black text-[9px] text-gray-400 uppercase tracking-widest flex items-center"><LinkIcon size={12} className="mr-2 text-indigo-400" /> Tài liệu riêng</h3>
            {isAdmin && selectedNode && <button onClick={() => openResourceModal(false)} className="text-indigo-600 p-1.5 bg-indigo-50 rounded-lg"><Plus size={14} /></button>}
          </div>
          <div className="flex-1 overflow-y-auto p-3 space-y-2 custom-scrollbar">
            {selectedNode?.lessonResources.map(res => (
                <div key={res.id} className="group bg-white p-3 rounded-xl border border-gray-100 shadow-sm flex justify-between items-center hover:border-indigo-200 hover:shadow-md transition-all">
                  <a href={res.url} target="_blank" rel="noreferrer" className="text-[10px] text-indigo-600 font-bold truncate mr-2">{res.title}</a>
                  {isAdmin && <button onClick={() => setShowDeleteConfirm({ type: 'resource', id: res.id, isGlobal: false, title: res.title })} className="text-red-300 hover:text-red-500 opacity-0 group-hover:opacity-100"><Trash2 size={12} /></button>}
                </div>
            ))}
          </div>
        </div>
        <div className="h-1/2 flex flex-col bg-white overflow-hidden">
          <div className="p-4 border-b border-gray-100 bg-gray-50/50 flex justify-between items-center sticky top-0 z-10">
            <h3 className="font-black text-[9px] text-indigo-900 uppercase tracking-widest flex items-center"><Settings size={12} className="mr-2" /> Tài liệu chung</h3>
            {isAdmin && <button onClick={() => openResourceModal(true)} className="text-indigo-600 p-1.5 bg-white rounded-lg shadow-sm"><Plus size={14} /></button>}
          </div>
          <div className="flex-1 overflow-y-auto p-3 space-y-2 custom-scrollbar">
            {data.globalResources.map(res => (
                <div key={res.id} className="group bg-gray-50/80 p-3 rounded-xl border border-gray-100 flex justify-between items-center hover:bg-white transition-all">
                  <a href={res.url} target="_blank" rel="noreferrer" className="text-[10px] text-gray-700 font-bold truncate mr-2">{res.title}</a>
                  {isAdmin && <button onClick={() => setShowDeleteConfirm({ type: 'resource', id: res.id, isGlobal: true, title: res.title })} className="text-red-300 hover:text-red-500 opacity-0 group-hover:opacity-100"><Trash2 size={12} /></button>}
                </div>
            ))}
          </div>
        </div>
      </aside>
      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 3px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; }
        @keyframes shake { 0%, 100% { transform: translateX(0); } 25% { transform: translateX(-4px); } 75% { transform: translateX(4px); } }
        .animate-shake { animation: shake 0.2s ease-in-out 0s 2; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback } from 'react';
import { 
  Book, Link as LinkIcon, X, Pencil, Plus, Settings, Globe, Maximize2, Save, 
  Loader2, LogOut, GraduationCap, KeyRound, Trash2, AlertTriangle, Cloud, CloudCheck, CloudOff,
  ShieldCheck
} from 'lucide-react';
import { createClient } from '@supabase/supabase-js';
import { BookNode, NodeType, AppData, ResourceLink } from './types';
import { INITIAL_DATA } from './constants';
import TreeItem from './components/TreeItem';

// =========================================================================
// THÔNG TIN SUPABASE ĐÃ ĐƯỢC CẬP NHẬT TỪ ẢNH CỦA BẠN:
// =========================================================================
const SUPABASE_URL = 'https://ktottoplusantmadclpg.supabase.co';
const SUPABASE_ANON_KEY = 'sb_publishable_Fa4z8bEgByw3pGTJdvBqmQ_D_KeDGdl';
// =========================================================================

const supabase = createClient(SUPABASE_URL, SUPABASE_ANON_KEY);

const App: React.FC = () => {
  const [data, setData] = useState<AppData>(INITIAL_DATA);
  const [role, setRole] = useState<'none' | 'teacher' | 'student'>('none');
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [iframeLoading, setIframeLoading] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [cloudStatus, setCloudStatus] = useState<'connected' | 'error' | 'local'>('local');

  // Modal States
  const [showPassInput, setShowPassInput] = useState(false);
  const [teacherPass, setTeacherPass] = useState('');
  const [passError, setPassError] = useState(false);
  const [showNodeModal, setShowNodeModal] = useState(false);
  const [nodeModalData, setNodeModalData] = useState<{ id?: string; parentId: string | null; type: NodeType; title: string; url: string; }>({ parentId: null, type: 'lesson', title: '', url: '' });
  const [showResourceModal, setShowResourceModal] = useState(false);
  const [resourceModalData, setResourceModalData] = useState({ isGlobal: false, title: '', url: '' });
  const [showDeleteConfirm, setShowDeleteConfirm] = useState<{ type: 'node' | 'resource'; id: string; isGlobal?: boolean; title: string; } | null>(null);

  const fetchCloudData = useCallback(async () => {
    setIsSyncing(true);
    try {
      const { data: cloudRows, error } = await supabase
        .from('app_settings') 
        .select('data')
        .eq('id', 1) 
        .single();

      if (error) throw error;
      if (cloudRows?.data) {
        setData(cloudRows.data);
        setCloudStatus('connected');
      }
    } catch (err) {
      console.error('Fetch error:', err);
      setCloudStatus('error');
      const saved = localStorage.getItem('teacher_app_data_v7');
      if (saved) setData(JSON.parse(saved));
    } finally {
      setIsSyncing(false);
    }
  }, []);

  const saveToCloud = async (newData: AppData) => {
    localStorage.setItem('teacher_app_data_v7', JSON.stringify(newData));
    if (role !== 'teacher') return;

    setIsSyncing(true);
    try {
      const { error } = await supabase
        .from('app_settings')
        .upsert({ id: 1, data: newData });

      if (error) throw error;
      setCloudStatus('connected');
    } catch (err) {
      console.error('Save error:', err);
      setCloudStatus('error');
    } finally {
      setIsSyncing(false);
    }
  };

  useEffect(() => {
    fetchCloudData();
  }, [fetchCloudData]);

  const updateData = (newData: AppData) => {
    setData(newData);
    saveToCloud(newData);
  };

  const handleSelectNode = (id: string) => {
    setSelectedId(id);
    const node = data.nodes.find(n => n.id === id);
    if (node && node.url) setIframeLoading(true);
  };

  const saveNode = (e: React.FormEvent) => {
    e.preventDefault();
    if (!nodeModalData.title.trim()) return;
    let nextNodes = [...data.nodes];
    if (nodeModalData.id) {
      nextNodes = nextNodes.map(n => n.id === nodeModalData.id ? { ...n, title: nodeModalData.title, url: nodeModalData.url } : n);
    } else {
      const newNode: BookNode = {
        id: `node-${Date.now()}`,
        title: nodeModalData.title,
        type: nodeModalData.type,
        url: nodeModalData.url,
        parentId: nodeModalData.parentId,
        lessonResources: []
      };
      nextNodes.push(newNode);
      setSelectedId(newNode.id);
    }
    updateData({ ...data, nodes: nextNodes });
    setShowNodeModal(false);
  };

  const saveResource = (e: React.FormEvent) => {
    e.preventDefault();
    const { title, url, isGlobal } = resourceModalData;
    if (!title.trim() || !url.trim()) return;
    const newRes: ResourceLink = { id: `res-${Date.now()}`, title, url };
    if (isGlobal) {
      updateData({ ...data, globalResources: [...data.globalResources, newRes] });
    } else if (selectedId) {
      const nextNodes = data.nodes.map(n => n.id === selectedId ? { ...n, lessonResources: [...n.lessonResources, newRes] } : n);
      updateData({ ...data, nodes: nextNodes });
    }
    setShowResourceModal(false);
  };

  const executeDelete = () => {
    if (!showDeleteConfirm) return;
    const { type, id, isGlobal } = showDeleteConfirm;
    let nextData = { ...data };
    if (type === 'node') {
      const idsToDelete = new Set<string>();
      const collectIds = (targetId: string) => {
        idsToDelete.add(targetId);
        data.nodes.filter(n => n.parentId === targetId).forEach(child => collectIds(child.id));
      };
      collectIds(id);
      nextData.nodes = data.nodes.filter(n => !idsToDelete.has(n.id));
      if (selectedId && idsToDelete.has(selectedId)) setSelectedId(null);
    } else {
      if (isGlobal) {
        nextData.globalResources = data.globalResources.filter(r => r.id !== id);
      } else {
        nextData.nodes = data.nodes.map(n => n.id === selectedId ? { ...n, lessonResources: n.lessonResources.filter(r => r.id !== id) } : n);
      }
    }
    updateData(nextData);
    setShowDeleteConfirm(null);
  };

  const openAddNodeModal = (parentId: string | null, type: NodeType) => {
    setNodeModalData({ parentId, type, title: '', url: '' });
    setShowNodeModal(true);
  };

  const openEditNodeModal = (node: BookNode) => {
    setNodeModalData({ id: node.id, parentId: node.parentId, type: node.type, title: node.title, url: node.url });
    setShowNodeModal(true);
  };

  const openResourceModal = (isGlobal: boolean) => {
    setResourceModalData({ isGlobal, title: '', url: '' });
    setShowResourceModal(true);
  };

