/**
 * HÀM LẤY BIẾN MÔI TRƯỜNG TỐI ƯU CHO VERCEL + VITE
 */
const getEnv = (key: string): string | undefined => {
  try {
    // 1. Thử với Vite (Bắt buộc phải có VITE_ trên Vercel)
    const viteKey = `VITE_${key}`;
    const metaEnv = (import.meta as any).env;
    if (metaEnv && metaEnv[viteKey]) return metaEnv[viteKey];
    if (metaEnv && metaEnv[key]) return metaEnv[key];

    // 2. Dự phòng cho process.env
    if (typeof process !== 'undefined' && process.env && process.env[key]) return process.env[key];
    if (typeof process !== 'undefined' && process.env && process.env[viteKey]) return process.env[viteKey];

    // 3. Dự phòng cho window injection
    if (typeof (window as any)._env_ !== 'undefined' && (window as any)._env_[key]) return (window as any)._env_[key];
  } catch (e) {
    console.warn("Env access restricted");
  }
  return undefined;
};

// Cấu hình từ môi trường
const ENV_PWD = getEnv('TEACHER_PASSWORD');
