/**
 * HÀM LẤY BIẾN MÔI TRƯỜNG TỐI ƯU CHO VERCEL + VITE
 * Tìm kiếm cả tên gốc và tên có tiền tố VITE_
 */
const getEnv = (key: string): string | undefined => {
  try {
    const viteKey = `VITE_${key}`;
    const metaEnv = (import.meta as any).env;

    // 1. Ưu tiên hàng đầu: Biến của Vite (Dùng trên Vercel/Local)
    if (metaEnv && metaEnv[viteKey]) return metaEnv[viteKey];
    if (metaEnv && metaEnv[key]) return metaEnv[key];

    // 2. Dự phòng: process.env (Dùng trong môi trường Node.js truyền thống)
    if (typeof process !== 'undefined' && process.env) {
      if (process.env[viteKey]) return process.env[viteKey];
      if (process.env[key]) return process.env[key];
    }

    // 3. Dự phòng cuối: window injection
    if (typeof (window as any)._env_ !== 'undefined' && (window as any)._env_[key]) return (window as any)._env_[key];
  } catch (e) {
    console.warn("Lỗi truy cập môi trường:", e);
  }
  return undefined;
};

