interface TreeItemProps {
  node: BookNode;
  allNodes: BookNode[];
  selectedId: string | null;
  isAdmin: boolean;
  onSelect: (id: string) => void;
  onAdd: (parentId: string, type: NodeType) => void;
  onEdit: (node: BookNode) => void;
  onDelete: (id: string) => void;
  level: number;
}

const TreeItem: React.FC<TreeItemProps> = ({ 
  node, 
  allNodes, 
  selectedId, 
  isAdmin,
  onSelect, 
  onAdd, 
  onEdit, 
  onDelete,
  level 
}) => {
  const [isOpen, setIsOpen] = useState(true);

  const children = allNodes.filter(n => n.parentId === node.id);
  const isSelected = selectedId === node.id;

  return (
    <div className="select-none mb-1">
      <div 
        className={`group flex items-center py-2 px-2.5 rounded-xl cursor-pointer transition-all ${
          isSelected 
            ? 'bg-indigo-600 text-white shadow-lg' 
            : 'hover:bg-indigo-50 text-slate-600'
        }`}
        style={{ marginLeft: `${level * 0.5}rem` }}
        onClick={() => onSelect(node.id)}
      >
        <div className="flex items-center flex-1 min-w-0">
          {node.type === 'folder' ? (
            <button 
              onClick={(e) => { e.stopPropagation(); setIsOpen(!isOpen); }}
              className={`p-0.5 mr-0.5 rounded-md transition-colors ${isSelected ? 'text-white/50 hover:text-white' : 'text-slate-400 hover:bg-slate-200'}`}
            >
              {isOpen ? <ChevronDown size={12} strokeWidth={3} /> : <ChevronRight size={12} strokeWidth={3} />}
            </button>
          ) : (
            <div className="w-4 mr-0.5" />
          )}

          {node.type === 'folder' ? (
            <Folder size={14} className={`mr-1.5 shrink-0 ${isSelected ? 'text-white' : 'text-amber-500'}`} />
          ) : (
            <Globe size={14} className={`mr-1.5 shrink-0 ${isSelected ? 'text-white' : 'text-sky-500'}`} />
          )}

          <span className={`truncate text-[11px] tracking-tight leading-tight ${isSelected ? 'font-bold' : 'font-medium'}`}>{node.title}</span>
        </div>

        {isAdmin && (
          <div className="flex items-center space-x-0.5 ml-1 opacity-0 group-hover:opacity-100 transition-opacity">
            {node.type === 'folder' && (
              <button 
                onClick={(e) => { e.stopPropagation(); onAdd(node.id, 'lesson'); }}
                className={`p-1 rounded-lg ${isSelected ? 'hover:bg-white/20' : 'hover:bg-indigo-100 text-indigo-500'}`}
              >
                <Plus size={12} />
              </button>
            )}
            <button 
              onClick={(e) => { e.stopPropagation(); onEdit(node); }}
              className={`p-1 rounded-lg ${isSelected ? 'hover:bg-white/20' : 'hover:bg-amber-100 text-amber-600'}`}
            >
              <Pencil size={12} />
            </button>
            <button 
              onClick={(e) => { e.stopPropagation(); onDelete(node.id); }}
              className={`p-1 rounded-lg ${isSelected ? 'hover:bg-white/20' : 'hover:bg-red-100 text-red-500'}`}
            >
