              </div>
              <div className="flex gap-4 pt-4">
                <button type="button" onClick={()=>setShowNodeModal(false)} className="flex-1 font-bold text-slate-400 uppercase text-[10px] hover:text-slate-600 transition-colors">Hủy bỏ</button>
