                </div>
              </div>
              <div className="flex gap-4 pt-4">
                <button type="button" onClick={()=>setShowResourceModal(false)} className="flex-1 font-bold text-slate-400 uppercase text-[10px]">Đóng</button>
                <button type="submit" className="flex-1 py-4 bg-indigo-600 text-white rounded-xl font-bold uppercase text-[10px] shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all">Thêm ngay</button>
              </div>
           </form>
        </div>
      )}

      {showDeleteConfirm && (
        <div className="fixed inset-0 z-[400] bg-black/60 flex items-center justify-center p-6 backdrop-blur-sm animate-in zoom-in duration-200">
           <div className="bg-white p-10 rounded-[40px] shadow-2xl text-center w-full max-w-xs space-y-6">
              <div className="w-16 h-16 bg-red-50 text-red-500 rounded-full flex items-center justify-center mx-auto"><AlertTriangle size={32}/></div>
              <p className="font-bold text-xs text-slate-800 leading-relaxed">Xác nhận xóa vĩnh viễn <br/><span className="text-red-500 font-bold">"{showDeleteConfirm.title}"</span>?</p>
              <div className="flex gap-4">
                 <button onClick={()=>setShowDeleteConfirm(null)} className="flex-1 font-bold text-slate-400 uppercase text-[10px] hover:text-slate-600 transition-colors">Không xóa</button>
                 <button onClick={()=> {
                   if(showDeleteConfirm.type === 'node') { updateData({...data, nodes: data.nodes.filter(n=>n.id !== showDeleteConfirm.id)}); setSelectedId(null); }
                   else {
                     if(showDeleteConfirm.isGlobal) updateData({...data, globalResources: data.globalResources.filter(r=>r.id !== showDeleteConfirm.id)});
                     else if(selectedId) updateData({...data, nodes: data.nodes.map(n=> n.id===selectedId ? {...n, lessonResources: n.lessonResources.filter(r=>r.id!==showDeleteConfirm.id)} : n)});
                   }
                   setShowDeleteConfirm(null);
                 }} className="flex-1 py-4 bg-red-500 text-white rounded-xl font-bold uppercase text-[10px] shadow-lg shadow-red-100 hover:bg-red-600 transition-all active:scale-95">Xác nhận</button>
              </div>
           </div>
        </div>
      )}

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .katex { font-size: 1.1em; }
        iframe { border-radius: 12px; background: white; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState } from 'https://esm.sh/react@^19.2.3';
import { ChevronRight, ChevronDown, Folder, Globe, Plus, Pencil, Trash2 } from 'https://esm.sh/lucide-react@^0.562.0';
import { BookNode, NodeType } from '../types';

interface TreeItemProps {
  node: BookNode;
  allNodes: BookNode[];
  selectedId: string | null;
  isAdmin: boolean;
  onSelect: (id: string) => void;
  onAdd: (parentId: string, type: NodeType) => void;
  onEdit: (node: BookNode) => void;
  onDelete: (id: string) => void;
  level: number;
}

const TreeItem: React.FC<TreeItemProps> = ({ 
  node, 
  allNodes, 
  selectedId, 
  isAdmin,
  onSelect, 
  onAdd, 
  onEdit, 
  onDelete,
  level 
}) => {
  const [isOpen, setIsOpen] = useState(true);

  const children = allNodes.filter(n => n.parentId === node.id);
  const isSelected = selectedId === node.id;

  return (
    <div className="select-none mb-1">
      <div 
        className={`group flex items-center py-2 px-3 rounded-xl cursor-pointer transition-all ${
          isSelected 
            ? 'bg-indigo-600 text-white shadow-lg' 
            : 'hover:bg-indigo-50 text-slate-600'
        }`}
        style={{ marginLeft: `${level * 0.75}rem` }}
        onClick={() => onSelect(node.id)}
      >
        <div className="flex items-center flex-1 min-w-0">
          {node.type === 'folder' ? (
            <button 
              onClick={(e) => { e.stopPropagation(); setIsOpen(!isOpen); }}
              className={`p-0.5 mr-1 rounded-md transition-colors ${isSelected ? 'text-white/50 hover:text-white' : 'text-slate-400 hover:bg-slate-200'}`}
            >
              {isOpen ? <ChevronDown size={14} strokeWidth={3} /> : <ChevronRight size={14} strokeWidth={3} />}
            </button>
          ) : (
            <div className="w-5 mr-1" />
          )}

          {node.type === 'folder' ? (
            <Folder size={16} className={`mr-2 shrink-0 ${isSelected ? 'text-white' : 'text-amber-500'}`} />
          ) : (
            <Globe size={16} className={`mr-2 shrink-0 ${isSelected ? 'text-white' : 'text-sky-500'}`} />
          )}

          <span className={`truncate text-xs tracking-tight leading-tight ${isSelected ? 'font-semibold' : 'font-normal'}`}>{node.title}</span>
        </div>

        {isAdmin && (
          <div className="flex items-center space-x-0.5 ml-1 opacity-0 group-hover:opacity-100 transition-opacity">
            {node.type === 'folder' && (
              <button 
                onClick={(e) => { e.stopPropagation(); onAdd(node.id, 'lesson'); }}
                className={`p-1 rounded-lg ${isSelected ? 'hover:bg-white/20' : 'hover:bg-indigo-100 text-indigo-500'}`}
              >
                <Plus size={14} />
              </button>
            )}
            <button 
              onClick={(e) => { e.stopPropagation(); onEdit(node); }}
              className={`p-1 rounded-lg ${isSelected ? 'hover:bg-white/20' : 'hover:bg-amber-100 text-amber-600'}`}
            >
              <Pencil size={14} />
            </button>
            <button 
              onClick={(e) => { e.stopPropagation(); onDelete(node.id); }}
              className={`p-1 rounded-lg ${isSelected ? 'hover:bg-white/20' : 'hover:bg-red-100 text-red-500'}`}
            >
              <Trash2 size={14} />
            </button>
          </div>
        )}
      </div>

      {node.type === 'folder' && isOpen && children.length > 0 && (
        <div className="mt-1">
          {children.map(child => (
            <TreeItem 
              key={child.id}
              node={child}
              allNodes={allNodes}
              selectedId={selectedId}
              isAdmin={isAdmin}
              onSelect={onSelect}
              onAdd={onAdd}
              onEdit={onEdit}
              onDelete={onDelete}
              level={level + 1}
            />
          ))}
        </div>
      )}
    </div>
  );
};

