const renderLatex = (text: string) => {
  if (!text) return null;
  const parts = text.split(/(\$[^\$]+\$)/g);
  return parts.map((part, i) => {
    if (part.startsWith('$') && part.endsWith('$')) {
      const math = part.slice(1, -1);
      try {
        const html = katex.renderToString(math, { throwOnError: false });
        return <span key={i} dangerouslySetInnerHTML={{ __html: html }} />;
      } catch (e) { return <span key={i}>{part}</span>; }
    }
    return <span key={i}>{part}</span>;
  });
};

// --- CORE APP COMPONENT ---
const App: React.FC = () => {
  const [data, setData] = useState<AppData>(INITIAL_DATA);
  const [isSyncing, setIsSyncing] = useState(false);
  const [visitorCount, setVisitorCount] = useState<number>(0);
  const navigate = useNavigate();

  const handleVisitorCount = useCallback(async () => {
    try {
      // Lấy số lượng hiện tại từ bản ghi đặc biệt có id=99 (dành cho stats)
      const { data: stats, error: fetchError } = await supabase
        .from('app_settings')
        .select('data')
        .eq('id', 99)
        .single();

      let currentCount = stats?.data?.visitorCount || 0;

      // Kiểm tra session để tránh tăng lượt ảo khi reload
      const sessionVisited = sessionStorage.getItem('v_visited');

      if (!sessionVisited) {
        currentCount += 1;
        await supabase.from('app_settings').upsert({ 
          id: 99, 
          data: { visitorCount: currentCount } 
        });
        sessionStorage.setItem('v_visited', 'true');
      }

      setVisitorCount(currentCount);
    } catch (err) {
      console.warn('Visitor tracking error');
    }
  }, []);

  const fetchCloudData = useCallback(async () => {
    setIsSyncing(true);
    try {
      const { data: cloudRows, error } = await supabase.from('app_settings').select('data').eq('id', 1).single();
      if (!error && cloudRows?.data) setData(cloudRows.data);
    } catch (err) { console.warn('Offline mode'); }
    finally { setIsSyncing(false); }
  }, []);

  useEffect(() => { 
    fetchCloudData(); 
    handleVisitorCount();
  }, [fetchCloudData, handleVisitorCount]);

  const updateData = async (newData: AppData) => {
    setData(newData);
    setIsSyncing(true);
    try {
      await supabase.from('app_settings').upsert({ id: 1, data: newData });
    } catch (err) { console.error('Cloud save error'); }
    finally { setIsSyncing(false); }
  };

  return (
    <Routes>
      <Route path="/" element={<LandingPage visitorCount={visitorCount} />} />
      <Route path="/teacher" element={
        <ProtectedRoute>
          <MainView isAdmin={true} data={data} updateData={updateData} isSyncing={isSyncing} visitorCount={visitorCount} />
        </ProtectedRoute>
      } />
      <Route path="/student" element={<MainView isAdmin={false} data={data} updateData={updateData} isSyncing={isSyncing} visitorCount={visitorCount} />} />
      <Route path="*" element={<Navigate to="/" replace />} />
    </Routes>
  );
};

