        {/* Previews */}
        <div className="space-y-2">
          {previewUrl && (
            <div className="relative inline-block animate-in zoom-in duration-200">
              <img src={previewUrl} className="h-20 w-20 object-cover rounded-xl border-2 border-indigo-100 shadow-md" />
