            className={`${darkMode ? 'bg-slate-900 border border-slate-800' : 'bg-white'} p-10 rounded-none shadow-2xl w-full max-w-md space-y-5 animate-in slide-in-from-bottom-10 border-t-4 border-indigo-600`}>
