import React, { useState } from 'https://esm.sh/react@^19.2.3';
import { X, BrainCircuit, Loader2, Trophy, ChevronLeft, ChevronRight, CheckCircle2, XCircle } from 'https://esm.sh/lucide-react@^0.562.0';
import { GoogleGenAI, Type } from "https://esm.sh/@google/genai";
import confetti from 'https://esm.sh/canvas-confetti';
import { QuizQuestion } from '../types';
import { renderLatex, getSafeEnv } from '../utils';

interface QuizModalProps {
  lessonTitle: string;
  onClose: () => void;
}

const QuizModal: React.FC<QuizModalProps> = ({ lessonTitle, onClose }) => {
  const [questions, setQuestions] = useState<QuizQuestion[]>([]);
  const [loading, setLoading] = useState(false);
  const [userAnswers, setUserAnswers] = useState<(number | null)[]>([]);
  const [showResults, setShowResults] = useState(false);
  const [currentIdx, setCurrentIdx] = useState(0);

  const generateQuiz = async () => {
    setLoading(true);
    const apiKey = getSafeEnv('API_KEY');
    if (!apiKey) { alert("Lỗi hệ thống: Không tìm thấy API_KEY."); onClose(); return; }
    try {
      const ai = new GoogleGenAI({ apiKey });
      // Nâng cấp lên Pro để xử lý các câu hỏi Vật Lý phức tạp và JSON ổn định hơn
      const response = await ai.models.generateContent({
        model: "gemini-3-pro-preview",
        contents: `Tạo đúng 5 câu hỏi trắc nghiệm Vật Lý cho bài: "${lessonTitle}". 
        Cấu trúc độ khó: 
        - 1 câu Dễ (Nhận biết).
        - 1 câu Trung bình (Thông hiểu).
        - 2 câu Khá (Vận dụng).
        - 1 câu Khó (Vận dụng cao).
        Công thức nằm trong $...$. Xuất JSON chuẩn mảng 5 đối tượng.`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                question: { type: Type.STRING },
                options: { type: Type.ARRAY, items: { type: Type.STRING } },
                correctIndex: { type: Type.INTEGER },
                explanation: { type: Type.STRING }
              },
              required: ["question", "options", "correctIndex", "explanation"]
            }
          }
        }
      });
      const qData = JSON.parse(response.text || "[]");
      setQuestions(qData);
      setUserAnswers(new Array(qData.length).fill(null));
    } catch (e) { 
      console.error("AI Generation Error:", e);
      alert("Kết nối AI gặp sự cố tạm thời. Vui lòng thử lại sau vài giây."); 
      onClose(); 
    }
    finally { setLoading(false); }
  };

  React.useEffect(() => { generateQuiz(); }, []);

  const calculateScore = () => questions.filter((q, i) => userAnswers[i] === q.correctIndex).length;

  const handleFinish = () => {
    if (userAnswers.includes(null)) {
        alert("Em hãy chọn đáp án cho tất cả câu hỏi nhé!");
        return;
    }
    if (calculateScore() === questions.length) {
        confetti({ particleCount: 100, spread: 60, origin: { y: 0.7 } });
    }
    setShowResults(true);
  };

  return (
    <div className="fixed inset-0 z-[500] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm animate-in fade-in duration-300">
      {/* Modal thu hẹp max-w-2xl để gọn gàng như trang giấy */}
      <div className="bg-white dark:bg-slate-900 rounded-none shadow-2xl w-full max-w-2xl overflow-hidden flex flex-col max-h-[85vh] border border-slate-200 dark:border-slate-800">

        <header className="px-5 py-3 bg-slate-900 text-white flex justify-between items-center shrink-0 border-b border-white/5">
          <div className="flex items-center gap-2">
              <BrainCircuit size={16} className="text-indigo-400" />
              <h3 className="text-[10px] font-bold uppercase tracking-widest">Kiểm tra AI: {lessonTitle}</h3>
          </div>
          <button onClick={onClose} className="p-1 hover:bg-white/10 transition-all"><X size={16}/></button>
        </header>

        {/* Luôn bật thanh cuộn dọc (overflow-y-auto) để xử lý nội dung dài */}
        <div className="flex-1 overflow-y-auto custom-scrollbar bg-white dark:bg-slate-950 p-6 md:p-8">
          {loading ? (
            <div className="flex flex-col items-center justify-center h-48 text-center">
              <Loader2 className="animate-spin text-indigo-500 mb-4" size={20}/>
              <p className="text-[8px] uppercase font-bold text-slate-400 tracking-widest">AI đang soạn thảo đề thi...</p>
            </div>
          ) : (
            <div className="space-y-4">
              {!showResults ? (
                <div className="animate-in slide-in-from-bottom-2 duration-500">
                  <div className="flex items-center gap-2 mb-4">
