                    </span>
                  </div>

                  {/* Chữ text-sm (Word size 12) và font-light (mảnh) */}
                  <div className="text-sm font-light text-slate-800 dark:text-slate-100 leading-relaxed mb-6">
                    {renderLatex(questions[currentIdx]?.question)}
                  </div>

                  {/* Nén sát khoảng cách đáp án (space-y-1.5) */}
                  <div className="space-y-1.5 max-w-xl">
                    {questions[currentIdx]?.options.map((opt, i) => (
                      <button key={i} onClick={() => { const n = [...userAnswers]; n[currentIdx] = i; setUserAnswers(n); }} 
                        className={`w-full px-4 py-2.5 rounded-none border text-left transition-all flex items-center gap-3 ${userAnswers[currentIdx] === i ? 'bg-indigo-600 border-indigo-600 text-white shadow-md' : 'bg-white dark:bg-slate-800 border-slate-100 dark:border-slate-800 hover:border-indigo-400 text-slate-700 dark:text-slate-300'}`}>
                        <span className={`w-6 h-6 rounded-none flex items-center justify-center font-bold text-[10px] shrink-0 ${userAnswers[currentIdx] === i ? 'bg-white/20' : 'bg-slate-50 dark:bg-slate-700 text-indigo-500'}`}>{String.fromCharCode(65 + i)}</span>
                        <span className="text-sm font-light">{renderLatex(opt)}</span>
                      </button>
                    ))}
                  </div>
                </div>
              ) : (
                <div className="space-y-4 animate-in zoom-in-95 duration-500">
                  <div className="text-center mb-6">
                      <div className="inline-block p-2 bg-amber-500 text-white rounded-none mb-2"><Trophy size={24} /></div>
                      <h2 className="text-xl font-black text-slate-800 dark:text-white uppercase tracking-tighter">ĐIỂM: {calculateScore()}/{questions.length}</h2>
                  </div>

                  <div className="space-y-3">
                    {questions.map((q, i) => (
                      <div key={i} className={`p-4 rounded-none border-l-2 bg-slate-50 dark:bg-slate-900/50 ${userAnswers[i] === q.correctIndex ? 'border-green-500' : 'border-red-500'}`}>
                        <div className="flex items-start gap-3 mb-2">
                           {userAnswers[i] === q.correctIndex ? <CheckCircle2 size={14} className="text-green-500 mt-0.5 shrink-0"/> : <XCircle size={14} className="text-red-500 mt-0.5 shrink-0"/>}
                           <p className="text-sm font-light text-slate-800 dark:text-slate-200">{renderLatex(q.question)}</p>
                        </div>
                        <div className="ml-6 p-2 bg-white dark:bg-black/20 text-[10px] text-slate-500 font-light italic border-l border-slate-200">
                            <span className="font-bold text-indigo-500 uppercase not-italic mr-2">Giải thích:</span> {renderLatex(q.explanation)}
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}
        </div>

        <footer className="px-6 py-3 border-t bg-slate-50 dark:bg-slate-900 flex justify-between items-center shrink-0">
          {!showResults && !loading && (
            <>
              <button disabled={currentIdx===0} onClick={()=>setCurrentIdx(p=>p-1)} className={`font-bold text-[9px] uppercase flex items-center gap-1 ${currentIdx===0 ? 'text-slate-200' : 'text-slate-400 hover:text-indigo-600'}`}>
                <ChevronLeft size={12}/> Lùi
              </button>

              <div className="flex-1 h-0.5 bg-slate-200 dark:bg-slate-800 mx-6 max-w-[150px] relative overflow-hidden">
                 <div className="absolute top-0 left-0 h-full bg-indigo-600 transition-all duration-300" style={{width: `${((currentIdx + 1) / questions.length) * 100}%`}}></div>
              </div>

              <div className="flex gap-2">
                  {currentIdx === questions.length - 1 ? 
                    <button onClick={handleFinish} className="px-6 py-2 bg-indigo-600 text-white rounded-none font-bold uppercase text-[9px] hover:bg-indigo-700 transition-all">Nộp bài</button> :
                    <button onClick={()=>setCurrentIdx(p=>p+1)} className="px-6 py-2 bg-slate-800 text-white rounded-none font-bold text-[9px] uppercase hover:bg-black transition-all flex items-center gap-1">Tiếp <ChevronRight size={12}/></button>
                  }
              </div>
            </>
          )}
          {showResults && <button onClick={onClose} className="w-full py-2.5 bg-slate-900 text-white rounded-none font-bold uppercase text-[9px] hover:bg-black tracking-widest">Đóng kết quả</button>}
        </footer>
      </div>
      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 3px; height: 3px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 0px; }
        .katex { font-size: 1em; }
      `}</style>
    </div>
  );
};

