                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}
        </div>

        <footer className="px-10 py-6 border-t bg-white flex justify-between items-center shrink-0">
          {!showResults && !loading && !errorInfo && (
            <>
