        <div className="mb-8 p-5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 shadow-sm rounded-3xl">
            <Book size={48} className="text-indigo-600"/>
        </div>
        <h1 className="text-6xl font-black text-slate-900 dark:text-white uppercase mb-2 tracking-tighter">VẬT LÝ 11</h1>
