              </div>
            </form>
          )}
        </div>
      </div>
    </div>
  );
};

const MainView: React.FC<{ isAdmin: boolean; data: AppData; updateData: (d: AppData) => void; isSyncing: boolean; visitorCount: number; isDarkMode: boolean; setIsDarkMode: (v: boolean) => void }> = ({ isAdmin, data, updateData, isSyncing, visitorCount, isDarkMode, setIsDarkMode }) => {
