               <span className="text-[9px] font-bold text-slate-300 dark:text-slate-600 uppercase tracking-widest">{visitorCount} View</span>
             </div>
             <button onClick={()=>{if(isAdmin)sessionStorage.removeItem('teacher_auth'); navigate('/');}} className="flex items-center gap-1.5 text-[9px] font-black text-red-400 dark:text-red-500 uppercase tracking-widest hover:text-red-600 transition-colors">
