import React, { useState } from 'https://esm.sh/react@^19.2.3';
import { ChevronRight, ChevronDown, Folder, Globe, Plus, Pencil, Trash2 } from 'https://esm.sh/lucide-react@^0.562.0';
import { BookNode, NodeType } from '../types';

interface TreeItemProps {
  node: BookNode;
  allNodes: BookNode[];
  selectedId: string | null;
  isAdmin: boolean;
  onSelect: (id: string) => void;
  onAdd: (parentId: string, type: NodeType) => void;
  onEdit: (node: BookNode) => void;
  onDelete: (id: string) => void;
  level: number;
}

const TreeItem: React.FC<TreeItemProps> = ({ 
  node, 
  allNodes, 
  selectedId, 
  isAdmin,
  onSelect, 
  onAdd, 
  onEdit, 
  onDelete,
  level 
}) => {
  const [isOpen, setIsOpen] = useState(true);

  const children = allNodes.filter(n => n.parentId === node.id);
  const isSelected = selectedId === node.id;

  return (
    <div className="select-none mb-0.5">
      <div 
        className={`group flex items-center py-1.5 px-2 rounded-lg cursor-pointer transition-all ${
          isSelected 
            ? 'bg-indigo-600 text-white shadow-sm' 
            : 'hover:bg-slate-100 dark:hover:bg-slate-800 text-slate-600 dark:text-slate-400'
        }`}
        style={{ marginLeft: `${level * 0.75}rem` }}
        onClick={() => onSelect(node.id)}
      >
        <div className="flex items-center flex-1 min-w-0">
          <div className="w-5 flex items-center justify-center shrink-0">
            {node.type === 'folder' ? (
              <button 
                onClick={(e) => { e.stopPropagation(); setIsOpen(!isOpen); }}
                className={`p-0.5 rounded transition-colors ${isSelected ? 'text-white/70 hover:text-white' : 'text-slate-400 dark:text-slate-600 hover:bg-slate-200 dark:hover:bg-slate-700'}`}
              >
                {isOpen ? <ChevronDown size={12} strokeWidth={3} /> : <ChevronRight size={12} strokeWidth={3} />}
              </button>
            ) : null}
          </div>

          <div className="w-5 flex items-center justify-center shrink-0 mr-1.5">
            {node.type === 'folder' ? (
              <Folder size={14} className={`${isSelected ? 'text-white' : 'text-amber-500'}`} />
            ) : (
              <Globe size={14} className={`${isSelected ? 'text-white' : 'text-sky-500'}`} />
            )}
          </div>

          <span className={`truncate text-[11px] tracking-tight leading-tight ${isSelected ? 'font-medium' : 'font-normal'} ${!isSelected && 'dark:text-slate-300'}`}>
            {node.title}
          </span>
        </div>

        {isAdmin && (
          <div className="flex items-center space-x-0.5 ml-1 opacity-0 group-hover:opacity-100 transition-opacity shrink-0">
            {node.type === 'folder' && (
              <button 
                onClick={(e) => { e.stopPropagation(); onAdd(node.id, 'lesson'); }}
                className={`p-1 rounded ${isSelected ? 'hover:bg-white/20 text-white' : 'hover:bg-indigo-100 dark:hover:bg-indigo-900 text-indigo-500'}`}
              >
                <Plus size={10} />
              </button>
            )}
            <button 
              onClick={(e) => { e.stopPropagation(); onEdit(node); }}
              className={`p-1 rounded ${isSelected ? 'hover:bg-white/20 text-white' : 'hover:bg-amber-100 dark:hover:bg-amber-900 text-amber-600'}`}
            >
              <Pencil size={10} />
            </button>
            <button 
              onClick={(e) => { e.stopPropagation(); onDelete(node.id); }}
              className={`p-1 rounded ${isSelected ? 'hover:bg-white/20 text-white' : 'hover:bg-red-100 dark:hover:bg-red-900 text-red-500'}`}
            >
              <Trash2 size={10} />
            </button>
          </div>
        )}
      </div>

      {node.type === 'folder' && isOpen && children.length > 0 && (
        <div className="mt-0.5 ml-[9px] border-l border-slate-100 dark:border-slate-800 pl-1">
          {children.map(child => (
            <TreeItem 
              key={child.id}
              node={child}
              allNodes={allNodes}
              selectedId={selectedId}
              isAdmin={isAdmin}
              onSelect={onSelect}
              onAdd={onAdd}
              onEdit={onEdit}
              onDelete={onDelete}
              level={0}
            />
          ))}
        </div>
      )}
    </div>
  );
};

export default TreeItem;

import React from 'https://esm.sh/react@^19.2.3';
import { Plus, Pencil, Trash2, FileText, Cloud, Globe } from 'https://esm.sh/lucide-react@^0.562.0';
import { ResourceLink } from '../types';

interface ResourcesPanelProps {
  isAdmin: boolean;
  selectedId: string | null;
  lessonResources: ResourceLink[];
  globalResources: ResourceLink[];
  onAdd: (isGlobal: boolean) => void;
  onEdit: (res: ResourceLink, isGlobal: boolean) => void;
  onDelete: (id: string, title: string, isGlobal: boolean) => void;
}

const ResourceItem: React.FC<{ 
  r: ResourceLink; 
  isGlobal: boolean; 
  isAdmin: boolean;
