import React, { useState, useEffect } from 'https://esm.sh/react@^19.2.3';
import { X, BrainCircuit, Trophy, CheckCircle2, XCircle, AlertCircle, Send, Save, RefreshCw } from 'https://esm.sh/lucide-react@^0.562.0';
import { GoogleGenAI, Type } from "https://esm.sh/@google/genai";
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
import confetti from 'https://esm.sh/canvas-confetti';
import { QuizQuestion } from '../types';
import { renderLatex, getSafeEnv } from '../utils';

const SUPABASE_URL = 'https://ktottoplusantmadclpg.supabase.co';
const SUPABASE_ANON_KEY = 'sb_publishable_Fa4z8bEgByw3pGTJdvBqmQ_D_KeDGdl';
const supabase = createClient(SUPABASE_URL, SUPABASE_ANON_KEY);

interface QuizModalProps {
  nodeId: string;
  lessonTitle: string;
  isAdmin: boolean;
  onClose: () => void;
}

const QuizModal: React.FC<QuizModalProps> = ({ nodeId, lessonTitle, isAdmin, onClose }) => {
  const [questions, setQuestions] = useState<QuizQuestion[]>([]);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [errorInfo, setErrorInfo] = useState<{title: string, msg: string} | null>(null);
  const [userAnswers, setUserAnswers] = useState<(number | null)[]>([]);
  const [showResults, setShowResults] = useState(false);

  // Lấy dữ liệu từ CSDL
  const fetchFromDB = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase.from('app_settings').select('data').eq('id', parseInt(nodeId.replace(/\D/g, '')) + 1000).single();
      if (data?.data && Array.isArray(data.data)) {
        setQuestions(data.data);
        setUserAnswers(new Array(data.data.length).fill(null));
      } else if (!isAdmin) {
        setErrorInfo({ title: "Chưa có bài tập", msg: "Giáo viên chưa soạn bài tập cho mục này." });
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchFromDB();
  }, [nodeId]);

  const generateQuiz = async () => {
    setLoading(true);
    setErrorInfo(null);
    const apiKey = getSafeEnv('API_KEY');

    if (!apiKey) {
      setErrorInfo({ title: "Lỗi cấu hình", msg: "Vui lòng thiết lập API Key." });
      setLoading(false);
      return;
    }

    try {
      const ai = new GoogleGenAI({ apiKey });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Tạo 5 câu trắc nghiệm Vật lý 11 cho bài: "${lessonTitle}". 
        Yêu cầu: Công thức dùng ký hiệu $...$. Trả về JSON array chuẩn.`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                question: { type: Type.STRING },
                options: { type: Type.ARRAY, items: { type: Type.STRING } },
                correctIndex: { type: Type.INTEGER },
                explanation: { type: Type.STRING }
              },
              required: ["question", "options", "correctIndex", "explanation"]
            }
          }
        }
      });

      const qData = JSON.parse(response.text || "[]");
      setQuestions(qData);
      setUserAnswers(new Array(qData.length).fill(null));
    } catch (e: any) { 
      setErrorInfo({ title: "Lỗi kết nối", msg: "Không thể khởi tạo bài tập lúc này." });
    } finally { setLoading(false); }
  };

  const saveToDB = async () => {
    if (questions.length === 0) return;
    setSaving(true);
    try {
      const dbId = parseInt(nodeId.replace(/\D/g, '')) + 1000;
      await supabase.from('app_settings').upsert({ id: dbId, data: questions });
      alert("Đã lưu bài tập vào CSDL thành công!");
    } catch (e) {
      alert("Lỗi khi lưu dữ liệu.");
