  const getDbId = () => parseInt(nodeId.replace(/\D/g, '')) + 1000;

  // Lấy dữ liệu từ CSDL
  const fetchFromDB = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase.from('app_settings').select('data').eq('id', getDbId()).single();
      if (data?.data && Array.isArray(data.data)) {
        setQuestions(data.data);
        setDbQuestions(data.data);
        setUserAnswers(new Array(data.data.length).fill(null));
        setIsAiMode(false);
      } else {
        setQuestions([]);
        setDbQuestions([]);
        if (!isAdmin) {
